cd /workspace && cat > /tmp/summ.py <<'EOF'
import json
d=json.load(open('contracts/openapi.contract.json'))
def compact(s, ind=0):
    pad='  '*ind
    if '$ref' in s: return s['$ref'].split('/')[-1]
    if 'allOf' in s: return 'allOf['+','.join(compact(x) for x in s['allOf'])+']'
    if 'oneOf' in s: return 'oneOf['+','.join(compact(x) for x in s['oneOf'])+']'
    if 'anyOf' in s: return 'anyOf['+','.join(compact(x) for x in s['anyOf'])+']'
    t=s.get('type')
    if t=='object':
        props=s.get('properties',{})
        req=set(s.get('required',[]))
        out='{'
        if not props:
            out+='additionalProperties:'+str(s.get('additionalProperties'))
        for k,v in props.items():
            out+='\n'+pad+'  '+k+('*' if k in req else '')+': '+compact(v,ind+1)
        out+='\n'+pad+'}' if props else '}'
        if s.get('additionalProperties') not in (False,None) and props: out+='+addl'
        return out
    if t=='array':
        return '['+compact(s.get('items',{}),ind)+']'
    extra=''
    if 'enum' in s: extra+=' enum='+json.dumps(s['enum'])
    if 'format' in s: extra+=' fmt='+s['format']
    for k in ('minimum','maximum','minLength','maxLength','minItems','maxItems','default','pattern','exclusiveMinimum'):
        if k in s: extra+=' %s=%s'%(k,s[k])
    if 'description' in s: extra+=' desc='+s['description'][:120]
    return str(t)+extra
for p, ops in d['paths'].items():
    for m, op in ops.items():
        print('='*80)
        print(m.upper(), p, op.get('operationId'), 'security=',op.get('security'))
        if op.get('description'): print('DESC:',op['description'])
        for prm in op.get('parameters',[]):
            print('PARAM', prm['in'], prm['name'], 'req=',prm.get('required'), compact(prm.get('schema',{})))
        rb=op.get('requestBody')
        if rb:
            print('REQBODY required=',rb.get('required'))
            for ct,c in rb['content'].items():
                print(' ',ct, compact(c['schema'],1))
        for code,r in op['responses'].items():
            sch=r.get('content',{}).get('application/json',{}).get('schema')
            if sch is None:
                print('RESP',code,'(no json)',r.get('content',{}).keys(), r.get('description'))
                continue
            if code.startswith('2'):
                print('RESP',code, compact(sch,1))
            else:
                codes=sch.get('properties',{}).get('code',{}).get('enum')
                print('RESP',code,'codes=',codes)
EOF
python3 /tmp/summ.py > /tmp/summary.txt; wc -l /tmp/summary.txt; sed -n 1,300p /tmp/summary.txt

