package app

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
)

// Session is the authenticated caller resolved from the bearer token.
type Session struct {
	Token              string
	UserID             string
	Username           string
	FullName           string
	Roles              []string
	ActiveRole         string
	Qualifications     []string
	Certifications     []Certification
	Active             bool
	AssignedLocationID *string
	Available          bool
}

func (s *Session) HasRole(role string) bool {
	for _, r := range s.Roles {
		if r == role {
			return true
		}
	}
	return false
}

// Req carries per-request state for operation handlers.
type Req struct {
	ctx    context.Context
	app    *App
	tx     pgx.Tx
	sess   *Session
	body   json.RawMessage
	now    time.Now
	op     string
	events []pendingEvent
	audits []auditEntry
}

type pendingEvent struct {
	Type       string
	EntityType string
	EntityID   string
	Payload    map[string]any
	Roles      []string
	UserIDs    []string
}

type opSpec struct {
	roles                 []string
	mutating              bool
	idempotencyRequired   bool
	idempotencyOptional   bool
	roleSelectionRequired bool
	allowUnselected       bool
	noAuth                bool
	successStatus         int
}

type opHandler func(r *Req) (any, error)

const (
	RoleAdministrator = "administrator"
	RoleDispatcher    = "dispatcher"
	RoleRequester     = "requester"
	RoleCollector     = "collection_professional"
	RoleCourier       = "delivery_partner"
	RoleNodeHandler   = "node_handler"
	RoleLaboratory    = "laboratory_team"
)

var allRoles = []string{RoleAdministrator, RoleDispatcher, RoleRequester, RoleCollector, RoleCourier, RoleNodeHandler, RoleLaboratory}
var workerRoles = []string{RoleCollector, RoleCourier, RoleNodeHandler, RoleLaboratory}
var opsRoles = []string{RoleAdministrator, RoleDispatcher}
var adminOnly = []string{RoleAdministrator}

func isValidRole(r string) bool {
	for _, x := range allRoles {
		if x == r {
			return true
		}
	}
	return false
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, e *APIError) {
	writeJSON(w, e.Status, map[string]string{"error": e.Message, "code": e.Code})
}

func writeData(w http.ResponseWriter, status int, data any) {
	writeJSON(w, status, map[string]any{"data": data})
}

// Router builds the HTTP handler serving the API, static frontend and map assets.
func (a *App) Router() http.Handler {
	mux := http.NewServeMux()

	mux.HandleFunc("/ready", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			writeError(w, apiErr(http.StatusMethodNotAllowed, "method_not_allowed", "use GET"))
			return
		}
		if a.Ready(r.Context()) {
			writeJSON(w, http.StatusOK, map[string]string{"status": "ready"})
			return
		}
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"status": "starting"})
	})

	a.registerOperations(mux)

	mapDir := a.cfg.MapAssetDir
	mux.Handle("/map-assets/", http.StripPrefix("/map-assets/", http.FileServer(http.Dir(mapDir))))

	static := a.cfg.StaticDir
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if strings.HasPrefix(r.URL.Path, "/api/") {
			writeError(w, errNotFound("unknown operation"))
			return
		}
		p := filepath.Join(static, filepath.Clean("/"+r.URL.Path))
		if st, err := os.Stat(p); err == nil && !st.IsDir() {
			http.ServeFile(w, r, p)
			return
		}
		http.ServeFile(w, r, filepath.Join(static, "index.html"))
	})
	return logMiddleware(mux)
}

func logMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		if strings.HasPrefix(r.URL.Path, "/api/") {
			log.Printf("%s %s %s", r.Method, r.URL.Path, time.Since(start).Round(time.Millisecond))
		}
	})
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if len(h) > 7 && strings.EqualFold(h[:7], "bearer ") {
		return strings.TrimSpace(h[7:])
	}
	return ""
}

func (a *App) authenticate(ctx context.Context, token string) (*Session, error) {
	if token == "" {
		return nil, errUnauthorized()
	}
	var s Session
	var certs []byte
	err := a.pool.QueryRow(ctx, `SELECT s.token, u.id, u.username, u.full_name, u.roles, s.active_role, u.qualifications, u.certifications, u.active, u.assigned_location_id, u.available
		FROM sessions s JOIN users u ON u.id = s.user_id WHERE s.token = $1`, token).
		Scan(&s.Token, &s.UserID, &s.Username, &s.FullName, &s.Roles, &s.ActiveRole, &s.Qualifications, &certs, &s.Active, &s.AssignedLocationID, &s.Available)
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, errUnauthorized()
	}
	if err != nil {
		return nil, err
	}
	if !s.Active {
		return nil, errUnauthorized()
	}
	_ = json.Unmarshal(certs, &s.Certifications)
	if len(s.Roles) == 1 && s.ActiveRole == "" {
		s.ActiveRole = s.Roles[0]
	}
	if s.ActiveRole != "" && !s.HasRole(s.ActiveRole) {
		s.ActiveRole = ""
	}
	return &s, nil
}

// handle wraps an operation with auth, role checks, body parsing, idempotency,
// transaction management and audit/event publication.
func (a *App) handle(mux *http.ServeMux, method, path, op string, spec opSpec, fn opHandler) {
	if spec.successStatus == 0 {
		spec.successStatus = http.StatusOK
	}
	mux.HandleFunc(path, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != method {
			writeError(w, apiErr(http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed"))
			return
		}
		ctx := r.Context()
		req := &Req{ctx: ctx, app: a, now: time.Now, op: op}

		if !spec.noAuth {
			sess, err := a.authenticate(ctx, bearerToken(r))
			if err != nil {
				a.respondError(w, req, err)
				return
			}
			req.sess = sess
			if perr := checkRole(sess, spec); perr != nil {
				a.auditOutside(ctx, sess, "permission_check", "operation", op, false, map[string]any{"code": perr.Code, "requiredRoles": spec.roles})
				writeError(w, perr)
				return
			}
		}

		if method == http.MethodPost {
			raw, err := io.ReadAll(io.LimitReader(r.Body, 4<<20))
			if err != nil {
				writeError(w, errInvalidJSON("cannot read body"))
				return
			}
			if len(bytes.TrimSpace(raw)) == 0 {
				raw = []byte("{}")
			}
			var probe map[string]json.RawMessage
			if err := json.Unmarshal(raw, &probe); err != nil {
				writeError(w, errInvalidJSON("request body must be a JSON object"))
				return
			}
			req.body = raw
		}

		// Idempotency replay / conflict detection.
		var idemKey string
		if spec.idempotencyRequired || spec.idempotencyOptional {
			var probe struct {
				IdempotencyKey *string `json:"idempotencyKey"`
			}
			_ = json.Unmarshal(req.body, &probe)
			if probe.IdempotencyKey != nil {
				idemKey = strings.TrimSpace(*probe.IdempotencyKey)
			}
			if spec.idempotencyRequired && idemKey == "" {
				a.respondError(w, req, errBadRequest("idempotency_required", "idempotencyKey is required"))
				return
			}
		}
		reqHash := hashBody(req.body)
		if idemKey != "" {
			var storedHash string
			var status int
			var resp []byte
			err := a.pool.QueryRow(ctx, `SELECT request_hash, status_code, response FROM idempotency_keys WHERE user_id=$1 AND operation=$2 AND idem_key=$3`,
				req.sess.UserID, op, idemKey).Scan(&storedHash, &status, &resp)
			if err == nil {
				if storedHash != reqHash {
					a.respondError(w, req, errConflict("idempotency_conflict", "idempotencyKey was already used with a different request"))
					return
				}
				w.Header().Set("Content-Type", "application/json")
				w.WriteHeader(status)
				_, _ = w.Write(resp)
				return
			} else if !errors.Is(err, pgx.ErrNoRows) {
				a.respondError(w, req, err)
				return
			}
		}

		if spec.mutating {
			a.mu.Lock()
			defer a.mu.Unlock()
		}
		tx, err := a.pool.Begin(ctx)
		if err != nil {
			a.respondError(w, req, err)
			return
		}
		req.tx = tx
		data, err := fn(req)
		if err != nil {
			_ = tx.Rollback(ctx)
			a.respondError(w, req, err)
			return
		}
		if err := req.flushAudits(); err != nil {
			_ = tx.Rollback(ctx)
			a.respondError(w, req, err)
			return
		}
		published, err := req.flushEvents()
		if err != nil {
			_ = tx.Rollback(ctx)
			a.respondError(w, req, err)
			return
		}
		envelope, _ := json.Marshal(map[string]any{"data": data})
		if idemKey != "" {
			if _, err := tx.Exec(ctx, `INSERT INTO idempotency_keys (user_id, operation, idem_key, request_hash, status_code, response) VALUES ($1,$2,$3,$4,$5,$6)`,
				req.sess.UserID, op, idemKey, reqHash, spec.successStatus, envelope); err != nil {
				_ = tx.Rollback(ctx)
				a.respondError(w, req, err)
				return
			}
		}
		if err := tx.Commit(ctx); err != nil {
			a.respondError(w, req, err)
			return
		}
		for _, ev := range published {
			a.hub.Publish(ev)
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(spec.successStatus)
		_, _ = w.Write(envelope)
	})
}

func checkRole(sess *Session, spec opSpec) *APIError {
	if len(spec.roles) == 0 {
		return nil
	}
	if sess.ActiveRole == "" {
		if spec.roleSelectionRequired {
			return errConflict("role_not_selected", "select an active role before performing this action")
		}
		for _, r := range sess.Roles {
			if containsStr(spec.roles, r) {
				return nil
			}
		}
		return errForbidden("your roles do not permit this action")
	}
	if containsStr(spec.roles, sess.ActiveRole) {
		return nil
	}
	return errForbidden("role " + sess.ActiveRole + " may not perform this action")
}

func containsStr(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

func hashBody(b []byte) string {
	var v any
	if err := json.Unmarshal(b, &v); err == nil {
		if m, ok := v.(map[string]any); ok {
			delete(m, "idempotencyKey")
		}
		if canon, err := json.Marshal(v); err == nil {
			b = canon
		}
	}
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

func (a *App) respondError(w http.ResponseWriter, req *Req, err error) {
	var ae *APIError
	if errors.As(err, &ae) {
		if req.sess != nil && ae.Status != http.StatusUnauthorized {
			a.auditOutside(req.ctx, req.sess, req.op, "operation", req.op, false, map[string]any{"code": ae.Code, "error": ae.Message})
		}
		writeError(w, ae)
		return
	}
	log.Printf("internal error in %s: %v", req.op, err)
	writeError(w, apiErr(http.StatusInternalServerError, "internal_error", "internal error"))
}

// parse decodes the request body strictly into v, rejecting unknown fields.
func (r *Req) parse(v any) error {
	dec := json.NewDecoder(bytes.NewReader(r.body))
	dec.DisallowUnknownFields()
	if err := dec.Decode(v); err != nil {
		return errInvalidJSON("invalid request body: " + err.Error())
	}
	return nil
}

func (r *Req) activeRole() string {
	if r.sess == nil {
		return ""
	}
	if r.sess.ActiveRole != "" {
		return r.sess.ActiveRole
	}
	if len(r.sess.Roles) > 0 {
		return r.sess.Roles[0]
	}
	return ""
}

func (r *Req) hasRole(role string) bool {
	return r.activeRole() == role
}

func (r *Req) isOps() bool {
	role := r.activeRole()
	return role == RoleAdministrator || role == RoleDispatcher
}

