	{Name: "Amber", Qualification: "amber", Container: "standard_vial", MinC: 15, MaxC: 30, Cooled: false, Batching: true},
	{Name: "Indigo", Qualification: "indigo", Container: "sealed_tube", MinC: 15, MaxC: 30, Cooled: false, Batching: true},
	{Name: "Frost", Qualification: "frost", Container: "cryo_vial", MinC: -25, MaxC: -10, Cooled: true, Batching: true},
	{Name: "Pulse", Qualification: "pulse", Container: "rapid_cartridge", MinC: 15, MaxC: 30, Cooled: false, Batching: false},
}

