package app

import (
	"context"
	"encoding/json"
	"errors"
	"time"

	"github.com/jackc/pgx/v5"
)

type Coordinate struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

func (c Coordinate) valid() bool {
	return c.Latitude >= -90 && c.Latitude <= 90 && c.Longitude >= -180 && c.Longitude <= 180
}

type Certification struct {
	Code      string     `json:"code"`
	Active    bool       `json:"active"`
	ExpiresAt *time.Time `json:"expiresAt,omitempty"`
}

type Capacity struct {
	CapacityUnits        int `json:"capacityUnits"`
	ReservedUnits        int `json:"reservedUnits"`
	AvailableUnits       int `json:"availableUnits"`
	CooledCapacityUnits  int `json:"cooledCapacityUnits"`
	CooledReservedUnits  int `json:"cooledReservedUnits"`
	CooledAvailableUnits int `json:"cooledAvailableUnits"`
}

func makeCapacity(cap, reserved, cooledCap, cooledReserved int) Capacity {
	return Capacity{CapacityUnits: cap, ReservedUnits: reserved, AvailableUnits: cap - reserved,
		CooledCapacityUnits: cooledCap, CooledReservedUnits: cooledReserved, CooledAvailableUnits: cooledCap - cooledReserved}
}

type FunctionStates struct {
	CollectionPoint bool `json:"collection_point"`
	TransferPoint   bool `json:"transfer_point"`
	Hub             bool `json:"hub"`
	Laboratory      bool `json:"laboratory"`
}

type Location struct {
	ID              string
	Name            string
	Lat, Lng        float64
	CoverageKm      float64
	HandlingMinutes int
	Active          bool
	Functions       FunctionStates
	CapacityUnits   int
	CooledCapacity  int
	Reserved        int
	CooledReserved  int
}

func (l *Location) capacity() Capacity {
	return makeCapacity(l.CapacityUnits, l.Reserved, l.CooledCapacity, l.CooledReserved)
}

func (l *Location) coord() Coordinate { return Coordinate{l.Lat, l.Lng} }

func (l *Location) toJSON() map[string]any {
	return map[string]any{
		"locationId": l.ID, "name": l.Name, "coordinate": l.coord(), "coverageKm": l.CoverageKm,
		"handlingMinutes": l.HandlingMinutes, "active": l.Active, "functions": l.Functions,
	}
}

const locationCols = `id, name, lat, lng, coverage_km, handling_minutes, active, fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory, capacity_units, cooled_capacity_units, reserved_units, cooled_reserved_units`

func scanLocation(row pgx.Row) (*Location, error) {
	var l Location
	err := row.Scan(&l.ID, &l.Name, &l.Lat, &l.Lng, &l.CoverageKm, &l.HandlingMinutes, &l.Active, &l.Functions.CollectionPoint, &l.Functions.TransferPoint, &l.Functions.Hub, &l.Functions.Laboratory, &l.CapacityUnits, &l.CooledCapacity, &l.Reserved, &l.CooledReserved)
	if err != nil {
		return nil, err
	}
	return &l, nil
}

func loadLocation(ctx context.Context, q queryer, id string) (*Location, error) {
	l, err := scanLocation(q.QueryRow(ctx, `SELECT `+locationCols+` FROM locations WHERE id=$1`, id))
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, nil
	}
	return l, err
}

func loadLocations(ctx context.Context, q queryer) (map[string]*Location, []*Location, error) {
	rows, err := q.Query(ctx, `SELECT `+locationCols+` FROM locations ORDER BY created_at, name`)
	if err != nil {
		return nil, nil, err
	}
	defer rows.Close()
	m := map[string]*Location{}
	var list []*Location
	for rows.Next() {
		l, err := scanLocation(rows)
		if err != nil {
			return nil, nil, err
		}
		m[l.ID] = l
		list = append(list, l)
	}
	return m, list, rows.Err()
}

type Connection struct {
	ID             string
	From, To       string
	TravelMinutes  int
	CostUnits      float64
	Cooled         bool
	Active         bool
	CapacityUnits  int
	CooledCapacity int
	Reserved       int
	CooledReserved int
}

func (c *Connection) capacity() Capacity {
	return makeCapacity(c.CapacityUnits, c.Reserved, c.CooledCapacity, c.CooledReserved)
}

const connectionCols = `id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, cooled_capacity_units, reserved_units, cooled_reserved_units`

func scanConnection(row pgx.Row) (*Connection, error) {
	var c Connection
	err := row.Scan(&c.ID, &c.From, &c.To, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active, &c.CapacityUnits, &c.CooledCapacity, &c.Reserved, &c.CooledReserved)
	if err != nil {
		return nil, err
	}
	return &c, nil
}

func loadConnection(ctx context.Context, q queryer, id string) (*Connection, error) {
	c, err := scanConnection(q.QueryRow(ctx, `SELECT `+connectionCols+` FROM connections WHERE id=$1`, id))
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, nil
	}
	return c, err
}

func loadConnections(ctx context.Context, q queryer) ([]*Connection, error) {
	rows, err := q.Query(ctx, `SELECT `+connectionCols+` FROM connections ORDER BY created_at`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var list []*Connection
	for rows.Next() {
		c, err := scanConnection(rows)
		if err != nil {
			return nil, err
		}
		list = append(list, c)
	}
	return list, rows.Err()
}

type SampleType struct {
	ID                         string   `json:"sampleTypeId"`
	Name                       string   `json:"name"`
	QualifiedCollectorRequired bool     `json:"qualifiedCollectorRequired"`
	RequiredQualification      string   `json:"requiredQualification"`
	ContainerType              string   `json:"containerType"`
	TemperatureMinC            float64  `json:"temperatureMinC"`
	TemperatureMaxC            float64  `json:"temperatureMaxC"`
	IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
	RequiresCooledRoute        bool     `json:"requiresCooledRoute"`
	BatchingAllowed            bool     `json:"batchingAllowed"`
}

const sampleTypeCols = `id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed`

func scanSampleType(row pgx.Row) (*SampleType, error) {
	var t SampleType
	err := row.Scan(&t.ID, &t.Name, &t.QualifiedCollectorRequired, &t.RequiredQualification, &t.ContainerType, &t.TemperatureMinC, &t.TemperatureMaxC, &t.IncompatibleSampleTypes, &t.RequiresCooledRoute, &t.BatchingAllowed)
	if err != nil {
		return nil, err
	}
	if t.IncompatibleSampleTypes == nil {
		t.IncompatibleSampleTypes = []string{}
	}
	return &t, nil
}

func loadSampleType(ctx context.Context, q queryer, id string) (*SampleType, error) {
	t, err := scanSampleType(q.QueryRow(ctx, `SELECT `+sampleTypeCols+` FROM sample_types WHERE id=$1`, id))
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, nil
	}
	return t, err
}

func loadSampleTypes(ctx context.Context, q queryer) (map[string]*SampleType, []*SampleType, error) {
