// qualifiedFor reports whether the user holds an active, unexpired certification
// or qualification matching the required code at the given time.
func (u *User) qualifiedFor(code string, at time.Time) bool {
	if code == "" {
		return true
	}
	for _, c := range u.Certifications {
		if c.Code == code && c.Active && (c.ExpiresAt == nil || c.ExpiresAt.After(at)) {
			return true
		}
	}
	return containsStr(u.Qualifications, code)
}

