func scanUser(row pgx.Row) (*User, error) {
	var u User
	var certs []byte
	err := row.Scan(&u.ID, &u.Username, &u.Email, &u.FullName, &u.Phone, &u.Roles, &u.Qualifications, &certs, &u.Active, &u.AssignedLocationID, &u.Available, &u.CapacityUnits, &u.PenaltyUntil, &u.LastOfferedAt, &u.LatestLat, &u.LatestLng, &u.LocationRecordedAt)
	if err != nil {
		return nil, err
	}
	u.Certifications = []Certification{}
	_ = json.Unmarshal(certs, &u.Certifications)
	if u.Roles == nil {
		u.Roles = []string{}
	}
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}
	return &u, nil
