func (u *User) hasRole(r string) bool { return containsStr(u.Roles, r) }

// qualifiedFor reports whether the user holds an active, unexpired certification
// or qualification matching the required code at the given time.
func (u *User) qualifiedFor(code string, at time.Time) bool {
	if code == "" {
		return true
	}
	for _, c := range u.Certifications {
		if c.Code == code && c.Active && (c.ExpiresAt == nil || c.ExpiresAt.After(at)) {
			return true
		}
	}
	return containsStr(u.Qualifications, code)
}

func (u *User) toJSON() map[string]any {
	return map[string]any{
		"userId": u.ID, "username": u.Username, "email": u.Email, "fullName": u.FullName, "phone": u.Phone,
		"roles": u.Roles, "qualifications": u.Qualifications, "certifications": u.Certifications, "active": u.Active,
	}
}

func (u *User) isWorker() bool {
	for _, r := range workerRoles {
		if u.hasRole(r) {
			return true
		}
	}
	return false
}

