package app

import (
	"errors"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
)

func (a *App) opAuthenticate(r *Req) (any, error) {
	var in struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	in.Username = strings.TrimSpace(in.Username)
	if in.Username == "" || in.Password == "" {
		return nil, errInvalidJSON("username and password are required")
	}
	var id, hash string
	var roles []string
	var active bool
	err := r.tx.QueryRow(r.ctx, `SELECT id, password_hash, roles, active FROM users WHERE username=$1`, in.Username).Scan(&id, &hash, &roles, &active)
	if errors.Is(err, pgx.ErrNoRows) || (err == nil && (!verifyPassword(hash, in.Password) || !active)) {
		a.auditOutside(r.ctx, nil, "sign_in", "user", in.Username, false, map[string]any{"username": in.Username, "reason": "invalid_credentials"})
		return nil, apiErr(401, "invalid_credentials", "invalid username or password")
	}
	if err != nil {
		return nil, err
	}
	activeRole := ""
	if len(roles) == 1 {
		activeRole = roles[0]
	}
	token := newToken()
	if _, err := r.tx.Exec(r.ctx, `INSERT INTO sessions (token, user_id, active_role) VALUES ($1,$2,$3)`, token, id, activeRole); err != nil {
		return nil, err
	}
	r.sess = &Session{Token: token, UserID: id, Username: in.Username, Roles: roles, ActiveRole: activeRole}
