		userAccessInput
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	if e := validateAccess(in.userAccessInput, true); e != nil {
		return nil, e
	}
	u, err := loadUser(r.ctx, r.tx, in.UserID)
	if err != nil {
		return nil, err
	}
	if u == nil {
		return nil, errNotFound("user not found")
	}
	if in.AssignedLocationID != nil {
		loc, err := loadLocation(r.ctx, r.tx, *in.AssignedLocationID)
		if err != nil {
			return nil, err
		}
		if loc == nil {
			return nil, errNotFound("assignedLocationId does not exist")
		}
	}
	if in.Qualifications == nil {
		in.Qualifications = u.Qualifications
	}
	if in.Certifications == nil {
		in.Certifications = u.Certifications
	}
	assigned := u.AssignedLocationID
	if in.AssignedLocationID != nil {
		assigned = in.AssignedLocationID
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE users SET roles=$2, qualifications=$3, certifications=$4, active=$5, assigned_location_id=$6, updated_at=now() WHERE id=$1`,
