			return nil, err
		}
	}
	a.requestOfferSweep()
	return map[string]any{"userId": updated.ID, "roles": updated.Roles, "qualifications": updated.Qualifications, "certifications": updated.Certifications, "active": updated.Active}, nil
}

func (a *App) opSetWorkerAvailability(r *Req) (any, error) {
	var in struct {
		WorkerID      string `json:"workerId"`
		Available     *bool  `json:"available"`
		CapacityUnits *int   `json:"capacityUnits"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	if in.Available == nil || in.CapacityUnits == nil {
		return nil, errInvalidJSON("available and capacityUnits are required")
	}
	if *in.CapacityUnits < 0 {
		return nil, errBadRequest("invalid_capacity", "capacityUnits must be >= 0")
	}
	if in.WorkerID != r.sess.UserID && !r.isOps() {
		return nil, errForbidden("workers may only change their own availability")
	}
	u, err := loadUser(r.ctx, r.tx, in.WorkerID)
	if err != nil {
		return nil, err
	}
	if u == nil {
		return nil, errNotFound("worker not found")
	}
	var active int
	if err := r.tx.QueryRow(r.ctx, `SELECT count(*) FROM assignments WHERE worker_id=$1 AND status NOT IN ('completed','cancelled','replaced','expired','pending','offered')`, u.ID).Scan(&active); err != nil {
		return nil, err
	}
	if *in.CapacityUnits < active {
		return nil, errConflict("capacity_reserved", "capacity cannot drop below the worker's in-progress assignments")
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE users SET available=$2, capacity_units=$3, updated_at=now() WHERE id=$1`, u.ID, *in.Available, *in.CapacityUnits); err != nil {
		return nil, err
	}
	r.audit("worker_availability_changed", "user", u.ID, map[string]any{"available": *in.Available, "capacityUnits": *in.CapacityUnits, "previousAvailable": u.Available, "previousCapacityUnits": u.CapacityUnits})
	r.emit("worker.availability", "worker", u.ID, map[string]any{"workerId": u.ID, "available": *in.Available, "capacityUnits": *in.CapacityUnits}, opsRoles, []string{u.ID})
	if !*in.Available {
		if err := a.releaseWorkerOffers(r, u.ID, "worker_unavailable"); err != nil {
			return nil, err
		}
	}
	a.requestOfferSweep()
	return map[string]any{"workerId": u.ID, "available": *in.Available, "capacityUnits": *in.CapacityUnits}, nil
}

// releaseWorkerOffers re-offers work that was offered to (but not yet in the
// hands of) a worker who became unavailable. Custody is never changed here.
func (a *App) releaseWorkerOffers(r *Req, workerID, reason string) error {
	list, err := loadAssignmentsWhere(r.ctx, r.tx, `worker_id=$1 AND status IN ('offered','accepted')`, workerID)
	if err != nil {
		return err
	}
	for _, as := range list {
		if _, err := r.tx.Exec(r.ctx, `UPDATE assignments SET status='pending', worker_id=NULL, offered_at=NULL, offer_expires_at=NULL, accepted_at=NULL, pending_since=$2, updated_at=now() WHERE id=$1`, as.ID, r.now); err != nil {
			return err
		}
		r.audit("assignment_released", "assignment", as.ID, map[string]any{"workerId": workerID, "reason": reason, "sampleId": as.sampleID(), "journeyId": as.JourneyID})
		if err := a.offerAssignment(r, as.ID); err != nil {
			return err
		}
	}
	return nil
}

func (a *App) opBootstrap(r *Req) (any, error) {
	u, err := loadUser(r.ctx, r.tx, r.sess.UserID)
	if err != nil {
		return nil, err
	}
	if u == nil {
		return nil, errNotFound("user not found")
	}
	role := r.sess.ActiveRole
	out := map[string]any{
		"user": map[string]any{
			"userId": u.ID, "username": u.Username, "fullName": u.FullName, "roles": u.Roles, "activeRole": role,
			"roleSelectionRequired": role == "",
		},
		"serverTime": r.now.Format(time.RFC3339Nano),
	}
	if role == RoleRequester {
		samples, err := loadSamplesWhere(r.ctx, r.tx, `r.requester_id=$1`, u.ID)
		if err != nil {
			return nil, err
		}
		items := []map[string]any{}
		for _, s := range samples {
			items = append(items, a.sampleSummary(r, s))
		}
		out["requesterSamples"] = items
	}
	if role == RoleAdministrator || role == RoleDispatcher {
		ops, err := a.operationsState(r, "")
		if err != nil {
			return nil, err
		}
		out["operations"] = ops
	}
	return out, nil
}

