	if err := a.bumpNetworkRevision(r); err != nil {
		return nil, err
	}
	if !*in.Active && c.Active {
		if _, err := a.replanForResource(r, "connection", c.ID, "connection_deactivated"); err != nil {
			return nil, err
		}
	}
	a.requestSnapshot()
