func (a *App) opConfigureCapacity(r *Req) (any, error) {
	var in struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       *int   `json:"capacityUnits"`
		CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	if in.CapacityUnits == nil {
		return nil, errInvalidJSON("capacityUnits is required")
	}
	cooled := 0
	if in.CooledCapacityUnits != nil {
		cooled = *in.CooledCapacityUnits
	}
	if *in.CapacityUnits < 0 || cooled < 0 {
		return nil, errBadRequest("invalid_capacity", "capacity units must be >= 0")
	}
	loc, err := loadLocation(r.ctx, r.tx, in.ResourceID)
	if err != nil {
		return nil, err
	}
	if loc != nil {
		if !r.isOps() {
			if r.sess.AssignedLocationID == nil || *r.sess.AssignedLocationID != loc.ID {
				return nil, errForbidden("you may only configure capacity for your assigned node or laboratory")
			}
		}
		if loc.Reserved > *in.CapacityUnits || loc.CooledReserved > cooled {
			return nil, errConflict("capacity_reserved", "capacity cannot be reduced below current reservations")
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE locations SET capacity_units=$2, cooled_capacity_units=$3, updated_at=now() WHERE id=$1`, loc.ID, *in.CapacityUnits, cooled); err != nil {
			return nil, err
		}
		r.audit("capacity_configured", "location", loc.ID, map[string]any{"capacityUnits": *in.CapacityUnits, "cooledCapacityUnits": cooled, "previous": loc.capacity()})
		r.emit("capacity.configured", "location", loc.ID, map[string]any{"resourceId": loc.ID, "capacityUnits": *in.CapacityUnits, "cooledCapacityUnits": cooled}, opsRoles, nil)
	} else {
		if !r.isOps() {
			return nil, errForbidden("only administrators may configure connection capacity")
		}
		c, err := loadConnection(r.ctx, r.tx, in.ResourceID)
		if err != nil {
			return nil, err
		}
		if c == nil {
			return nil, errBadRequest("invalid_capacity", "resourceId is not a location or connection")
		}
		if c.Reserved > *in.CapacityUnits || c.CooledReserved > cooled {
			return nil, errConflict("capacity_reserved", "capacity cannot be reduced below current reservations")
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE connections SET capacity_units=$2, cooled_capacity_units=$3, updated_at=now() WHERE id=$1`, c.ID, *in.CapacityUnits, cooled); err != nil {
			return nil, err
		}
		r.audit("capacity_configured", "connection", c.ID, map[string]any{"capacityUnits": *in.CapacityUnits, "cooledCapacityUnits": cooled, "previous": c.capacity()})
		r.emit("capacity.configured", "connection", c.ID, map[string]any{"resourceId": c.ID, "capacityUnits": *in.CapacityUnits, "cooledCapacityUnits": cooled}, opsRoles, nil)
	}
	if err := a.bumpNetworkRevision(r); err != nil {
		return nil, err
	}
	a.requestSnapshot()
	return map[string]any{"resourceId": in.ResourceID, "capacityUnits": *in.CapacityUnits, "cooledCapacityUnits": cooled}, nil
}

func (a *App) opConfigureLaboratoryAcceptance(r *Req) (any, error) {
	var in struct {
		LaboratoryID string `json:"laboratoryId"`
		SampleTypeID string `json:"sampleTypeId"`
		Accepts      *bool  `json:"accepts"`
	}
	if err := r.parse(&in); err != nil {
