package app

import (
	"context"
	"encoding/json"
	"log"
	"math"
	"time"
)

type ServiceabilityRegion struct {
	LocationID string  `json:"locationId"`
	Name       string  `json:"name"`
	Latitude   float64 `json:"latitude"`
	Longitude  float64 `json:"longitude"`
	CoverageKm float64 `json:"coverageKm"`
}

// ServiceabilitySnapshot is one complete, published serviceability-calculation version.
type ServiceabilitySnapshot struct {
	Version                    int64                  `json:"version"`
	Status                     string                 `json:"status"`
	ComputedAt                 time.Time              `json:"computedAt"`
	NetworkRevision            int64                  `json:"networkRevision"`
	Regions                    []ServiceabilityRegion `json:"regions"`
	ActiveCollectionPointCount int                    `json:"activeCollectionPointCount"`
}

func (a *App) currentSnapshot() *ServiceabilitySnapshot {
	a.svcMu.RLock()
	defer a.svcMu.RUnlock()
	return a.svcSnapshot
}

func (a *App) requestSnapshot() {
	select {
	case a.svcQueue <- struct{}{}:
	default:
	}
}

func (a *App) snapshotWorker() {
	for range a.svcQueue {
		// Wait for any in-flight mutation to commit so the new version reflects it.
		a.mu.Lock()
		a.mu.Unlock()
		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		if err := a.computeSnapshot(ctx); err != nil {
			log.Printf("serviceability snapshot failed: %v", err)
		}
		cancel()
	}
}

func (a *App) loadOrComputeSnapshot(ctx context.Context) error {
	return a.computeSnapshot(ctx)
}

// computeSnapshot builds a new complete version and atomically publishes it;
// readers keep seeing the previous version until the swap.
func (a *App) computeSnapshot(ctx context.Context) error {
	var revision int64
	if err := a.pool.QueryRow(ctx, `SELECT (value::text)::bigint FROM app_settings WHERE key='network_revision'`).Scan(&revision); err != nil {
		return err
	}
	_, locs, err := loadLocations(ctx, a.pool)
	if err != nil {
		return err
	}
	regions := []ServiceabilityRegion{}
	for _, l := range locs {
		if l.Active && l.Functions.CollectionPoint {
			regions = append(regions, ServiceabilityRegion{LocationID: l.ID, Name: l.Name, Latitude: l.Lat, Longitude: l.Lng, CoverageKm: math.Min(l.CoverageKm, 5)})
		}
	}
	snap := &ServiceabilitySnapshot{Status: "complete", NetworkRevision: revision, Regions: regions, ActiveCollectionPointCount: len(regions)}
	err = a.pool.QueryRow(ctx, `INSERT INTO serviceability_snapshots (status, network_revision, regions, active_collection_point_count) VALUES ('complete',$1,$2,$3) RETURNING version, computed_at`,
		revision, mustJSON(regions), len(regions)).Scan(&snap.Version, &snap.ComputedAt)
	if err != nil {
		return err
	}
	a.svcMu.Lock()
	a.svcSnapshot = snap
	a.svcMu.Unlock()
	return nil
}

func (s *ServiceabilitySnapshot) MarshalJSON() ([]byte, error) {
	type alias ServiceabilitySnapshot
	return json.Marshal((*alias)(s))
}

// haversineKm returns the great-circle distance between two coordinates.
func haversineKm(a, b Coordinate) float64 {
	const R = 6371.0
	toRad := func(d float64) float64 { return d * math.Pi / 180 }
	dLat := toRad(b.Latitude - a.Latitude)
	dLng := toRad(b.Longitude - a.Longitude)
	la1, la2 := toRad(a.Latitude), toRad(b.Latitude)
	h := math.Sin(dLat/2)*math.Sin(dLat/2) + math.Cos(la1)*math.Cos(la2)*math.Sin(dLng/2)*math.Sin(dLng/2)
	return 2 * R * math.Asin(math.Min(1, math.Sqrt(h)))
}

