package app

import (
	"strings"
	"time"
)

func parseTime(s string) (time.Time, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return time.Time{}, false
	}
	for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02T15:04:05", "2006-01-02 15:04:05Z07:00", "2006-01-02"} {
		if t, err := time.Parse(layout, s); err == nil {
			return t.UTC(), true
		}
	}
	return time.Time{}, false
}

// requiredTime parses a mandatory timestamp field.
func requiredTime(raw *string, field string) (time.Time, *APIError) {
	if raw == nil {
		return time.Time{}, errInvalidJSON(field + " is required")
	}
	t, ok := parseTime(*raw)
	if !ok {
		return time.Time{}, errBadRequest("invalid_time", field+" must be an RFC 3339 timestamp")
	}
	return t, nil
}

func optionalTime(raw *string, field string) (*time.Time, *APIError) {
	if raw == nil || strings.TrimSpace(*raw) == "" {
		return nil, nil
	}
	t, ok := parseTime(*raw)
	if !ok {
		return nil, errBadRequest("invalid_time", field+" must be an RFC 3339 timestamp")
	}
	return &t, nil
}

type requestInput struct {
	RequesterID             *string     `json:"requesterId"`
	Origin                  *Coordinate `json:"origin"`
	OriginType              string      `json:"originType"`
	OriginNodeID            *string     `json:"originNodeId"`
	RequestedAt             *string     `json:"requestedAt"`
	DeliveryDeadline        *string     `json:"deliveryDeadline"`
	EarliestCollectionAt    *string     `json:"earliestCollectionAt"`
	LatestCollectionAt      *string     `json:"latestCollectionAt"`
	SampleTypeID            string      `json:"sampleTypeId"`
	ContainerType           *string     `json:"containerType"`
	TemperatureMinC         *float64    `json:"temperatureMinC"`
	TemperatureMaxC         *float64    `json:"temperatureMaxC"`
	IncompatibleSampleTypes []string    `json:"incompatibleSampleTypes"`
	IdempotencyKey          *string     `json:"idempotencyKey"`
}

type parsedRequest struct {
	Origin       Coordinate
	OriginType   string
	OriginNode   *Location
	RequestedAt  time.Time
	Deadline     time.Time
	Earliest     time.Time
	Latest       time.Time
	SampleType   *SampleType
	Container    string
	MinC, MaxC   float64
	Incompatible []string
}

// validateRequest applies the shared validation rules for serviceability
// checks, collection requests and pre-sealed ingestion.
func (a *App) validateRequest(r *Req, in *requestInput, defaultOriginType string, allowHome bool, needHandling bool) (*parsedRequest, error) {
	p := &parsedRequest{}
	if in.Origin == nil {
		return nil, errBadRequest("invalid_origin", "origin is required")
	}
	if !in.Origin.valid() {
		return nil, errBadRequest("invalid_origin", "origin coordinate out of range")
	}
	p.Origin = *in.Origin
	p.OriginType = in.OriginType
	if p.OriginType == "" {
		p.OriginType = defaultOriginType
	}
	switch p.OriginType {
	case "home":
		if !allowHome {
			return nil, errBadRequest("invalid_origin_type", "pre-sealed samples cannot originate from a home")
		}
	case "clinic", "node":
	default:
		return nil, errBadRequest("invalid_origin_type", "originType must be home, clinic or node")
	}
	var e *APIError
	if p.RequestedAt, e = requiredTime(in.RequestedAt, "requestedAt"); e != nil {
		return nil, e
	}
	if p.Deadline, e = requiredTime(in.DeliveryDeadline, "deliveryDeadline"); e != nil {
		return nil, e
	}
	if !p.Deadline.After(p.RequestedAt) {
		return nil, errBadRequest("invalid_deadline", "deliveryDeadline must be after requestedAt")
	}
	earliest, e := optionalTime(in.EarliestCollectionAt, "earliestCollectionAt")
	if e != nil {
		return nil, e
	}
	latest, e := optionalTime(in.LatestCollectionAt, "latestCollectionAt")
	if e != nil {
		return nil, e
	}
	p.Earliest = p.RequestedAt
	if earliest != nil {
		p.Earliest = *earliest
	}
	p.Latest = p.Deadline
	if latest != nil {
		p.Latest = *latest
	}
	if p.Latest.Before(p.Earliest) {
		return nil, errBadRequest("invalid_collection_window", "latestCollectionAt must not be before earliestCollectionAt")
	}
	if p.Latest.After(p.Deadline) {
		return nil, errBadRequest("invalid_collection_window", "the collection window must close before the delivery deadline")
	}
	if p.Earliest.Before(p.RequestedAt) {
		return nil, errBadRequest("invalid_collection_window", "earliestCollectionAt must not be before requestedAt")
	}
	if in.SampleTypeID == "" {
		return nil, errInvalidJSON("sampleTypeId is required")
	}
	st, err := loadSampleType(r.ctx, r.tx, in.SampleTypeID)
	if err != nil {
		return nil, err
	}
	if st == nil {
		return nil, errNotFound("sample type not found")
	}
	p.SampleType = st
	if p.OriginType == "node" {
		if in.OriginNodeID == nil || *in.OriginNodeID == "" {
			return nil, errBadRequest("invalid_origin", "originNodeId is required for a node origin")
		}
		loc, err := loadLocation(r.ctx, r.tx, *in.OriginNodeID)
		if err != nil {
			return nil, err
		}
		if loc == nil {
			return nil, errNotFound("origin node not found")
		}
		if !loc.Active {
			return nil, errBadRequest("invalid_origin_state", "origin node is inactive")
		}
		p.OriginNode = loc
	} else if in.OriginNodeID != nil && *in.OriginNodeID != "" {
		loc, err := loadLocation(r.ctx, r.tx, *in.OriginNodeID)
		if err != nil {
			return nil, err
		}
		if loc == nil {
			return nil, errNotFound("origin node not found")
		}
		if !loc.Active {
			return nil, errBadRequest("invalid_origin_state", "origin node is inactive")
		}
		p.OriginNode = loc
	}
	if needHandling {
		if in.ContainerType == nil || in.TemperatureMinC == nil || in.TemperatureMaxC == nil {
			return nil, errInvalidJSON("containerType, temperatureMinC and temperatureMaxC are required")
		}
		p.Container = *in.ContainerType
		p.MinC, p.MaxC = *in.TemperatureMinC, *in.TemperatureMaxC
		if p.MinC > p.MaxC {
			return nil, errBadRequest("handling_mismatch", "temperatureMinC must not exceed temperatureMaxC")
		}
		if !strings.EqualFold(strings.TrimSpace(p.Container), st.ContainerType) {
			return nil, errBadRequest("handling_mismatch", "containerType does not match the sample type's required container "+st.ContainerType)
		}
		if p.MinC < st.TemperatureMinC || p.MaxC > st.TemperatureMaxC {
			return nil, errBadRequest("handling_mismatch", "temperature range must lie within the sample type's allowed range")
		}
		p.Incompatible = in.IncompatibleSampleTypes
		if p.Incompatible == nil {
			p.Incompatible = []string{}
		}
		for _, id := range p.Incompatible {
			t, err := loadSampleType(r.ctx, r.tx, id)
			if err != nil {
				return nil, err
			}
			if t == nil {
				return nil, errBadRequest("handling_mismatch", "incompatible sample type "+id+" does not exist")
			}
		}
	}
	return p, nil
}

func (p *parsedRequest) planInput() *planInput {
	in := &planInput{Origin: p.Origin, OriginType: p.OriginType, SampleType: p.SampleType, StartAt: p.Earliest, Deadline: p.Deadline, Units: 1}
	if p.OriginNode != nil {
		in.OriginNodeID = strPtr(p.OriginNode.ID)
		if p.OriginType == "node" {
			in.StartLocationID = strPtr(p.OriginNode.ID)
		}
	}
