package app

import (
	"context"
	"log"
	"time"
)

func (a *App) opAcceptAssignment(r *Req) (any, error) {
	var in struct {
		AssignmentID string `json:"assignmentId"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	as, err := loadAssignment(r.ctx, r.tx, in.AssignmentID, true)
	if err != nil {
		return nil, err
	}
	if as == nil {
		return nil, errNotFound("assignment not found")
	}
	if as.finished() {
		return nil, errConflict("assignment_inactive", "assignment is no longer active")
	}
	if as.Status != "offered" && as.Status != "pending" {
		if as.WorkerID != nil && *as.WorkerID == r.sess.UserID {
			return nil, errConflict("offer_not_available", "assignment was already accepted")
		}
		return nil, errConflict("assignment_taken", "assignment is held by another worker")
	}
	if as.Status == "pending" || as.WorkerID == nil {
		return nil, errConflict("offer_not_offered", "assignment has not been offered to you")
	}
	if *as.WorkerID != r.sess.UserID {
		return nil, errConflict("offer_not_available", "assignment is offered to a different worker")
	}
	if as.OfferExpiresAt != nil && as.OfferExpiresAt.Before(r.now) {
		return nil, errConflict("offer_not_available", "the offer has expired")
	}
	role := map[string]string{"collection": RoleCollector, "transport": RoleCourier, "node": RoleNodeHandler, "laboratory": RoleLaboratory}[as.Kind]
	if r.activeRole() != role {
		return nil, apiErr(403, "ineligible_worker", "this assignment requires the "+role+" role")
	}
	u, err := loadUser(r.ctx, r.tx, r.sess.UserID)
	if err != nil {
		return nil, err
	}
	if !u.Available {
		return nil, errConflict("worker_unavailable", "you are marked unavailable")
	}
	if as.Kind == "collection" && !u.qualifiedFor(as.RequiredQualification, r.now) {
		return nil, apiErr(403, "ineligible_worker", "you lack the qualification "+as.RequiredQualification)
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE assignments SET status='accepted', accepted_at=$2, offer_expires_at=NULL, updated_at=now() WHERE id=$1`, as.ID, r.now); err != nil {
		return nil, err
	}
	r.audit("assignment_accepted", "assignment", as.ID, map[string]any{"workerId": u.ID, "kind": as.Kind, "journeyId": as.JourneyID, "sampleId": as.sampleID(), "sampleIds": as.SampleIDs})
	r.emit("assignment.accepted", "assignment", as.ID, map[string]any{"assignmentId": as.ID, "workerId": u.ID, "kind": as.Kind, "sampleId": as.sampleID()}, opsRoles, []string{u.ID})
	return map[string]any{"assignmentId": as.ID, "workerId": u.ID, "status": "accepted"}, nil
}

func (a *App) opDeclineAssignment(r *Req) (any, error) {
	var in struct {
		AssignmentID string  `json:"assignmentId"`
		Reason       string  `json:"reason"`
		DeclinedAt   *string `json:"declinedAt"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	declinedAt := r.now
	if t, e := optionalTime(in.DeclinedAt, "declinedAt"); e != nil {
		return nil, e
	} else if t != nil {
		declinedAt = *t
	}
	as, err := loadAssignment(r.ctx, r.tx, in.AssignmentID, true)
	if err != nil {
		return nil, err
	}
	if as == nil {
		return nil, errNotFound("assignment not found")
	}
	if as.Status != "offered" || as.WorkerID == nil || *as.WorkerID != r.sess.UserID {
		return nil, errConflict("offer_not_available", "no open offer for this assignment is addressed to you")
	}
	if err := a.declineOffer(r, as, r.sess.UserID, "declined", in.Reason, declinedAt); err != nil {
		return nil, err
	}
	// Repeated declines lower priority for a limited time, never permanently.
	var recent int
	if err := r.tx.QueryRow(r.ctx, `SELECT count(*) FROM audit_log WHERE action='assignment_declined' AND actor_id=$1 AND occurred_at > $2`, r.sess.UserID, r.now.Add(-1*time.Hour)).Scan(&recent); err != nil {
		return nil, err
	}
	if recent+1 >= a.cfg.DeclinePenaltyCount {
		if _, err := r.tx.Exec(r.ctx, `UPDATE users SET penalty_until=$2 WHERE id=$1`, r.sess.UserID, r.now.Add(a.cfg.DeclinePenalty)); err != nil {
			return nil, err
		}
	}
	after, err := loadAssignment(r.ctx, r.tx, as.ID, false)
	if err != nil {
		return nil, err
	}
	out := map[string]any{"assignmentId": as.ID, "status": "pending", "declinedBy": r.sess.UserID, "declinedAt": declinedAt}
	if after.Status == "offered" && after.WorkerID != nil {
		out["reofferedTo"] = *after.WorkerID
	}
	return out, nil
}

// declineOffer records a decline (explicit or by timeout) and re-offers the work.
func (a *App) declineOffer(r *Req, as *Assignment, workerID, how, reason string, at time.Time) error {
	if _, err := r.tx.Exec(r.ctx, `UPDATE assignments SET status='pending', worker_id=NULL, offered_at=NULL, offer_expires_at=NULL, declined_worker_ids=array_append(declined_worker_ids,$2::uuid), pending_since=COALESCE(pending_since,$3), updated_at=now() WHERE id=$1`, as.ID, workerID, at); err != nil {
		return err
	}
	action := "assignment_declined"
	if how == "expired" {
		action = "offer_expired"
	}
	r.audits = append(r.audits, auditEntry{ActorID: workerID, Role: map[string]string{"collection": RoleCollector, "transport": RoleCourier, "node": RoleNodeHandler, "laboratory": RoleLaboratory}[as.Kind], Action: action, EntityType: "assignment", EntityID: as.ID, Success: true, OccurredAt: at,
		Details: map[string]any{"workerId": workerID, "reason": reason, "kind": as.Kind, "journeyId": as.JourneyID, "sampleId": as.sampleID(), "sampleIds": as.SampleIDs}})
	r.emit("assignment.declined", "assignment", as.ID, map[string]any{"assignmentId": as.ID, "workerId": workerID, "how": how}, opsRoles, []string{workerID})
	return a.offerAssignment(r, as.ID)
}

var transportOrder = map[string]int{"accepted": 0, "at_pickup": 1, "picked_up": 2, "in_transit": 3, "arrived": 4, "delivered": 5}
var nodeOrder = map[string]int{"accepted": 0, "in_progress": 1, "completed": 2}

func (a *App) opUpdateAssignmentProgress(r *Req) (any, error) {
	var in struct {
		AssignmentID string  `json:"assignmentId"`
		Status       string  `json:"status"`
		OccurredAt   *string `json:"occurredAt"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	at, e := requiredTime(in.OccurredAt, "occurredAt")
	if e != nil {
		return nil, e
	}
	valid := map[string]bool{"at_pickup": true, "picked_up": true, "in_transit": true, "arrived": true, "delivered": true, "in_progress": true, "completed": true}
	if !valid[in.Status] {
		return nil, errInvalidJSON("unknown progress status")
	}
	as, err := loadAssignment(r.ctx, r.tx, in.AssignmentID, true)
	if err != nil {
		return nil, err
	}
	if as == nil {
		return nil, errNotFound("assignment not found")
	}
	if as.WorkerID == nil || *as.WorkerID != r.sess.UserID {
		return nil, apiErr(403, "ineligible_worker", "assignment belongs to another worker")
	}
	if as.finished() {
		return nil, errConflict("assignment_inactive", "assignment is no longer active")
	}
	if as.Status == "offered" || as.Status == "pending" {
		return nil, errConflict("assignment_not_ready", "accept the assignment before reporting progress")
	}
	if as.LastProgressAt != nil && at.Before(*as.LastProgressAt) {
		return nil, errConflict("invalid_progress_time", "occurredAt is earlier than the previous progress update")
	}
	if as.AcceptedAt != nil && at.Before(*as.AcceptedAt) {
		return nil, errConflict("invalid_progress_time", "occurredAt is earlier than acceptance")
	}
	sample, err := loadSample(r.ctx, r.tx, as.sampleID(), true)
	if err != nil {
		return nil, err
	}
	if sample == nil {
		return nil, errNotFound("sample not found")
	}
	if sample.terminal() {
		return nil, errConflict("invalid_sample_state", "sample is "+sample.Status)
	}
	j, err := loadJourney(r.ctx, r.tx, as.JourneyID, false)
	if err != nil {
		return nil, err
	}
	if j == nil || !j.active() {
		return nil, errConflict("assignment_inactive", "journey is not active")
	}
	newStatus := in.Status
	switch as.Kind {
	case "transport":
		cur, ok := transportOrder[as.Status]
		next, ok2 := transportOrder[newStatus]
		if !ok || !ok2 {
			return nil, errConflict("invalid_transition", "status "+newStatus+" is not valid for a transport leg")
		}
		if next <= cur {
			return nil, errConflict("invalid_transition", "cannot move from "+as.Status+" back to "+newStatus)
		}
		if next >= transportOrder["picked_up"] {
			if !sample.Sealed {
				return nil, errConflict("collection_required", "the sample has not been collected and sealed")
			}
			if sample.CurrentHolderID == nil || *sample.CurrentHolderID != r.sess.UserID {
				prev, err := loadAssignmentsWhere(r.ctx, r.tx, `journey_id=$1 AND sequence < $2 AND status NOT IN ('completed','cancelled','replaced','expired')`, as.JourneyID, as.Sequence)
				if err != nil {
					return nil, err
				}
				if len(prev) > 0 {
					return nil, errConflict("prior_leg_incomplete", "the previous leg has not been completed and handed off")
				}
				return nil, errConflict("custody_required", "custody must be transferred to you through a confirmed handoff first")
			}
		}
	case "node", "laboratory":
		if newStatus != "in_progress" && newStatus != "completed" {
			return nil, errConflict("invalid_transition", "node and laboratory assignments only progress to in_progress or completed")
		}
		if newStatus == "completed" {
			return nil, errConflict("invalid_transition", "node work completes through a confirmed outgoing handoff; laboratory work completes through receipt confirmation")
		}
		cur := nodeOrder[as.Status]
		if as.Status == "arrived" {
			cur = 1
		}
		if nodeOrder[newStatus] <= cur {
			return nil, errConflict("invalid_transition", "cannot move from "+as.Status+" to "+newStatus)
		}
		if sample.CurrentHolderID == nil || *sample.CurrentHolderID != r.sess.UserID {
			return nil, errConflict("custody_required", "custody must be transferred to you through a confirmed handoff first")
		}
	case "collection":
		return nil, errConflict("invalid_transition", "collection work progresses through collect-and-seal and handoff")
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE assignments SET status=$2, last_progress_at=$3, updated_at=now() WHERE id=$1`, as.ID, newStatus, at); err != nil {
		return nil, err
	}
	sampleStatus := sample.Status
	if as.Kind == "transport" && (newStatus == "picked_up" || newStatus == "in_transit") && sampleStatus != "exception" {
		sampleStatus = "in_transit"
	}
	if as.Kind == "transport" && (newStatus == "arrived" || newStatus == "delivered") && sampleStatus != "exception" {
		sampleStatus = "at_node"
		if as.ToLocationID != nil && sample.TargetLaboratoryID != nil && *as.ToLocationID == *sample.TargetLaboratoryID {
			sampleStatus = "at_laboratory"
		}
	}
	locID := sample.CurrentLocationID
	if as.Kind == "transport" {
		if newStatus == "arrived" || newStatus == "delivered" {
			locID = as.ToLocationID
		} else if newStatus == "in_transit" || newStatus == "picked_up" {
			locID = nil
		}
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET status=$2, current_location_id=$3, last_event_at=$4, updated_at=now() WHERE id=$1`, sample.ID, sampleStatus, locID, at); err != nil {
		return nil, err
	}
	if as.Kind == "transport" && (newStatus == "arrived" || newStatus == "delivered") && as.ToLocationID != nil {
		if l, _ := loadLocation(r.ctx, r.tx, *as.ToLocationID); l != nil {
			if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4 WHERE id=$1`, sample.ID, l.Lat, l.Lng, at); err != nil {
				return nil, err
			}
		}
	}
	for _, sid := range as.SampleIDs {
		if sid == sample.ID {
			continue
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET status=$2, current_location_id=$3, last_event_at=$4, updated_at=now() WHERE id=$1 AND status NOT IN ('exception','received','cancelled','expired')`, sid, sampleStatus, locID, at); err != nil {
			return nil, err
		}
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE journeys SET status='active', updated_at=now() WHERE id=$1 AND status='planned'`, as.JourneyID); err != nil {
		return nil, err
	}
	r.audit("assignment_progress", "assignment", as.ID, map[string]any{"status": newStatus, "previousStatus": as.Status, "occurredAt": at, "sampleId": sample.ID, "sampleIds": as.SampleIDs, "journeyId": as.JourneyID, "sampleStatus": sampleStatus})
	r.emit("assignment.progress", "assignment", as.ID, map[string]any{"assignmentId": as.ID, "status": newStatus, "sampleId": sample.ID, "sampleStatus": sampleStatus}, opsRoles, []string{sample.Req.RequesterID, r.sess.UserID})
	return map[string]any{"assignmentId": as.ID, "sampleId": sample.ID, "status": newStatus}, nil
}

