package app

import (
	"strings"
	"time"
)

func (a *App) opCollectAndSeal(r *Req) (any, error) {
	var in struct {
		SampleID      string   `json:"sampleId"`
		AssignmentID  string   `json:"assignmentId"`
		CollectedAt   *string  `json:"collectedAt"`
		ContainerType string   `json:"containerType"`
		ObservedTemp  *float64 `json:"observedTemperatureC"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	at, e := requiredTime(in.CollectedAt, "collectedAt")
	if e != nil {
		return nil, e
	}
	if in.ObservedTemp == nil || strings.TrimSpace(in.ContainerType) == "" {
		return nil, errInvalidJSON("containerType and observedTemperatureC are required")
	}
	s, err := loadSample(r.ctx, r.tx, in.SampleID, true)
	if err != nil {
		return nil, err
	}
	if s == nil {
		return nil, errNotFound("sample not found")
	}
	as, err := loadAssignment(r.ctx, r.tx, in.AssignmentID, true)
	if err != nil {
		return nil, err
	}
	if as == nil || !as.hasSample(s.ID) {
		return nil, errNotFound("collection assignment not found for this sample")
	}
	if as.Kind != "collection" {
		return nil, errConflict("collection_not_ready", "assignment is not a collection assignment")
	}
	if as.finished() {
		return nil, errConflict("assignment_inactive", "collection assignment is no longer active")
	}
	if as.WorkerID == nil || *as.WorkerID != r.sess.UserID {
		return nil, errForbidden("collection assignment belongs to another worker")
	}
	if as.Status != "accepted" {
		if as.Status == "sealed" {
			return nil, errConflict("invalid_sample_state", "sample is already sealed")
		}
		return nil, errConflict("collection_not_ready", "accept the collection assignment before collecting")
	}
	if s.Sealed || s.Status != "requested" && s.Status != "exception" {
		return nil, errConflict("invalid_sample_state", "sample is "+s.Status)
	}
	if at.Before(s.Req.EarliestCollectionAt) || at.After(s.Req.LatestCollectionAt) {
		return nil, errConflict("outside_collection_window", "collectedAt is outside the collection window")
	}
	if at.After(s.Req.DeliveryDeadline) {
		return nil, errConflict("invalid_collection_time", "collectedAt is after the delivery deadline")
	}
	st, err := loadSampleType(r.ctx, r.tx, s.Req.SampleTypeID)
	if err != nil {
		return nil, err
	}
	u, err := loadUser(r.ctx, r.tx, r.sess.UserID)
	if err != nil {
		return nil, err
	}
	if st.QualifiedCollectorRequired && !u.qualifiedFor(st.RequiredQualification, at) {
		return nil, errConflict("certification_inactive", "your certification for "+st.RequiredQualification+" is missing, inactive or expired")
	}
	if !strings.EqualFold(strings.TrimSpace(in.ContainerType), s.Req.ContainerType) {
		return nil, errBadRequest("handling_noncompliant", "container type "+in.ContainerType+" does not match the required "+s.Req.ContainerType)
	}
	compliant := *in.ObservedTemp >= s.Req.TemperatureMinC && *in.ObservedTemp <= s.Req.TemperatureMaxC
	if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET status='sealed', sealed=true, sealed_at=$2, current_holder_id=$3, current_location_id=NULL, last_event_at=$2, updated_at=now() WHERE id=$1`, s.ID, at, u.ID); err != nil {
		return nil, err
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE assignments SET status='sealed', last_progress_at=$2, updated_at=now() WHERE id=$1`, as.ID, at); err != nil {
		return nil, err
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE journeys SET status='active', updated_at=now() WHERE id=$1 AND status='planned'`, as.JourneyID); err != nil {
		return nil, err
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE journey_stops SET completed_at=$2 WHERE journey_id=$1 AND stop_type='pickup' AND completed_at IS NULL`, as.JourneyID, at); err != nil {
		return nil, err
	}
	if u.LatestLat != nil {
		_, _ = r.tx.Exec(r.ctx, `UPDATE samples SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4 WHERE id=$1`, s.ID, *u.LatestLat, *u.LatestLng, at)
	}
	r.audit("sample_collected", "sample", s.ID, map[string]any{"assignmentId": as.ID, "collectedAt": at, "collectorId": u.ID, "journeyId": as.JourneyID})
	r.audit("sample_sealed", "sample", s.ID, map[string]any{"assignmentId": as.ID, "containerType": in.ContainerType, "observedTemperatureC": *in.ObservedTemp, "compliant": compliant, "holderId": u.ID})
	r.audit("custody_established", "sample", s.ID, map[string]any{"holderId": u.ID, "assignmentId": as.ID})
	if _, err := r.tx.Exec(r.ctx, `INSERT INTO handling_checkpoints (id, sample_id, assignment_id, worker_id, container_type, observed_temperature_c, recorded_at, compliant) VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
		newID(), s.ID, as.ID, u.ID, in.ContainerType, *in.ObservedTemp, at, compliant); err != nil {
		return nil, err
	}
	s.Status = "sealed"
	if !compliant {
		if err := a.raiseException(r, s, "handling_noncompliant", "observed temperature outside the required range at sealing", nil, map[string]any{"observedTemperatureC": *in.ObservedTemp, "assignmentId": as.ID}); err != nil {
			return nil, err
		}
	}
	r.emit("sample.sealed", "sample", s.ID, map[string]any{"sampleId": s.ID, "holderId": u.ID, "compliant": compliant}, opsRoles, []string{s.Req.RequesterID, u.ID})
	return map[string]any{"sampleId": s.ID, "status": "sealed", "currentHolderId": u.ID, "sealedAt": at, "handlingCompliant": compliant}, nil
}

func (a *App) opInitiateHandoff(r *Req) (any, error) {
	var in struct {
		SampleID         string  `json:"sampleId"`
		FromAssignmentID string  `json:"fromAssignmentId"`
		ToAssignmentID   string  `json:"toAssignmentId"`
		ReceiverID       string  `json:"receiverId"`
		InitiatedAt      *string `json:"initiatedAt"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	at, e := requiredTime(in.InitiatedAt, "initiatedAt")
	if e != nil {
		return nil, e
	}
	if in.ReceiverID == "" {
		return nil, errBadRequest("invalid_receiver", "receiverId is required")
	}
	s, err := loadSample(r.ctx, r.tx, in.SampleID, true)
	if err != nil {
		return nil, err
	}
	if s == nil {
		return nil, errNotFound("sample not found")
	}
	from, err := loadAssignment(r.ctx, r.tx, in.FromAssignmentID, true)
	if err != nil {
		return nil, err
	}
	to, err := loadAssignment(r.ctx, r.tx, in.ToAssignmentID, true)
	if err != nil {
		return nil, err
	}
	if from == nil || to == nil {
		return nil, errNotFound("assignment not found")
	}
	if from.WorkerID == nil || *from.WorkerID != r.sess.UserID {
		return nil, apiErr(403, "sender_assignment_mismatch", "the sending assignment is not yours")
	}
	if s.CurrentHolderID == nil || *s.CurrentHolderID != r.sess.UserID {
		return nil, errConflict("not_current_holder", "you do not currently hold this sample")
	}
	if !from.hasSample(s.ID) || !to.hasSample(s.ID) {
		return nil, errBadRequest("invalid_handoff_route", "both assignments must belong to this sample's journey")
	}
	if from.JourneyID != to.JourneyID || s.ActiveJourneyID == nil || *s.ActiveJourneyID != from.JourneyID {
		return nil, errConflict("invalid_handoff_route", "assignments are not part of the sample's active journey")
	}
	if to.Sequence != from.Sequence+1 {
		return nil, errConflict("nonadjacent_handoff", "handoffs are only allowed between consecutive legs")
	}
	if from.finished() {
		return nil, errConflict("invalid_assignment_state", "the sending assignment is already finished")
	}
	if !from.holding() {
		if from.Kind == "transport" {
			return nil, errConflict("transport_leg_incomplete", "report arrival before handing the sample off")
		}
		return nil, errConflict("prior_leg_incomplete", "the sending assignment has not reached a handoff-ready state")
	}
	if to.Status == "offered" || to.Status == "pending" {
		return nil, errConflict("offer_not_available", "the receiving assignment has not been accepted yet")
	}
	if to.finished() {
		return nil, errConflict("invalid_assignment_state", "the receiving assignment is no longer active")
	}
	if to.WorkerID == nil || *to.WorkerID != in.ReceiverID {
		return nil, errConflict("receiver_assignment_mismatch", "receiverId does not match the worker of the receiving assignment")
	}
	receiver, err := loadUser(r.ctx, r.tx, in.ReceiverID)
	if err != nil {
		return nil, err
	}
	if receiver == nil {
		return nil, errBadRequest("invalid_receiver", "receiver not found")
	}
	if !receiver.Active || !receiver.Available {
		return nil, errConflict("receiver_unavailable", "receiver is not available")
	}
	if to.Kind == "node" && (receiver.AssignedLocationID == nil || to.NodeID == nil || *receiver.AssignedLocationID != *to.NodeID) {
		return nil, errConflict("node_assignment_mismatch", "receiver is not assigned to the destination node")
	}
	if to.Kind == "laboratory" && (receiver.AssignedLocationID == nil || to.LaboratoryID == nil || *receiver.AssignedLocationID != *to.LaboratoryID) {
		return nil, errConflict("node_assignment_mismatch", "receiver is not assigned to the destination laboratory")
	}
	if s.LastEventAt != nil && at.Before(*s.LastEventAt) {
		return nil, errConflict("invalid_handoff_time", "initiatedAt is earlier than the sample's last recorded event")
	}
	existing, err := loadHandoffsWhere(r.ctx, r.tx, `sample_id=$1 AND status='pending'`, s.ID)
	if err != nil {
		return nil, err
	}
	if len(existing) > 0 {
		h := existing[0]
		if h.FromAssignmentID == from.ID && h.ToAssignmentID == to.ID && h.ReceiverID == in.ReceiverID {
			return map[string]any{"handoffId": h.ID, "senderId": h.SenderID, "receiverId": h.ReceiverID, "currentHolderId": *s.CurrentHolderID, "status": "pending"}, nil
		}
		return nil, errConflict("pending_handoff_exists", "a handoff for this sample is already pending")
	}
	id := newID()
	if _, err := r.tx.Exec(r.ctx, `INSERT INTO handoffs (id, sample_id, journey_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, initiated_at) VALUES ($1,$2,$3,$4,$5,$6,$7,'pending',$8)`,
		id, s.ID, from.JourneyID, from.ID, to.ID, r.sess.UserID, in.ReceiverID, at); err != nil {
		return nil, err
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET last_event_at=$2, updated_at=now() WHERE id=$1`, s.ID, at); err != nil {
		return nil, err
	}
	r.audit("handoff_initiated", "handoff", id, map[string]any{"sampleId": s.ID, "journeyId": from.JourneyID, "fromAssignmentId": from.ID, "toAssignmentId": to.ID, "senderId": r.sess.UserID, "receiverId": in.ReceiverID, "initiatedAt": at})
	r.emit("handoff.initiated", "handoff", id, map[string]any{"handoffId": id, "sampleId": s.ID, "senderId": r.sess.UserID, "receiverId": in.ReceiverID}, opsRoles, []string{r.sess.UserID, in.ReceiverID})
	return map[string]any{"handoffId": id, "senderId": r.sess.UserID, "receiverId": in.ReceiverID, "currentHolderId": r.sess.UserID, "status": "pending"}, nil
}

func (a *App) opConfirmHandoff(r *Req) (any, error) {
	var in struct {
		HandoffID        string  `json:"handoffId"`
		ConfirmationSide string  `json:"confirmationSide"`
		ConfirmedAt      *string `json:"confirmedAt"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	if in.ConfirmationSide != "sender" && in.ConfirmationSide != "receiver" {
		return nil, errBadRequest("invalid_confirmation_side", "confirmationSide must be sender or receiver")
	}
	at, e := requiredTime(in.ConfirmedAt, "confirmedAt")
	if e != nil {
		return nil, e
	}
	h, err := loadHandoff(r.ctx, r.tx, in.HandoffID, true)
	if err != nil {
		return nil, err
	}
	if h == nil {
		return nil, errNotFound("handoff not found")
	}
	s, err := loadSample(r.ctx, r.tx, h.SampleID, true)
	if err != nil {
		return nil, err
	}
	expected := h.SenderID
	if in.ConfirmationSide == "receiver" {
		expected = h.ReceiverID
	}
	if expected != r.sess.UserID {
		return nil, errForbidden("you are not the "+in.ConfirmationSide+" of this handoff")
	}
	response := func(holder string) map[string]any {
		return map[string]any{"handoffId": h.ID, "status": h.Status, "senderConfirmed": h.SenderConfirmed, "receiverConfirmed": h.ReceiverConfirmed, "currentHolderId": holder}
	}
	if h.Status == "confirmed" {
		// Repeated confirmations are idempotent and never transfer custody twice.
		return response(h.ReceiverID), nil
	}
	if h.Status != "pending" {
		return nil, errConflict("handoff_inactive", "handoff is "+h.Status)
	}
	if at.Before(h.InitiatedAt) {
		return nil, errConflict("invalid_confirmation_time", "confirmedAt is earlier than the handoff initiation")
	}
	if s.CurrentHolderID == nil || *s.CurrentHolderID != h.SenderID {
		return nil, errConflict("custody_conflict", "the sender no longer holds the sample")
	}
	alreadyConfirmed := (in.ConfirmationSide == "sender" && h.SenderConfirmed) || (in.ConfirmationSide == "receiver" && h.ReceiverConfirmed)
	if alreadyConfirmed {
		return response(h.SenderID), nil
	}
	if in.ConfirmationSide == "sender" {
		h.SenderConfirmed = true
		h.SenderConfirmedAt = &at
	} else {
		h.ReceiverConfirmed = true
		h.ReceiverConfirmedAt = &at
	}
	r.audit("handoff_confirmed", "handoff", h.ID, map[string]any{"sampleId": s.ID, "journeyId": h.JourneyID, "side": in.ConfirmationSide, "confirmedAt": at, "by": r.sess.UserID})
	holder := h.SenderID
	if h.SenderConfirmed && h.ReceiverConfirmed {
		h.Status = "confirmed"
		h.CompletedAt = &at
		holder = h.ReceiverID
		if err := a.completeHandoff(r, h, s, at); err != nil {
			return nil, err
		}
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE handoffs SET status=$2, sender_confirmed=$3, receiver_confirmed=$4, sender_confirmed_at=$5, receiver_confirmed_at=$6, completed_at=$7 WHERE id=$1`,
		h.ID, h.Status, h.SenderConfirmed, h.ReceiverConfirmed, h.SenderConfirmedAt, h.ReceiverConfirmedAt, h.CompletedAt); err != nil {
		return nil, err
	}
	r.emit("handoff.confirmed", "handoff", h.ID, map[string]any{"handoffId": h.ID, "sampleId": s.ID, "status": h.Status, "side": in.ConfirmationSide, "currentHolderId": holder}, opsRoles, []string{h.SenderID, h.ReceiverID, s.Req.RequesterID})
	return response(holder), nil
}

// completeHandoff transfers custody once both sides have confirmed, completes
// the sending assignment and advances the receiving one.
func (a *App) completeHandoff(r *Req, h *Handoff, s *Sample, at time.Time) error {
	from, err := loadAssignment(r.ctx, r.tx, h.FromAssignmentID, true)
	if err != nil {
		return err
	}
	to, err := loadAssignment(r.ctx, r.tx, h.ToAssignmentID, true)
	if err != nil {
		return err
	}
	if from == nil || to == nil {
		return errConflict("handoff_inactive", "assignments no longer exist")
	}
	// A batched assignment completes only after every sample has been handed over.
	remaining := 0
	for _, sid := range from.SampleIDs {
		if sid == s.ID {
			continue
		}
		var n int
		if err := r.tx.QueryRow(r.ctx, `SELECT count(*) FROM handoffs WHERE sample_id=$1 AND from_assignment_id=$2 AND status='confirmed'`, sid, from.ID).Scan(&n); err != nil {
			return err
		}
		if n == 0 {
			remaining++
		}
	}
	if remaining == 0 {
		if _, err := r.tx.Exec(r.ctx, `UPDATE assignments SET status='completed', completed_at=$2, last_progress_at=$2, updated_at=now() WHERE id=$1`, from.ID, at); err != nil {
			return err
		}
		r.audit("assignment_completed", "assignment", from.ID, map[string]any{"kind": from.Kind, "journeyId": from.JourneyID, "sampleId": s.ID, "sampleIds": from.SampleIDs, "completedAt": at})
		r.emit("assignment.completed", "assignment", from.ID, map[string]any{"assignmentId": from.ID, "kind": from.Kind, "sampleId": s.ID}, opsRoles, []string{*from.WorkerID})
	}
	// Release the resource the sample has just left.
	switch from.Kind {
	case "transport":
		if from.ConnectionID != nil {
			if err := releaseReservations(r, from.JourneyID, *from.ConnectionID, s.ID, "leg_completed"); err != nil {
				return err
			}
		}
	case "node":
		if from.NodeID != nil {
			if err := releaseReservations(r, from.JourneyID, *from.NodeID, s.ID, "node_departed"); err != nil {
				return err
			}
		}
	case "collection":
		if from.ToLocationID != nil && to.Kind == "transport" {
			if err := releaseReservations(r, from.JourneyID, *from.ToLocationID, s.ID, "entry_node_departed"); err != nil {
				return err
			}
		}
	}
	newStatus := to.Status
	sampleStatus := "in_transit"
	var locID *string
	switch to.Kind {
	case "transport":
		if transportOrder[to.Status] < transportOrder["picked_up"] {
			newStatus = "picked_up"
		}
	case "node":
		newStatus = "in_progress"
		sampleStatus = "at_node"
		locID = to.NodeID
		if _, err := r.tx.Exec(r.ctx, `UPDATE journey_stops SET completed_at=$3 WHERE journey_id=$1 AND location_id=$2 AND stop_type='handoff' AND completed_at IS NULL`, to.JourneyID, *to.NodeID, at); err != nil {
			return err
		}
	case "laboratory":
		newStatus = "arrived"
		sampleStatus = "at_laboratory"
		locID = to.LaboratoryID
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE assignments SET status=$2, last_progress_at=$3, updated_at=now() WHERE id=$1`, to.ID, newStatus, at); err != nil {
		return err
	}
	if s.Status == "exception" {
		sampleStatus = "exception"
	}
	var lat, lng *float64
	if locID != nil {
		if l, _ := loadLocation(r.ctx, r.tx, *locID); l != nil {
			lat, lng = &l.Lat, &l.Lng
		}
	} else if u, _ := loadUser(r.ctx, r.tx, h.ReceiverID); u != nil && u.LatestLat != nil {
		lat, lng = u.LatestLat, u.LatestLng
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET current_holder_id=$2, status=$3, current_location_id=$4, last_event_at=$5, latest_lat=COALESCE($6,latest_lat), latest_lng=COALESCE($7,latest_lng), location_recorded_at=CASE WHEN $6 IS NULL THEN location_recorded_at ELSE $5 END, updated_at=now() WHERE id=$1`,
		s.ID, h.ReceiverID, sampleStatus, locID, at, lat, lng); err != nil {
		return err
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE journeys SET status='active', updated_at=now() WHERE id=$1 AND status='planned'`, to.JourneyID); err != nil {
		return err
	}
	r.audit("custody_transferred", "sample", s.ID, map[string]any{"handoffId": h.ID, "fromHolderId": h.SenderID, "toHolderId": h.ReceiverID, "fromAssignmentId": from.ID, "toAssignmentId": to.ID, "journeyId": to.JourneyID, "status": sampleStatus, "at": at})
	r.emit("custody.transferred", "sample", s.ID, map[string]any{"sampleId": s.ID, "fromHolderId": h.SenderID, "toHolderId": h.ReceiverID, "status": sampleStatus}, opsRoles, []string{h.SenderID, h.ReceiverID, s.Req.RequesterID})
	return nil
}

func (a *App) opRecordHandlingCheckpoint(r *Req) (any, error) {
	var in struct {
		SampleID      string   `json:"sampleId"`
		AssignmentID  string   `json:"assignmentId"`
		LocationID    *string  `json:"locationId"`
		ContainerType string   `json:"containerType"`
		ObservedTemp  *float64 `json:"observedTemperatureC"`
		RecordedAt    *string  `json:"recordedAt"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	at, e := requiredTime(in.RecordedAt, "recordedAt")
	if e != nil {
		return nil, e
	}
	if in.ObservedTemp == nil || strings.TrimSpace(in.ContainerType) == "" {
		return nil, errInvalidJSON("containerType and observedTemperatureC are required")
	}
	s, err := loadSample(r.ctx, r.tx, in.SampleID, true)
	if err != nil {
		return nil, err
	}
	if s == nil {
		return nil, errNotFound("sample not found")
	}
	as, err := loadAssignment(r.ctx, r.tx, in.AssignmentID, false)
	if err != nil {
		return nil, err
	}
	if as == nil || !as.hasSample(s.ID) {
		return nil, errNotFound("assignment not found for this sample")
	}
	if as.WorkerID == nil || *as.WorkerID != r.sess.UserID {
		return nil, errForbidden("assignment belongs to another worker")
	}
	if s.terminal() {
		return nil, errConflict("terminal_sample", "sample is "+s.Status)
	}
	if as.finished() {
		return nil, errConflict("assignment_inactive", "assignment is no longer active")
	}
	if s.CurrentHolderID == nil || *s.CurrentHolderID != r.sess.UserID {
		return nil, errForbidden("you do not currently hold this sample")
	}
	j, err := loadJourney(r.ctx, r.tx, as.JourneyID, false)
	if err != nil {
		return nil, err
	}
	if j == nil || !j.active() {
		return nil, errConflict("journey_inactive", "journey is not active")
	}
	if s.LastEventAt != nil && at.Before(*s.LastEventAt) {
		return nil, errConflict("invalid_checkpoint_time", "recordedAt is earlier than the sample's last recorded event")
	}
	compliant := strings.EqualFold(strings.TrimSpace(in.ContainerType), s.Req.ContainerType) && *in.ObservedTemp >= s.Req.TemperatureMinC && *in.ObservedTemp <= s.Req.TemperatureMaxC
	id := newID()
	if _, err := r.tx.Exec(r.ctx, `INSERT INTO handling_checkpoints (id, sample_id, assignment_id, worker_id, location_id, container_type, observed_temperature_c, recorded_at, compliant) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		id, s.ID, as.ID, r.sess.UserID, in.LocationID, in.ContainerType, *in.ObservedTemp, at, compliant); err != nil {
		return nil, err
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET last_event_at=$2, updated_at=now() WHERE id=$1`, s.ID, at); err != nil {
		return nil, err
	}
	r.audit("handling_checkpoint_recorded", "sample", s.ID, map[string]any{"checkpointId": id, "assignmentId": as.ID, "containerType": in.ContainerType, "observedTemperatureC": *in.ObservedTemp, "compliant": compliant, "locationId": in.LocationID, "recordedAt": at})
	status := s.Status
	if !compliant && s.Status != "exception" {
		if err := a.raiseException(r, s, "handling_noncompliant", "handling checkpoint outside the sample's required container or temperature range", nil, map[string]any{"checkpointId": id, "observedTemperatureC": *in.ObservedTemp, "containerType": in.ContainerType}); err != nil {
			return nil, err
		}
		status = "exception"
	}
	r.emit("sample.checkpoint", "sample", s.ID, map[string]any{"sampleId": s.ID, "compliant": compliant, "status": status}, opsRoles, []string{s.Req.RequesterID})
	return map[string]any{"checkpointId": id, "sampleId": s.ID, "compliant": compliant, "sampleStatus": status}, nil
}

func (a *App) labOperatorFor(r *Req, labID string) (*Location, error) {
	loc, err := loadLocation(r.ctx, r.tx, labID)
	if err != nil {
		return nil, err
	}
	if loc == nil {
		return nil, errNotFound("laboratory not found")
	}
	if r.sess.AssignedLocationID == nil || *r.sess.AssignedLocationID != loc.ID {
		return nil, apiErr(403, "wrong_laboratory_operator", "you are not assigned to this laboratory")
	}
	return loc, nil
}

func (a *App) opConfirmLaboratoryReceipt(r *Req) (any, error) {
	var in struct {
		SampleID     string  `json:"sampleId"`
		LaboratoryID string  `json:"laboratoryId"`
		ReceivedAt   *string `json:"receivedAt"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	at, e := requiredTime(in.ReceivedAt, "receivedAt")
	if e != nil {
		return nil, e
	}
	s, err := loadSample(r.ctx, r.tx, in.SampleID, true)
	if err != nil {
		return nil, err
	}
	if s == nil {
		return nil, errNotFound("sample not found")
	}
	lab, err := a.labOperatorFor(r, in.LaboratoryID)
	if err != nil {
		return nil, err
	}
	if s.Status == "received" {
		return nil, errConflict("receipt_not_ready", "sample was already received")
	}
	if s.terminal() {
		return nil, errConflict("receipt_not_ready", "sample is "+s.Status)
	}
	if !lab.Active || !lab.Functions.Laboratory {
		return nil, errConflict("laboratory_unavailable", "laboratory is not active")
	}
	if s.TargetLaboratoryID == nil || *s.TargetLaboratoryID != lab.ID {
		return nil, errConflict("receipt_not_ready", "sample is not routed to this laboratory")
	}
	pending, err := loadHandoffsWhere(r.ctx, r.tx, `sample_id=$1 AND status='pending'`, s.ID)
	if err != nil {
		return nil, err
	}
	if len(pending) > 0 {
		return nil, errConflict("pending_handoff_exists", "a handoff for this sample is still pending")
	}
	if s.CurrentHolderID == nil || *s.CurrentHolderID != r.sess.UserID {
		return nil, errConflict("custody_conflict", "you do not hold this sample; confirm the incoming handoff first")
	}
	labAs, err := loadAssignmentsWhere(r.ctx, r.tx, `journey_id=$1 AND kind='laboratory' AND status NOT IN ('completed','cancelled','replaced','expired')`, derefStr(s.ActiveJourneyID))
	if err != nil {
		return nil, err
	}
	if len(labAs) == 0 || labAs[0].WorkerID == nil || *labAs[0].WorkerID != r.sess.UserID {
		return nil, errConflict("receipt_not_ready", "no laboratory intake assignment is held by you for this sample")
	}
	if s.LastEventAt != nil && at.Before(*s.LastEventAt) {
		return nil, errConflict("invalid_receipt_time", "receivedAt is earlier than the sample's last recorded event")
	}
	if at.After(s.Req.DeliveryDeadline) {
		if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET status='expired', exception=$2, last_event_at=$3, updated_at=now() WHERE id=$1`, s.ID, mustJSON(map[string]any{"kind": "deadline_missed", "reason": "sample reached the laboratory after its delivery deadline", "observedAt": at, "laboratoryId": lab.ID}), at); err != nil {
			return nil, err
		}
		if _, err := r.tx.Exec(r.ctx, `INSERT INTO sample_exceptions (id, sample_id, laboratory_id, kind, reason, observed_at, recorded_by) VALUES ($1,$2,$3,'deadline_missed','sample reached the laboratory after its delivery deadline',$4,$5)`, newID(), s.ID, lab.ID, at, r.sess.UserID); err != nil {
			return nil, err
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE journeys SET status='expired', replan_status='expired', updated_at=now() WHERE id=$1`, derefStr(s.ActiveJourneyID)); err != nil {
			return nil, err
		}
		if err := releaseReservations(r, derefStr(s.ActiveJourneyID), "", s.ID, "deadline_missed"); err != nil {
			return nil, err
		}
		r.audits = append(r.audits, auditEntry{ActorID: r.sess.UserID, Role: r.activeRole(), Action: "sample_expired", EntityType: "sample", EntityID: s.ID, Success: true, OccurredAt: r.now, Details: map[string]any{"reason": "deadline_missed", "receivedAt": at, "deadline": s.Req.DeliveryDeadline, "laboratoryId": lab.ID}})
		if err := r.flushAudits(); err != nil {
			return nil, err
		}
		if err := r.tx.Commit(r.ctx); err != nil {
			return nil, err
		}
		tx, err := a.pool.Begin(r.ctx)
		if err != nil {
			return nil, err
		}
		r.tx = tx
		return nil, errConflict("delivery_deadline_exceeded", "sample arrived after its delivery deadline and has been marked expired")
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET status='received', received_laboratory_id=$2, received_at=$3, current_location_id=$2, last_event_at=$3, latest_lat=$4, latest_lng=$5, location_recorded_at=$3, updated_at=now() WHERE id=$1`, s.ID, lab.ID, at, lab.Lat, lab.Lng); err != nil {
		return nil, err
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE assignments SET status='completed', completed_at=$2, last_progress_at=$2, updated_at=now() WHERE id=$1`, labAs[0].ID, at); err != nil {
		return nil, err
	}
	jid := derefStr(s.ActiveJourneyID)
	var open int
	if err := r.tx.QueryRow(r.ctx, `SELECT count(*) FROM samples WHERE active_journey_id=$1 AND status NOT IN ('received','cancelled','expired')`, jid).Scan(&open); err != nil {
		return nil, err
	}
	if open == 0 {
		if _, err := r.tx.Exec(r.ctx, `UPDATE journeys SET status='completed', updated_at=now() WHERE id=$1`, jid); err != nil {
			return nil, err
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE journey_stops SET completed_at=$2 WHERE journey_id=$1 AND stop_type='delivery' AND completed_at IS NULL`, jid, at); err != nil {
			return nil, err
		}
		r.audit("journey_completed", "journey", jid, map[string]any{"sampleId": s.ID, "laboratoryId": lab.ID})
	}
	if err := releaseReservations(r, jid, "", s.ID, "received"); err != nil {
		return nil, err
	}
	r.audit("sample_received", "sample", s.ID, map[string]any{"laboratoryId": lab.ID, "receivedAt": at, "assignmentId": labAs[0].ID, "journeyId": jid, "deadline": s.Req.DeliveryDeadline})
	r.audit("assignment_completed", "assignment", labAs[0].ID, map[string]any{"kind": "laboratory", "journeyId": jid, "sampleId": s.ID, "completedAt": at})
	r.emit("sample.received", "sample", s.ID, map[string]any{"sampleId": s.ID, "laboratoryId": lab.ID, "receivedAt": at}, opsRoles, []string{s.Req.RequesterID, r.sess.UserID})
	return map[string]any{"sampleId": s.ID, "laboratoryId": lab.ID, "status": "received", "receivedAt": at}, nil
}

func (a *App) opRecordLaboratoryException(r *Req) (any, error) {
	var in struct {
		SampleID     string  `json:"sampleId"`
		LaboratoryID string  `json:"laboratoryId"`
		Reason       string  `json:"reason"`
		ObservedAt   *string `json:"observedAt"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	at, e := requiredTime(in.ObservedAt, "observedAt")
	if e != nil {
		return nil, e
	}
	if strings.TrimSpace(in.Reason) == "" {
		return nil, errInvalidJSON("reason is required")
	}
	s, err := loadSample(r.ctx, r.tx, in.SampleID, true)
	if err != nil {
		return nil, err
	}
	if s == nil {
		return nil, errNotFound("sample not found")
	}
	lab, err := a.labOperatorFor(r, in.LaboratoryID)
	if err != nil {
		return nil, err
	}
	if s.TargetLaboratoryID == nil || *s.TargetLaboratoryID != lab.ID {
		return nil, errConflict("wrong_laboratory", "sample is not routed to this laboratory")
	}
	if s.terminal() {
		return nil, errConflict("journey_inactive", "sample is "+s.Status)
	}
	if s.ActiveJourneyID == nil {
		return nil, errConflict("journey_inactive", "sample has no active journey")
	}
	j, err := loadJourney(r.ctx, r.tx, *s.ActiveJourneyID, false)
	if err != nil {
		return nil, err
	}
	if j == nil || !j.active() {
		return nil, errConflict("journey_inactive", "journey is not active")
	}
	if !s.Sealed {
		return nil, errConflict("laboratory_not_ready", "sample has not entered the transport network yet")
	}
	if at.Before(s.Req.RequestedAt) {
		return nil, errConflict("invalid_exception_time", "observedAt is earlier than the request")
	}
	excID := newID()
	exc := map[string]any{"exceptionId": excID, "kind": "laboratory_exception", "reason": in.Reason, "observedAt": at, "laboratoryId": lab.ID, "recordedBy": r.sess.UserID, "previousStatus": s.Status}
	if _, err := r.tx.Exec(r.ctx, `INSERT INTO sample_exceptions (id, sample_id, laboratory_id, kind, reason, observed_at, recorded_by) VALUES ($1,$2,$3,'laboratory_exception',$4,$5,$6)`, excID, s.ID, lab.ID, in.Reason, at, r.sess.UserID); err != nil {
		return nil, err
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET status='exception', exception=$2, last_event_at=$3, updated_at=now() WHERE id=$1`, s.ID, mustJSON(exc), at); err != nil {
		return nil, err
	}
	r.audit("laboratory_exception_recorded", "sample", s.ID, map[string]any{"exceptionId": excID, "laboratoryId": lab.ID, "reason": in.Reason, "observedAt": at, "journeyId": j.ID})
	r.emit("sample.exception", "sample", s.ID, map[string]any{"sampleId": s.ID, "kind": "laboratory_exception", "reason": in.Reason}, opsRoles, []string{s.Req.RequesterID})
	return map[string]any{"exceptionId": excID, "sampleId": s.ID, "status": "exception", "reason": in.Reason}, nil
}

func derefStr(p *string) string {
	if p == nil {
		return ""
	}
	return *p
}

