				return nil
			}
		}
		return errForbidden("your roles do not permit this action")
	}
	if containsStr(spec.roles, sess.ActiveRole) {
		return nil
	}
	return errForbidden("role " + sess.ActiveRole + " may not perform this action")
}

func containsStr(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

func hashBody(b []byte) string {
	var v any
	if err := json.Unmarshal(b, &v); err == nil {
		if m, ok := v.(map[string]any); ok {
			delete(m, "idempotencyKey")
		}
		if canon, err := json.Marshal(v); err == nil {
			b = canon
		}
	}
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

func (a *App) respondError(w http.ResponseWriter, req *Req, err error) {
	var ae *APIError
	if errors.As(err, &ae) {
		if req.sess != nil && ae.Status != http.StatusUnauthorized {
			a.auditOutside(req.ctx, req.sess, req.op, "operation", req.op, false, map[string]any{"code": ae.Code, "error": ae.Message})
		}
		writeError(w, ae)
		return
	}
	log.Printf("internal error in %s: %v", req.op, err)
