}

// parse decodes the request body into v.
func (r *Req) parse(v any) error {
	dec := json.NewDecoder(bytes.NewReader(r.body))
	if err := dec.Decode(v); err != nil {
		return errInvalidJSON("invalid request body: " + err.Error())
	}
	return nil
}

func (r *Req) activeRole() string {
	if r.sess == nil {
		return ""
	}
	if r.sess.ActiveRole != "" {
		return r.sess.ActiveRole
	}
	if len(r.sess.Roles) > 0 {
		return r.sess.Roles[0]
	}
	return ""
}

func (r *Req) hasRole(role string) bool {
	return r.activeRole() == role
}

func (r *Req) isOps() bool {
	role := r.activeRole()
	return role == RoleAdministrator || role == RoleDispatcher
}

