package app

import (
	"context"
	"math"
	"sort"
	"time"
)

// network is an in-memory view of the structural transport network.
type network struct {
	locations   map[string]*Location
	connections []*Connection
	outgoing    map[string][]*Connection
	acceptance  map[string]map[string]bool // laboratoryId -> sampleTypeId -> accepts
}

func loadNetwork(ctx context.Context, q queryer) (*network, error) {
	locs, _, err := loadLocations(ctx, q)
	if err != nil {
		return nil, err
	}
	conns, err := loadConnections(ctx, q)
	if err != nil {
		return nil, err
	}
	n := &network{locations: locs, connections: conns, outgoing: map[string][]*Connection{}, acceptance: map[string]map[string]bool{}}
	for _, c := range conns {
		n.outgoing[c.From] = append(n.outgoing[c.From], c)
	}
	rows, err := q.Query(ctx, `SELECT laboratory_id, sample_type_id, accepts FROM laboratory_acceptance`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var lab, st string
		var accepts bool
		if err := rows.Scan(&lab, &st, &accepts); err != nil {
			return nil, err
		}
		if n.acceptance[lab] == nil {
			n.acceptance[lab] = map[string]bool{}
		}
		n.acceptance[lab][st] = accepts
	}
	return n, rows.Err()
}

func (n *network) labAccepts(labID, sampleTypeID string) bool {
	l := n.locations[labID]
	if l == nil || !l.Active || !l.Functions.Laboratory {
		return false
	}
	return n.acceptance[labID][sampleTypeID]
}

func (n *network) acceptedTypes(labID string) []string {
	out := []string{}
	for st, ok := range n.acceptance[labID] {
		if ok {
			out = append(out, st)
		}
	}
	sort.Strings(out)
	return out
}

// coveringCollectionPoints returns active collection points whose coverage
// radius (capped at 5 km) contains the origin.
func (n *network) coveringCollectionPoints(origin Coordinate) []*Location {
	var out []*Location
	for _, l := range n.locations {
		if !l.Active || !l.Functions.CollectionPoint {
			continue
		}
		if haversineKm(origin, l.coord()) <= math.Min(l.CoverageKm, 5) {
			out = append(out, l)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		di, dj := haversineKm(origin, out[i].coord()), haversineKm(origin, out[j].coord())
		if di != dj {
			return di < dj
		}
		return out[i].ID < out[j].ID
	})
	return out
}

type planInput struct {
	Origin             Coordinate
	OriginType         string
	OriginNodeID       *string
	StartLocationID    *string // replanning: the sample is already here
	SampleType         *SampleType
	StartAt            time.Time
	Deadline           time.Time
	Units              int
	ExcludeLocations   map[string]bool
	ExcludeConnections map[string]bool
	PreferredLabID     *string
}

type planResult struct {
	Reason      string // "serviceable" or a serviceability reason code
	Entry       *Location
	Path        []*Location
	Connections []*Connection
	Laboratory  *Location
	ArrivalAt   time.Time
	StopTimes   []time.Time // estimated time at each path node (arrival + handling complete)
	TotalCost   float64
}

type dijkstraOpts struct {
	checkCapacity bool
	checkCooled   bool
}

type pathState struct {
	nodes []string
	conns []*Connection
	at    time.Time
	cost  float64
}

func (n *network) nodeUsable(l *Location, in *planInput, opts dijkstraOpts, isStart bool) bool {
	if l == nil {
		return false
	}
	if in.ExcludeLocations[l.ID] && !isStart {
		return false
	}
	if !l.Active && !isStart {
		return false
	}
	if opts.checkCapacity && !isStart {
		units := in.Units
		if in.SampleType.RequiresCooledRoute {
			if l.CooledCapacity-l.CooledReserved < units {
				return false
			}
		} else if l.CapacityUnits-l.Reserved < units {
			return false
		}
	}
	return true
}

func (n *network) connUsable(c *Connection, in *planInput, opts dijkstraOpts) bool {
	if !c.Active || in.ExcludeConnections[c.ID] {
		return false
	}
	if opts.checkCooled && in.SampleType.RequiresCooledRoute && !c.Cooled {
		return false
	}
	if opts.checkCapacity {
		if in.SampleType.RequiresCooledRoute {
			if c.CooledCapacity-c.CooledReserved < in.Units {
				return false
			}
		} else if c.CapacityUnits-c.Reserved < in.Units {
			return false
		}
	}
	return true
}

// shortestToLab runs Dijkstra (by arrival time) from start to the earliest
// reachable accepting laboratory. The start node itself may be a laboratory.
func (n *network) shortestToLab(start *Location, in *planInput, opts dijkstraOpts) *pathState {
	startAt := in.StartAt.Add(time.Duration(start.HandlingMinutes) * time.Minute)
	best := map[string]pathState{start.ID: {nodes: []string{start.ID}, at: startAt}}
	visited := map[string]bool{}
	for {
		var cur *pathState
		var curID string
		for id, st := range best {
			if visited[id] {
				continue
			}
			if cur == nil || st.at.Before(cur.at) || (st.at.Equal(cur.at) && id < curID) {
				s := st
				cur, curID = &s, id
			}
		}
		if cur == nil {
			break
		}
		visited[curID] = true
		for _, c := range n.outgoing[curID] {
			if !n.connUsable(c, in, opts) {
				continue
			}
			to := n.locations[c.To]
			if !n.nodeUsable(to, in, opts, false) {
				continue
			}
			arrive := cur.at.Add(time.Duration(c.TravelMinutes+to.HandlingMinutes) * time.Minute)
			if prev, ok := best[c.To]; ok && !arrive.Before(prev.at) {
				continue
			}
			nodes := append(append([]string{}, cur.nodes...), c.To)
			conns := append(append([]*Connection{}, cur.conns...), c)
			best[c.To] = pathState{nodes: nodes, conns: conns, at: arrive, cost: cur.cost + c.CostUnits}
		}
	}
	var chosen *pathState
	var chosenID string
	for id, st := range best {
		if !n.labAccepts(id, in.SampleType.ID) {
			continue
		}
		if in.ExcludeLocations[id] {
			continue
		}
		if in.PreferredLabID != nil && *in.PreferredLabID == id {
			s := st
			return &s
		}
		if chosen == nil || st.at.Before(chosen.at) || (st.at.Equal(chosen.at) && id < chosenID) {
			s := st
			chosen, chosenID = &s, id
		}
	}
	return chosen
}

// plan computes the best route for the input, returning a serviceability reason
// when no valid plan exists. A result with Reason "deadline_unreachable" still
// carries the best path found so callers can report an estimate.
func (n *network) plan(in *planInput) *planResult {
	if in.Units <= 0 {
		in.Units = 1
	}
	var starts []*Location
	switch {
	case in.StartLocationID != nil:
		l := n.locations[*in.StartLocationID]
		if l == nil {
			return &planResult{Reason: "no_route"}
		}
		starts = []*Location{l}
	case in.OriginType == "node":
		if in.OriginNodeID == nil {
			return &planResult{Reason: "outside_service_coverage"}
		}
		l := n.locations[*in.OriginNodeID]
		if l == nil || !l.Active {
			return &planResult{Reason: "outside_service_coverage"}
		}
		starts = []*Location{l}
	default:
		starts = n.coveringCollectionPoints(in.Origin)
		if len(starts) == 0 {
			return &planResult{Reason: "outside_service_coverage"}
		}
	}
	hasLab := false
	for id := range n.locations {
		if n.labAccepts(id, in.SampleType.ID) && !in.ExcludeLocations[id] {
			hasLab = true
			break
		}
	}
	if !hasLab {
		return &planResult{Reason: "no_accepting_laboratory"}
	}
	attempt := func(opts dijkstraOpts) (*pathState, *Location) {
		var bestState *pathState
		var bestStart *Location
		for _, s := range starts {
			if !n.nodeUsable(s, in, opts, true) {
				continue
			}
			st := n.shortestToLab(s, in, opts)
			if st == nil {
				continue
			}
			if bestState == nil || st.at.Before(bestState.at) {
				bestState, bestStart = st, s
			}
		}
		return bestState, bestStart
	}
	st, start := attempt(dijkstraOpts{checkCapacity: true, checkCooled: true})
	if st == nil {
		if s2, _ := attempt(dijkstraOpts{checkCapacity: false, checkCooled: true}); s2 != nil {
			return &planResult{Reason: "insufficient_capacity"}
		}
		if s3, _ := attempt(dijkstraOpts{checkCapacity: false, checkCooled: false}); s3 != nil {
			return &planResult{Reason: "handling_rules_unsatisfiable"}
		}
		return &planResult{Reason: "no_route"}
	}
	res := &planResult{Reason: "serviceable", Entry: start, Connections: st.conns, ArrivalAt: st.at, TotalCost: st.cost}
	t := in.StartAt.Add(time.Duration(start.HandlingMinutes) * time.Minute)
	res.StopTimes = append(res.StopTimes, t)
	for i, id := range st.nodes {
		l := n.locations[id]
		res.Path = append(res.Path, l)
		if i > 0 {
			c := st.conns[i-1]
			t = t.Add(time.Duration(c.TravelMinutes+l.HandlingMinutes) * time.Minute)
			res.StopTimes = append(res.StopTimes, t)
		}
	}
	res.Laboratory = res.Path[len(res.Path)-1]
	if res.ArrivalAt.After(in.Deadline) {
		res.Reason = "deadline_unreachable"
	}
	return res
}

func (res *planResult) routeMode(sampleCount int) string {
	if sampleCount > 1 {
		return "batched"
	}
	if len(res.Connections) <= 1 {
		return "direct"
	}
	return "multi_stop"
}

