			}
			nodes := append(append([]string{}, cur.nodes...), c.To)
			conns := append(append([]*Connection{}, cur.conns...), c)
			best[c.To] = pathState{nodes: nodes, conns: conns, at: arrive, cost: cur.cost + c.CostUnits}
		}
	}
	if in.TargetLocationID != nil {
		if st, ok := best[*in.TargetLocationID]; ok {
			return &st
		}
		return nil
	}
	var chosen *pathState
	var chosenID string
	for id, st := range best {
		if !n.labAccepts(id, in.SampleType.ID) {
			continue
		}
		if in.ExcludeLocations[id] {
			continue
		}
		if in.PreferredLabID != nil && *in.PreferredLabID == id {
			s := st
			return &s
		}
		if chosen == nil || st.at.Before(chosen.at) || (st.at.Equal(chosen.at) && id < chosenID) {
			s := st
			chosen, chosenID = &s, id
		}
	}
	return chosen
}

// plan computes the best route for the input, returning a serviceability reason
// when no valid plan exists. A result with Reason "deadline_unreachable" still
// carries the best path found so callers can report an estimate.
func (n *network) plan(in *planInput) *planResult {
	if in.Units <= 0 {
		in.Units = 1
	}
	var starts []*Location
	switch {
	case in.StartLocationID != nil:
		l := n.locations[*in.StartLocationID]
		if l == nil {
			return &planResult{Reason: "no_route"}
		}
		starts = []*Location{l}
	case in.OriginType == "node":
		if in.OriginNodeID == nil {
			return &planResult{Reason: "outside_service_coverage"}
		}
		l := n.locations[*in.OriginNodeID]
		if l == nil || !l.Active {
			return &planResult{Reason: "outside_service_coverage"}
		}
		starts = []*Location{l}
	default:
		starts = n.coveringCollectionPoints(in.Origin)
		if len(starts) == 0 {
			return &planResult{Reason: "outside_service_coverage"}
		}
	}
	hasLab := in.TargetLocationID != nil
	for id := range n.locations {
		if n.labAccepts(id, in.SampleType.ID) && !in.ExcludeLocations[id] {
			hasLab = true
			break
		}
	}
	if !hasLab {
		return &planResult{Reason: "no_accepting_laboratory"}
	}
	attempt := func(opts dijkstraOpts) (*pathState, *Location) {
		var bestState *pathState
		var bestStart *Location
		for _, s := range starts {
			if !n.nodeUsable(s, in, opts, true) {
				continue
			}
			st := n.shortestToLab(s, in, opts)
			if st == nil {
				continue
			}
			if bestState == nil || st.at.Before(bestState.at) {
				bestState, bestStart = st, s
			}
		}
		return bestState, bestStart
	}
	st, start := attempt(dijkstraOpts{checkCapacity: true, checkCooled: true})
	if st == nil {
		if s2, _ := attempt(dijkstraOpts{checkCapacity: false, checkCooled: true}); s2 != nil {
			return &planResult{Reason: "insufficient_capacity"}
		}
		if s3, _ := attempt(dijkstraOpts{checkCapacity: false, checkCooled: false}); s3 != nil {
			return &planResult{Reason: "handling_rules_unsatisfiable"}
		}
		return &planResult{Reason: "no_route"}
	}
	res := &planResult{Reason: "serviceable", Entry: start, Connections: st.conns, ArrivalAt: st.at, TotalCost: st.cost}
	t := in.StartAt.Add(time.Duration(start.HandlingMinutes) * time.Minute)
	res.StopTimes = append(res.StopTimes, t)
	for i, id := range st.nodes {
		l := n.locations[id]
		res.Path = append(res.Path, l)
		if i > 0 {
			c := st.conns[i-1]
			t = t.Add(time.Duration(c.TravelMinutes+l.HandlingMinutes) * time.Minute)
			res.StopTimes = append(res.StopTimes, t)
		}
	}
	res.Laboratory = res.Path[len(res.Path)-1]
	if res.ArrivalAt.After(in.Deadline) {
		res.Reason = "deadline_unreachable"
	}
	return res
}

// planFromPath builds a plan along an explicit ordered list of location ids,
// validating that every hop is an active, usable connection and that the final
// node is an accepting laboratory.
func (n *network) planFromPath(in *planInput, nodeIDs []string) (*planResult, *APIError) {
	if len(nodeIDs) == 0 {
		return nil, errConflict("invalid_stop_order", "no stops supplied")
	}
	opts := dijkstraOpts{checkCapacity: true, checkCooled: true}
	start := n.locations[nodeIDs[0]]
	if start == nil {
		return nil, errConflict("invalid_stop", "unknown start location")
	}
	res := &planResult{Reason: "serviceable", Entry: start, Path: []*Location{start}}
	t := in.StartAt.Add(time.Duration(start.HandlingMinutes) * time.Minute)
	res.StopTimes = []time.Time{t}
	for i := 1; i < len(nodeIDs); i++ {
		to := n.locations[nodeIDs[i]]
		if to == nil {
			return nil, errConflict("invalid_stop", "unknown location "+nodeIDs[i])
		}
		if !n.nodeUsable(to, in, opts, false) {
			return nil, errConflict("invalid_stop", "location "+to.Name+" is unavailable or has no capacity")
		}
		var conn *Connection
		for _, c := range n.outgoing[nodeIDs[i-1]] {
			if c.To == to.ID && n.connUsable(c, in, opts) && (conn == nil || c.TravelMinutes < conn.TravelMinutes) {
				conn = c
			}
		}
		if conn == nil {
			return nil, errConflict("invalid_stop_order", "no usable connection from "+n.locations[nodeIDs[i-1]].Name+" to "+to.Name)
		}
		t = t.Add(time.Duration(conn.TravelMinutes+to.HandlingMinutes) * time.Minute)
		res.Path = append(res.Path, to)
		res.Connections = append(res.Connections, conn)
		res.StopTimes = append(res.StopTimes, t)
		res.TotalCost += conn.CostUnits
	}
	res.Laboratory = res.Path[len(res.Path)-1]
	if !n.labAccepts(res.Laboratory.ID, in.SampleType.ID) {
		return nil, errConflict("invalid_destination", "the final stop is not an active laboratory accepting this sample type")
	}
	res.ArrivalAt = t
	if res.ArrivalAt.After(in.Deadline) {
		res.Reason = "deadline_unreachable"
	}
	return res, nil
}

func (res *planResult) routeMode(sampleCount int) string {
	if sampleCount > 1 {
		return "batched"
	}
	if len(res.Connections) <= 1 {
		return "direct"
	}
	return "multi_stop"
}

