// journeyPlanJSON renders the full dispatcher view of a journey.
func (a *App) journeyPlanJSON(r *Req, j *Journey, includeNested bool) (map[string]any, error) {
	stops, err := loadStops(r.ctx, r.tx, j.ID)
	if err != nil {
		return nil, err
	}
	list, err := loadJourneyAssignments(r.ctx, r.tx, j.ID)
	if err != nil {
		return nil, err
	}
	legs := []map[string]any{}
	workers := []string{}
	seen := map[string]bool{}
	var collectionIDs, nodeIDs, labIDs, transportIDs []string
	for _, as := range list {
		if as.WorkerID != nil && !seen[*as.WorkerID] {
			seen[*as.WorkerID] = true
			workers = append(workers, *as.WorkerID)
		}
		switch as.Kind {
		case "collection":
			collectionIDs = append(collectionIDs, as.ID)
		case "node":
			nodeIDs = append(nodeIDs, as.ID)
		case "laboratory":
			labIDs = append(labIDs, as.ID)
		case "transport":
			transportIDs = append(transportIDs, as.ID)
			legs = append(legs, as.toLeg())
		}
	}
	stopJSON := []map[string]any{}
	for _, s := range stops {
		stopJSON = append(stopJSON, s.toJSON())
	}
	capUsed := len(j.SampleIDs)
	capAvail := a.routeAvailableCapacity(r, j)
	out := map[string]any{
		"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode, "status": j.Status,
		"totalCostUnits": j.TotalCostUnits, "capacityUsed": capUsed, "capacityAvailable": capAvail,
