observation.new_content:
package app

import (
	"encoding/json"
	"strings"
	"time"
)

func (a *App) isStale(recordedAt *time.Time) bool {
	return recordedAt == nil || time.Since(*recordedAt) > a.cfg.StaleAfter
}

// journeyPlanJSON renders the full dispatcher view of a journey.
func (a *App) journeyPlanJSON(r *Req, j *Journey, includeNested bool) (map[string]any, error) {
	stops, err := loadStops(r.ctx, r.tx, j.ID)
	if err != nil {
		return nil, err
	}
	list, err := loadJourneyAssignments(r.ctx, r.tx, j.ID)
	if err != nil {
		return nil, err
	}
	legs := []map[string]any{}
	workers := []string{}
	seen := map[string]bool{}
	var collectionIDs, nodeIDs, labIDs, transportIDs []string
	for _, as := range list {
		if as.WorkerID != nil && !seen[*as.WorkerID] {
			seen[*as.WorkerID] = true
			workers = append(workers, *as.WorkerID)
		}
		switch as.Kind {
		case "collection":
			collectionIDs = append(collectionIDs, as.ID)
		case "node":
			nodeIDs = append(nodeIDs, as.ID)
		case "laboratory":
			labIDs = append(labIDs, as.ID)
		case "transport":
			transportIDs = append(transportIDs, as.ID)
			legs = append(legs, as.toLeg())
		}
	}
	stopJSON := []map[string]any{}
	for _, s := range stops {
		stopJSON = append(stopJSON, s.toJSON())
	}
	capUsed := len(j.SampleIDs)
	capAvail := a.routeAvailableCapacity(r, j)
	out := map[string]any{
		"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode, "status": j.Status,
		"totalCostUnits": j.TotalCostUnits, "capacityUsed": capUsed, "capacityAvailable": capAvail,
		"sampleIds": j.SampleIDs, "orderedStops": stopJSON, "legs": legs, "assignedWorkerIds": workers,
		"collectionAssignmentIds": orEmpty(collectionIDs), "nodeAssignmentIds": orEmpty(nodeIDs), "laboratoryAssignmentIds": orEmpty(labIDs),
		"valid": j.active() || j.Status == "completed",
	}
	if j.EstimatedDeliveryAt != nil {
		out["estimatedDeliveryAt"] = *j.EstimatedDeliveryAt
	}
	if j.ParentJourneyID != nil {
		out["parentJourneyId"] = *j.ParentJourneyID
	}
	if len(collectionIDs) > 0 {
		out["collectionAssignmentId"] = collectionIDs[0]
	}
	if len(transportIDs) > 0 {
		out["firstTransportAssignmentId"] = transportIDs[0]
		out["finalTransportAssignmentId"] = transportIDs[len(transportIDs)-1]
		if len(transportIDs) > 2 {
			out["middleTransportAssignmentId"] = transportIDs[1]
		}
	}
	if j.ReplanStatus != "" {
		out["replanStatus"] = j.ReplanStatus
	}
	if includeNested {
		if j.ReplacementJourneyID != nil {
			if rj, _ := loadJourney(r.ctx, r.tx, *j.ReplacementJourneyID, false); rj != nil {
				if plan, err := a.journeyPlanJSON(r, rj, false); err == nil {
					out["replacementJourney"] = plan
				}
			}
		}
		if j.SplitJourneyID != nil {
			if sj, _ := loadJourney(r.ctx, r.tx, *j.SplitJourneyID, false); sj != nil {
				if plan, err := a.journeyPlanJSON(r, sj, false); err == nil {
					out["splitJourney"] = plan
				}
			}
		}
	}
	return out, nil
}

func orEmpty(l []string) []string {
	if l == nil {
		return []string{}
	}
	return l
}

// routeAvailableCapacity is the tightest remaining capacity across the journey's reserved resources.
func (a *App) routeAvailableCapacity(r *Req, j *Journey) int {
	rows, err := r.tx.Query(r.ctx, `SELECT DISTINCT resource_type, resource_id, cooled FROM capacity_reservations WHERE journey_id=$1 AND active`, j.ID)
	if err != nil {
		return 0
	}
	defer rows.Close()
	min := -1
	for rows.Next() {
		var rtype, rid string
		var cooled bool
		if err := rows.Scan(&rtype, &rid, &cooled); err != nil {
			return 0
		}
		var avail int
		table := "locations"
		if rtype == "connection" {
			table = "connections"
		}
		col := "capacity_units - reserved_units"
		if cooled {
			col = "cooled_capacity_units - cooled_reserved_units"
		}
		if err := r.tx.QueryRow(r.ctx, `SELECT `+col+` FROM `+table+` WHERE id=$1`, rid).Scan(&avail); err != nil {
			continue
		}
		if min < 0 || avail < min {
			min = avail
		}
	}
	if min < 0 {
		return 0
	}
	return min
}

func (a *App) opReadJourneyPlan(r *Req) (any, error) {
	var in struct {
		JourneyID string `json:"journeyId"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	j, err := loadJourney(r.ctx, r.tx, in.JourneyID, false)
	if err != nil {
		return nil, err
	}
	if j == nil {
		return nil, errNotFound("journey not found")
	}
	role := r.activeRole()
	switch role {
	case RoleAdministrator, RoleDispatcher:
		return a.journeyPlanJSON(r, j, true)
	case RoleRequester:
		samples, err := loadSamplesWhere(r.ctx, r.tx, `s.id = ANY($1) AND r.requester_id=$2`, j.SampleIDs, r.sess.UserID)
		if err != nil {
			return nil, err
		}
		if len(samples) == 0 {
			return nil, errForbidden("this journey does not carry any of your samples")
		}
		stops, err := loadStops(r.ctx, r.tx, j.ID)
		if err != nil {
			return nil, err
		}
		list, err := loadJourneyAssignments(r.ctx, r.tx, j.ID)
		if err != nil {
			return nil, err
		}
		ids := []string{}
		for _, s := range samples {
			ids = append(ids, s.ID)
		}
		stopJSON := []map[string]any{}
		for _, s := range stops {
			stopJSON = append(stopJSON, s.toJSON())
		}
		legs := []map[string]any{}
		for _, as := range list {
			if as.Kind != "transport" {
				continue
			}
			leg := map[string]any{"sequence": as.Sequence, "status": as.Status}
			if as.FromLocationID != nil {
				leg["fromLocationId"] = *as.FromLocationID
			}
			if as.ToLocationID != nil {
				leg["toLocationId"] = *as.ToLocationID
			}
			legs = append(legs, leg)
		}
		out := map[string]any{"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode, "status": j.Status, "totalCostUnits": j.TotalCostUnits, "sampleIds": ids, "orderedStops": stopJSON, "legs": legs}
		if j.EstimatedDeliveryAt != nil {
			out["estimatedDeliveryAt"] = *j.EstimatedDeliveryAt
		}
		if j.ParentJourneyID != nil {
			out["parentJourneyId"] = *j.ParentJourneyID
		}
		return out, nil
	default:
		list, err := loadJourneyAssignments(r.ctx, r.tx, j.ID)
		if err != nil {
			return nil, err
		}
		var mine []*Assignment
		for _, as := range list {
			if as.WorkerID != nil && *as.WorkerID == r.sess.UserID {
				mine = append(mine, as)
			}
		}
		if len(mine) == 0 {
			return nil, errForbidden("you have no assignment on this journey")
		}
		stops, err := loadStops(r.ctx, r.tx, j.ID)
		if err != nil {
			return nil, err
		}
		relevant := map[string]bool{}
		ids := []string{}
		legs := []map[string]any{}
		var collectionIDs, nodeIDs, labIDs []string
		sampleSet := map[string]bool{}
		for _, as := range mine {
			ids = append(ids, as.ID)
			for _, sid := range as.SampleIDs {
				sampleSet[sid] = true
			}
			if as.FromLocationID != nil {
				relevant[*as.FromLocationID] = true
			}
			if as.ToLocationID != nil {
				relevant[*as.ToLocationID] = true
			}
			if as.NodeID != nil {
				relevant[*as.NodeID] = true
			}
			if as.LaboratoryID != nil {
				relevant[*as.LaboratoryID] = true
			}
			switch as.Kind {
			case "collection":
				collectionIDs = append(collectionIDs, as.ID)
			case "node":
				nodeIDs = append(nodeIDs, as.ID)
			case "laboratory":
				labIDs = append(labIDs, as.ID)
			}
			legs = append(legs, as.toLeg())
		}
		stopJSON := []map[string]any{}
		for _, s := range stops {
			if relevant[s.LocationID] {
				stopJSON = append(stopJSON, s.toJSON())
			}
		}
		sampleIDs := []string{}
		for id := range sampleSet {
			sampleIDs = append(sampleIDs, id)
		}
		out := map[string]any{"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode, "status": j.Status, "scope": "assigned_legs",
			"assignmentIds": ids, "sampleIds": sampleIDs, "legs": legs, "orderedStops": stopJSON,
			"collectionAssignmentIds": orEmpty(collectionIDs), "nodeAssignmentIds": orEmpty(nodeIDs), "laboratoryAssignmentIds": orEmpty(labIDs), "assignedWorkerIds": []string{r.sess.UserID}}
		if j.EstimatedDeliveryAt != nil {
			out["estimatedDeliveryAt"] = *j.EstimatedDeliveryAt
		}
		if j.ParentJourneyID != nil {
			out["parentJourneyId"] = *j.ParentJourneyID
		}
		return out, nil
	}
}

// canSeeSample enforces data-level access: owners, custodians/assigned workers and operations roles.
func (a *App) canSeeSample(r *Req, s *Sample) (bool, error) {
	if r.isOps() {
		return true, nil
	}
	role := r.activeRole()
	if role == RoleRequester {
		return s.Req.RequesterID == r.sess.UserID, nil
	}
	if s.CurrentHolderID != nil && *s.CurrentHolderID == r.sess.UserID {
		return true, nil
	}
	if s.Req.CreatedBy == r.sess.UserID {
		return true, nil
	}
	var n int
	if err := r.tx.QueryRow(r.ctx, `SELECT count(*) FROM assignments WHERE $1 = ANY(sample_ids) AND worker_id=$2`, s.ID, r.sess.UserID).Scan(&n); err != nil {
		return false, err
	}
	if n > 0 {
		return true, nil
	}
	// Node handlers and laboratory operators may see samples routed through their location.
	if r.sess.AssignedLocationID != nil && (role == RoleNodeHandler || role == RoleLaboratory) {
		if s.TargetLaboratoryID != nil && *s.TargetLaboratoryID == *r.sess.AssignedLocationID {
			return true, nil
		}
		if err := r.tx.QueryRow(r.ctx, `SELECT count(*) FROM assignments WHERE $1 = ANY(sample_ids) AND (node_id=$2 OR laboratory_id=$2 OR to_location_id=$2)`, s.ID, *r.sess.AssignedLocationID).Scan(&n); err != nil {
			return false, err
		}
		return n > 0, nil
	}
	return false, nil
}

func (a *App) sampleLocationFields(s *Sample, m map[string]any) {
	if s.LatestLat != nil && s.LatestLng != nil {
		m["latestLocation"] = Coordinate{*s.LatestLat, *s.LatestLng}
	}
	if s.LocationRecordedAt != nil {
		m["locationRecordedAt"] = *s.LocationRecordedAt
	}
	m["locationStale"] = a.isStale(s.LocationRecordedAt)
}

func (a *App) opReadSampleState(r *Req, sampleID string) (any, error) {
	s, err := loadSample(r.ctx, r.tx, sampleID, false)
	if err != nil {
		return nil, err
	}
	if s == nil {
		return nil, errNotFound("sample not found")
	}
	ok, err := a.canSeeSample(r, s)
	if err != nil {
		return nil, err
	}
	if !ok {
		return nil, errForbidden("you may not view this sample")
	}
	timeline, err := timelineFor(r.ctx, r.tx, s.ID)
	if err != nil {
		return nil, err
	}
	ids, err := activeAssignmentIDs(r, s.ID)
	if err != nil {
		return nil, err
	}
	out := map[string]any{
		"sampleId": s.ID, "requestId": s.RequestID, "requesterId": s.Req.RequesterID, "origin": s.Req.Origin, "originType": s.Req.OriginType,
		"requestedAt": s.Req.RequestedAt, "deliveryDeadline": s.Req.DeliveryDeadline, "sampleTypeId": s.Req.SampleTypeID, "containerType": s.Req.ContainerType,
		"temperatureMinC": s.Req.TemperatureMinC, "temperatureMaxC": s.Req.TemperatureMaxC, "incompatibleSampleTypes": s.Req.IncompatibleSampleTypes,
		"serviceability": s.Serviceability, "activeAssignmentIds": ids, "state": map[string]any{"status": s.Status}, "timeline": timeline,
	}
	if s.ActiveJourneyID != nil {
		out["activeJourneyId"] = *s.ActiveJourneyID
	}
	if s.TargetLaboratoryID != nil {
		out["targetLaboratoryId"] = *s.TargetLaboratoryID
	}
	a.sampleLocationFields(s, out)
	return out, nil
}

func (a *App) opReadSampleLifecycle(r *Req) (any, error) {
	var in struct {
		SampleID string `json:"sampleId"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	s, err := loadSample(r.ctx, r.tx, in.SampleID, false)
	if err != nil {
		return nil, err
	}
	if s == nil {
		return nil, errNotFound("sample not found")
	}
	ok, err := a.canSeeSample(r, s)
	if err != nil {
		return nil, err
	}
	if !ok {
		return nil, errForbidden("you may not view this sample")
	}
	timeline, err := timelineFor(r.ctx, r.tx, s.ID)
	if err != nil {
		return nil, err
	}
	completed, err := loadAssignmentsWhere(r.ctx, r.tx, `$1 = ANY(sample_ids) AND status='completed'`, s.ID)
	if err != nil {
		return nil, err
	}
	completedIDs := []string{}
	for _, as := range completed {
		completedIDs = append(completedIDs, as.ID)
	}
	replacements := []string{}
	if s.ActiveJourneyID != nil {
		js, err := loadJourneysWhere(r.ctx, r.tx, `parent_journey_id IS NOT NULL AND status IN ('planned','active') AND $1 = ANY(sample_ids)`, s.ID)
		if err != nil {
			return nil, err
		}
		for _, j := range js {
			replacements = append(replacements, j.ID)
		}
	}
	out := map[string]any{"sampleId": s.ID, "status": s.Status, "sealed": s.Sealed, "completedLegIds": completedIDs, "activeReplacementPlanIds": replacements, "timeline": timeline}
	if s.ActiveJourneyID != nil {
		out["activeJourneyId"] = *s.ActiveJourneyID
	}
	if s.CurrentHolderID != nil {
		out["currentHolderId"] = *s.CurrentHolderID
	}
	if s.ReceivedLaboratoryID != nil {
		out["receivedLaboratoryId"] = *s.ReceivedLaboratoryID
	}
	if s.Exception != nil {
		out["exception"] = s.Exception
	}
	pending, err := loadHandoffsWhere(r.ctx, r.tx, `sample_id=$1 AND status='pending'`, s.ID)
	if err != nil {
		return nil, err
	}
	if len(pending) > 0 {
		out["pendingHandoffId"] = pending[0].ID
		out["pendingHandoff"] = pending[0].toJSON()
	}
	a.sampleLocationFields(s, out)
	return out, nil
}

func (a *App) sampleSummary(r *Req, s *Sample) map[string]any {
	m := map[string]any{"kind": "sample", "sampleId": s.ID, "sample_id": s.ID, "requestId": s.RequestID, "status": s.Status, "serviceability": s.Serviceability,
		"requestedAt": s.Req.RequestedAt, "deliveryDeadline": s.Req.DeliveryDeadline, "earliestCollectionAt": s.Req.EarliestCollectionAt, "latestCollectionAt": s.Req.LatestCollectionAt, "requesterId": s.Req.RequesterID}
	if s.ActiveJourneyID != nil {
		m["journeyId"] = *s.ActiveJourneyID
		m["activeJourneyId"] = *s.ActiveJourneyID
	}
	if s.TargetLaboratoryID != nil {
		m["laboratoryId"] = *s.TargetLaboratoryID
	}
	if s.CurrentHolderID != nil {
		m["currentHolderId"] = *s.CurrentHolderID
	}
	if s.LocationRecordedAt != nil {
		m["locationRecordedAt"] = *s.LocationRecordedAt
	}
	m["locationStale"] = a.isStale(s.LocationRecordedAt)
	return m
}

func (a *App) opListRoleWork(r *Req) (any, error) {
	var in struct {
		Role   *string `json:"role"`
		Status string  `json:"status"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	role := r.activeRole()
	if in.Role != nil && *in.Role != "" {
		if !isValidRole(*in.Role) {
			return nil, errBadRequest("invalid_role", "unknown role")
		}
		if *in.Role != role {
			if !r.sess.HasRole(*in.Role) {
				return nil, errForbidden("you do not hold the role "+*in.Role)
			}
			return nil, errForbidden("select the role " + *in.Role + " before viewing its work")
		}
	}
	work := map[string][]map[string]any{"pending": {}, "inProgress": {}, "completed": {}}
	add := func(bucket string, item map[string]any) {
		if in.Status != "" && item["status"] != in.Status {
			return
		}
		work[bucket] = append(work[bucket], item)
	}
	switch role {
	case RoleRequester:
		samples, err := loadSamplesWhere(r.ctx, r.tx, `r.requester_id=$1`, r.sess.UserID)
		if err != nil {
			return nil, err
		}
		for _, s := range samples {
			item := a.sampleSummary(r, s)
			hist, err := timelineFor(r.ctx, r.tx, s.ID)
			if err != nil {
				return nil, err
			}
			item["history"] = hist
			switch s.Status {
			case "requested", "unserviceable":
				add("pending", item)
			case "received", "cancelled", "expired":
				add("completed", item)
			default:
				add("inProgress", item)
			}
		}
	case RoleAdministrator, RoleDispatcher:
		journeys, err := loadJourneysWhere(r.ctx, r.tx, `true`)
		if err != nil {
			return nil, err
		}
		for _, j := range journeys {
			var count int
			if err := r.tx.QueryRow(r.ctx, `SELECT count(*) FROM assignments WHERE journey_id=$1`, j.ID).Scan(&count); err != nil {
				return nil, err
			}
			hist, err := timelineFor(r.ctx, r.tx, j.ID)
			if err != nil {
				return nil, err
			}
			item := map[string]any{"kind": "journey", "journeyId": j.ID, "journey_id": j.ID, "status": j.Status, "routeMode": j.RouteMode, "planVersion": j.PlanVersion, "sampleIds": j.SampleIDs, "assignmentCount": count, "history": hist}
			if j.EstimatedDeliveryAt != nil {
				item["estimatedDeliveryAt"] = *j.EstimatedDeliveryAt
			} else {
				item["estimatedDeliveryAt"] = r.now
			}
			switch j.Status {
			case "planned":
				add("pending", item)
			case "active":
				add("inProgress", item)
			default:
				add("completed", item)
			}
		}
	default:
		kind := map[string]string{RoleCollector: "collection", RoleCourier: "transport", RoleNodeHandler: "node", RoleLaboratory: "laboratory"}[role]
		list, err := loadAssignmentsWhere(r.ctx, r.tx, `kind=$1 AND worker_id=$2 AND status <> 'pending'`, kind, r.sess.UserID)
		if err != nil {
			return nil, err
		}
		for _, as := range list {
			item, err := a.assignmentWorkItem(r, as)
			if err != nil {
				return nil, err
			}
			switch {
			case as.Status == "offered":
				add("pending", item)
			case as.finished():
				add("completed", item)
			default:
				add("inProgress", item)
			}
		}
	}
	return work, nil
}

func (a *App) assignmentWorkItem(r *Req, as *Assignment) (map[string]any, error) {
	hist, err := timelineFor(r.ctx, r.tx, as.ID)
	if err != nil {
		return nil, err
	}
	item := map[string]any{"kind": as.Kind, "assignmentId": as.ID, "assignment_id": as.ID, "sampleId": as.sampleID(), "sample_id": as.sampleID(), "status": as.Status, "journeyId": as.JourneyID, "sequence": as.Sequence, "history": hist}
	if as.FromLocationID != nil {
		item["fromLocationId"] = *as.FromLocationID
	}
	if as.ToLocationID != nil {
		item["toLocationId"] = *as.ToLocationID
		if l, _ := loadLocation(r.ctx, r.tx, *as.ToLocationID); l != nil {
			item["destinationCapacity"] = l.capacity()
		}
	}
	if as.OfferExpiresAt != nil && as.Status == "offered" {
		item["offerExpiresAt"] = *as.OfferExpiresAt
	}
	if as.NodeID != nil {
		item["nodeId"] = *as.NodeID
		prev, _ := loadAssignmentsWhere(r.ctx, r.tx, `journey_id=$1 AND sequence=$2`, as.JourneyID, as.Sequence-1)
		next, _ := loadAssignmentsWhere(r.ctx, r.tx, `journey_id=$1 AND sequence=$2`, as.JourneyID, as.Sequence+1)
		if len(prev) > 0 && prev[0].FromLocationID != nil {
			item["incomingFromLocationId"] = *prev[0].FromLocationID
		}
		if len(next) > 0 && next[0].ToLocationID != nil {
			item["outgoingToLocationId"] = *next[0].ToLocationID
		}
	}
	if as.LaboratoryID != nil {
		item["laboratoryId"] = *as.LaboratoryID
		if s, _ := loadSample(r.ctx, r.tx, as.sampleID(), false); s != nil {
			item["expectedSampleTypeId"] = s.Req.SampleTypeID
		}
	}
	return item, nil
}

func (a *App) opReadOperationsState(r *Req) (any, error) {
	var in struct {
		Filters *struct {
			SampleTypeID  string `json:"sampleTypeId"`
			SampleTypeID2 string `json:"sample_type_id"`
		} `json:"filters"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	filter := ""
	if in.Filters != nil {
		filter = in.Filters.SampleTypeID
		if filter == "" {
			filter = in.Filters.SampleTypeID2
		}
	}
	return a.operationsState(r, filter)
}

func (a *App) operationsState(r *Req, sampleTypeFilter string) (map[string]any, error) {
	where := `true`
	args := []any{}
	if sampleTypeFilter != "" {
		where = `r.sample_type_id=$1`
		args = append(args, sampleTypeFilter)
	}
	samples, err := loadSamplesWhere(r.ctx, r.tx, where, args...)
	if err != nil {
		return nil, err
	}
	sampleJSON := []map[string]any{}
	exceptions := []map[string]any{}
	delays := []map[string]any{}
	for _, s := range samples {
		m := map[string]any{"sampleId": s.ID, "sample_id": s.ID, "status": s.Status, "requestId": s.RequestID, "origin": s.Req.Origin, "deliveryDeadline": s.Req.DeliveryDeadline}
		if s.CurrentHolderID != nil {
			m["currentHolderId"] = *s.CurrentHolderID
		}
		if s.ActiveJourneyID != nil {
			m["activeJourneyId"] = *s.ActiveJourneyID
		}
		a.sampleLocationFields(s, m)
		sampleJSON = append(sampleJSON, m)
		if !s.terminal() && s.Status != "unserviceable" && r.now.After(s.Req.DeliveryDeadline) {
			delays = append(delays, map[string]any{"sampleId": s.ID, "kind": "deadline_passed", "deliveryDeadline": s.Req.DeliveryDeadline, "status": s.Status})
		}
	}
	rows, err := r.tx.Query(r.ctx, `SELECT e.id, e.sample_id, e.laboratory_id, e.kind, e.reason, e.observed_at, e.recorded_by, s.status FROM sample_exceptions e JOIN samples s ON s.id=e.sample_id ORDER BY e.created_at DESC`)
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var id, sid, kind, reason, status string
		var lab, by *string
		var at time.Time
		if err := rows.Scan(&id, &sid, &lab, &kind, &reason, &at, &by, &status); err != nil {
			rows.Close()
			return nil, err
		}
		exceptions = append(exceptions, map[string]any{"exceptionId": id, "sampleId": sid, "laboratoryId": lab, "kind": kind, "reason": reason, "observedAt": at, "recordedBy": by, "sampleStatus": status})
	}
	rows.Close()

	users, err := loadUsersWhere(r.ctx, r.tx, `active AND roles && $1`, workerRoles)
	if err != nil {
		return nil, err
	}
	counts := map[string]int{}
	crow, err := r.tx.Query(r.ctx, `SELECT worker_id, count(*) FROM assignments WHERE worker_id IS NOT NULL AND status NOT IN ('completed','cancelled','replaced','expired','pending') GROUP BY worker_id`)
	if err != nil {
		return nil, err
	}
	for crow.Next() {
		var id string
		var n int
		if err := crow.Scan(&id, &n); err != nil {
			crow.Close()
			return nil, err
		}
		counts[id] = n
	}
	crow.Close()
	workers := []map[string]any{}
	minC, maxC := -1, 0
	for _, u := range users {
		status := "unavailable"
		if u.Available {
			status = "available"
			if minC < 0 || counts[u.ID] < minC {
				minC = counts[u.ID]
			}
			if counts[u.ID] > maxC {
				maxC = counts[u.ID]
			}
		}
		w := map[string]any{"workerId": u.ID, "worker_id": u.ID, "fullName": u.FullName, "roles": u.Roles, "available": u.Available, "status": status, "capacityUnits": u.CapacityUnits, "assignmentCount": counts[u.ID], "locationStale": a.isStale(u.LocationRecordedAt)}
		if u.LatestLat != nil && u.LatestLng != nil {
			w["latestLocation"] = Coordinate{*u.LatestLat, *u.LatestLng}
			w["latest_location"] = Coordinate{*u.LatestLat, *u.LatestLng}
		}
		if u.LocationRecordedAt != nil {
			w["locationRecordedAt"] = *u.LocationRecordedAt
		}
		workers = append(workers, w)
	}
	spread := 0
	if minC >= 0 {
		spread = maxC - minC
	}

	net, err := loadNetwork(r.ctx, r.tx)
	if err != nil {
		return nil, err
	}
	_, locs, err := loadLocations(r.ctx, r.tx)
	if err != nil {
		return nil, err
	}
	locJSON := []map[string]any{}
	for _, l := range locs {
		m := l.toJSON()
		m["id"] = l.ID
		m["capacity"] = l.capacity()
		m["acceptedSampleTypeIds"] = net.acceptedTypes(l.ID)
		locJSON = append(locJSON, m)
	}
	connJSON := []map[string]any{}
	for _, c := range net.connections {
		connJSON = append(connJSON, map[string]any{"id": c.ID, "connectionId": c.ID, "fromLocationId": c.From, "toLocationId": c.To, "travelMinutes": c.TravelMinutes, "costUnits": c.CostUnits, "cooled": c.Cooled, "active": c.Active, "capacity": c.capacity()})
	}

	journeys, err := loadJourneysWhere(r.ctx, r.tx, `status IN ('planned','active')`)
	if err != nil {
		return nil, err
	}
	routes := []map[string]any{}
	for _, j := range journeys {
		stops, err := loadStops(r.ctx, r.tx, j.ID)
		if err != nil {
			return nil, err
		}
		list, err := loadJourneyAssignments(r.ctx, r.tx, j.ID)
		if err != nil {
			return nil, err
		}
		stopJSON := []map[string]any{}
		for _, s := range stops {
			stopJSON = append(stopJSON, s.toJSON())
		}
		legs := []map[string]any{}
		for _, as := range list {
			leg := as.toLeg()
			leg["kind"] = as.Kind
			legs = append(legs, leg)
		}
		route := map[string]any{"journeyId": j.ID, "status": j.Status, "routeMode": j.RouteMode, "planVersion": j.PlanVersion, "sampleIds": j.SampleIDs, "orderedStops": stopJSON, "legs": legs, "targetLaboratoryId": j.TargetLaboratoryID}
		if j.EstimatedDeliveryAt != nil {
			route["estimatedDeliveryAt"] = *j.EstimatedDeliveryAt
		}
		routes = append(routes, route)
		for _, as := range list {
			if as.Status == "offered" && as.OfferExpiresAt != nil && as.OfferExpiresAt.Before(r.now) {
				delays = append(delays, map[string]any{"journeyId": j.ID, "assignmentId": as.ID, "kind": "offer_overdue", "sampleId": as.sampleID()})
			}
			if as.Status == "pending" {
				delays = append(delays, map[string]any{"journeyId": j.ID, "assignmentId": as.ID, "kind": "unassigned", "sampleId": as.sampleID()})
			}
		}
	}
	handoffs := []map[string]any{}
	hs, err := loadHandoffsWhere(r.ctx, r.tx, `status='pending'`)
	if err != nil {
		return nil, err
	}
	for _, h := range hs {
		handoffs = append(handoffs, h.toJSON())
	}
	var ineligible int
	if err := r.tx.QueryRow(r.ctx, `SELECT count(*) FROM assignments a JOIN users u ON u.id=a.worker_id WHERE a.status IN ('offered','accepted') AND (NOT u.active OR NOT u.available)`).Scan(&ineligible); err != nil {
		return nil, err
	}
	return map[string]any{
		"samples": sampleJSON, "workers": workers, "locations": locJSON, "connections": connJSON, "routes": routes,
		"handoffs": handoffs, "delays": delays, "exceptions": exceptions, "assignmentCountSpread": spread, "ineligibleAssignmentCount": ineligible,
	}, nil
}

func (a *App) opSearchAuditTrail(r *Req) (any, error) {
	var in struct {
		Query      string  `json:"query"`
		ActorID    string  `json:"actorId"`
		EntityType string  `json:"entityType"`
		EntityID   string  `json:"entityId"`
		Action     string  `json:"action"`
		Role       string  `json:"role"`
		Success    *bool   `json:"success"`
		FromTime   *string `json:"fromTime"`
		ToTime     *string `json:"toTime"`
		Limit      *int    `json:"limit"`
		Offset     *int    `json:"offset"`
		Order      string  `json:"order"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	limit, offset := 500, 0
	if in.Limit != nil {
		if *in.Limit < 1 || *in.Limit > 5000 {
			return nil, errBadRequest("invalid_limit", "limit must be between 1 and 5000")
		}
		limit = *in.Limit
	}
	if in.Offset != nil {
		if *in.Offset < 0 {
			return nil, errBadRequest("invalid_offset", "offset must be >= 0")
		}
		offset = *in.Offset
	}
	order := "newest_first"
	if in.Order != "" {
		if in.Order != "newest_first" && in.Order != "oldest_first" {
			return nil, errBadRequest("invalid_order", "order must be newest_first or oldest_first")
		}
		order = in.Order
	}
	from, e := optionalTime(in.FromTime, "fromTime")
	if e != nil {
		return nil, e
	}
	to, e := optionalTime(in.ToTime, "toTime")
	if e != nil {
		return nil, e
	}
	conds := []string{"true"}
	args := []any{}
	add := func(cond string, v any) {
		args = append(args, v)
		conds = append(conds, strings.ReplaceAll(cond, "?", "$"+itoa(int64(len(args)))))
	}
	if in.Query != "" {
		add("search_text LIKE ?", "%"+strings.ToLower(in.Query)+"%")
	}
	if in.ActorID != "" {
		add("actor_id = ?", in.ActorID)
	}
	if in.EntityType != "" {
		add("entity_type = ?", in.EntityType)
	}
	if in.EntityID != "" {
		add("(entity_id = ? OR details->>'sampleId' = ? OR details->>'journeyId' = ? OR details->>'requestId' = ?)", in.EntityID)
		args = append(args, in.EntityID, in.EntityID, in.EntityID)
		n := len(args)
		conds[len(conds)-1] = "(entity_id = $" + itoa(int64(n-3)) + " OR details->>'sampleId' = $" + itoa(int64(n-2)) + " OR details->>'journeyId' = $" + itoa(int64(n-1)) + " OR details->>'requestId' = $" + itoa(int64(n)) + ")"
	}
	if in.Action != "" {
		add("action = ?", in.Action)
	}
	if in.Role != "" {
		add("role = ?", in.Role)
	}
	if in.Success != nil {
		add("success = ?", *in.Success)
	}
	if from != nil {
		add("occurred_at >= ?", *from)
	}
	if to != nil {
		add("occurred_at <= ?", *to)
	}
	whereSQL := strings.Join(conds, " AND ")
	var total int
	if err := r.tx.QueryRow(r.ctx, `SELECT count(*) FROM audit_log WHERE `+whereSQL, args...).Scan(&total); err != nil {
		return nil, err
	}
	dir := "DESC"
	if order == "oldest_first" {
		dir = "ASC"
	}
	args = append(args, limit, offset)
	rows, err := r.tx.Query(r.ctx, `SELECT event_id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details FROM audit_log WHERE `+whereSQL+` ORDER BY event_id `+dir+` LIMIT $`+itoa(int64(len(args)-1))+` OFFSET $`+itoa(int64(len(args))), args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	entries := []map[string]any{}
	for rows.Next() {
		var id int64
		var actor, role, action, etype, eid string
		var success bool
		var at time.Time
		var details []byte
		if err := rows.Scan(&id, &actor, &role, &action, &etype, &eid, &success, &at, &details); err != nil {
			return nil, err
		}
		d := map[string]any{}
		_ = json.Unmarshal(details, &d)
		sid := itoa(id)
		entries = append(entries, map[string]any{
			"auditId": sid, "audit_id": sid, "actorId": actor, "actor_id": actor, "role": role, "actorRole": role, "action": action,
			"entityType": etype, "entity_type": etype, "entityId": eid, "entity_id": eid, "success": success, "occurredAt": at, "occurred_at": at, "details": d,
		})
	}
	returned := len(entries)
	out := map[string]any{"entries": entries, "total": total, "returned": returned, "offset": offset, "limit": limit, "order": order, "hasMore": offset+returned < total}
	if offset+returned < total {
		out["nextOffset"] = offset + returned
	}
	return out, nil
}

