func (a *App) opListRoleWork(r *Req) (any, error) {
	var in struct {
		Role   *string `json:"role"`
		Status string  `json:"status"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	role := r.activeRole()
	if in.Role != nil && *in.Role != "" {
		if !isValidRole(*in.Role) {
			return nil, errBadRequest("invalid_role", "unknown role")
		}
		if *in.Role != role {
			if !r.sess.HasRole(*in.Role) {
				return nil, errForbidden("you do not hold the role "+*in.Role)
			}
			return nil, errForbidden("select the role " + *in.Role + " before viewing its work")
		}
	}
	work := map[string][]map[string]any{"pending": {}, "inProgress": {}, "completed": {}}
	add := func(bucket string, item map[string]any) {
		if in.Status != "" && item["status"] != in.Status {
			return
		}
		work[bucket] = append(work[bucket], item)
	}
	switch role {
	case RoleRequester:
		samples, err := loadSamplesWhere(r.ctx, r.tx, `r.requester_id=$1`, r.sess.UserID)
		if err != nil {
			return nil, err
		}
		for _, s := range samples {
			item := a.sampleSummary(r, s)
			hist, err := timelineFor(r.ctx, r.tx, s.ID)
			if err != nil {
				return nil, err
			}
			item["history"] = hist
			switch s.Status {
			case "requested", "unserviceable":
				add("pending", item)
			case "received", "cancelled", "expired":
				add("completed", item)
			default:
				add("inProgress", item)
			}
		}
	case RoleAdministrator, RoleDispatcher:
		journeys, err := loadJourneysWhere(r.ctx, r.tx, `true`)
		if err != nil {
			return nil, err
		}
		for _, j := range journeys {
			var count int
			if err := r.tx.QueryRow(r.ctx, `SELECT count(*) FROM assignments WHERE journey_id=$1`, j.ID).Scan(&count); err != nil {
				return nil, err
			}
			hist, err := timelineFor(r.ctx, r.tx, j.ID)
			if err != nil {
				return nil, err
			}
			item := map[string]any{"kind": "journey", "journeyId": j.ID, "journey_id": j.ID, "status": j.Status, "routeMode": j.RouteMode, "planVersion": j.PlanVersion, "sampleIds": j.SampleIDs, "assignmentCount": count, "history": hist}
			if j.EstimatedDeliveryAt != nil {
				item["estimatedDeliveryAt"] = *j.EstimatedDeliveryAt
			} else {
				item["estimatedDeliveryAt"] = r.now
			}
			switch j.Status {
			case "planned":
				add("pending", item)
			case "active":
				add("inProgress", item)
			default:
				add("completed", item)
			}
		}
	default:
		kind := map[string]string{RoleCollector: "collection", RoleCourier: "transport", RoleNodeHandler: "node", RoleLaboratory: "laboratory"}[role]
		list, err := loadAssignmentsWhere(r.ctx, r.tx, `kind=$1 AND worker_id=$2 AND status <> 'pending'`, kind, r.sess.UserID)
		if err != nil {
			return nil, err
		}
		for _, as := range list {
			item, err := a.assignmentWorkItem(r, as)
			if err != nil {
				return nil, err
			}
			switch {
			case as.Status == "offered":
				add("pending", item)
			case as.finished():
				add("completed", item)
			default:
				add("inProgress", item)
			}
		}
	}
	return work, nil
}

func (a *App) assignmentWorkItem(r *Req, as *Assignment) (map[string]any, error) {
	hist, err := timelineFor(r.ctx, r.tx, as.ID)
	if err != nil {
		return nil, err
	}
	item := map[string]any{"kind": as.Kind, "assignmentId": as.ID, "assignment_id": as.ID, "sampleId": as.sampleID(), "sample_id": as.sampleID(), "status": as.Status, "journeyId": as.JourneyID, "sequence": as.Sequence, "history": hist}
	if as.FromLocationID != nil {
		item["fromLocationId"] = *as.FromLocationID
	}
	if as.ToLocationID != nil {
		item["toLocationId"] = *as.ToLocationID
		if l, _ := loadLocation(r.ctx, r.tx, *as.ToLocationID); l != nil {
			item["destinationCapacity"] = l.capacity()
		}
	}
	if as.OfferExpiresAt != nil && as.Status == "offered" {
		item["offerExpiresAt"] = *as.OfferExpiresAt
	}
	if as.NodeID != nil {
		item["nodeId"] = *as.NodeID
		prev, _ := loadAssignmentsWhere(r.ctx, r.tx, `journey_id=$1 AND sequence=$2`, as.JourneyID, as.Sequence-1)
		next, _ := loadAssignmentsWhere(r.ctx, r.tx, `journey_id=$1 AND sequence=$2`, as.JourneyID, as.Sequence+1)
		if len(prev) > 0 && prev[0].FromLocationID != nil {
			item["incomingFromLocationId"] = *prev[0].FromLocationID
		}
		if len(next) > 0 && next[0].ToLocationID != nil {
			item["outgoingToLocationId"] = *next[0].ToLocationID
		}
	}
	if as.LaboratoryID != nil {
		item["laboratoryId"] = *as.LaboratoryID
		if s, _ := loadSample(r.ctx, r.tx, as.sampleID(), false); s != nil {
			item["expectedSampleTypeId"] = s.Req.SampleTypeID
		}
	}
	return item, nil
}

