// defaultSampleTypes are always present: Amber, Indigo, Frost and Pulse.
type defaultSampleType struct {
        Name          string
        Qualification string
        Container     string
        MinC, MaxC    float64
        Cooled        bool
        Batching      bool
}

var defaultSampleTypes = []defaultSampleType{
        {Name: "Amber", Qualification: "amber", Container: "standard_vial", MinC: 15, MaxC: 30, Cooled: false, Batching: true},
        {Name: "Indigo", Qualification: "indigo", Container: "sealed_tube", MinC: 15, MaxC: 30, Cooled: false, Batching: true},
        {Name: "Frost", Qualification: "frost", Container: "cryo_vial", MinC: -25, MaxC: -10, Cooled: true, Batching: true},
        {Name: "Pulse", Qualification: "pulse", Container: "rapid_cartridge", MinC: 15, MaxC: 30, Cooled: false, Batching: false},
}

func seedDefaults(ctx context.Context, pool *pgxpool.Pool) error {
        ids := map[string]string{}
        for _, t := range defaultSampleTypes {
                var id string
                err := pool.QueryRow(ctx, `SELECT id FROM sample_types WHERE name=$1`, t.Name).Scan(&id)
                if err == pgx.ErrNoRows {
                        id = newID()
                        if _, err := pool.Exec(ctx, `INSERT INTO sample_types (id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed)
                                VALUES ($1,$2,true,$3,$4,$5,$6,$7,$8)`, id, t.Name, t.Qualification, t.Container, t.MinC, t.MaxC, t.Cooled, t.Batching); err != nil {
                                return fmt.Errorf("seed sample type %s: %w", t.Name, err)
                        }
                } else if err != nil {
                        return err
                }
                ids[t.Name] = id
        }
        // Indigo must not share a container with Amber (mutual incompatibility).
        if _, err := pool.Exec(ctx, `UPDATE sample_types SET incompatible_sample_types = array_append(array_remove(incompatible_sample_types, $2::uuid), $2::uuid) WHERE id=$1`, ids["Indigo"], ids["Amber"]); err != nil {
