        }
        if _, err := pool.Exec(ctx, `UPDATE sample_types SET incompatible_sample_types = array_append(array_remove(incompatible_sample_types, $2::uuid), $2::uuid) WHERE id=$1`, ids["Amber"], ids["Indigo"]); err != nil {
                return err
        }
