//go:embed schema.sql
var schemaSQL string

// Config holds runtime settings sourced from the environment.
type Config struct {
	DatabaseURL         string
	ListenAddr          string
	AdminUsername       string
	AdminPassword       string
	StaticDir           string
	MapAssetDir         string
	OfferTimeout        time.Duration
	NoWorkerTimeout     time.Duration
	StaleAfter          time.Duration
	DeclinePenalty      time.Duration
	DeclinePenaltyCount int
}

func ConfigFromEnv() Config {
	c := Config{
		DatabaseURL:         envOr("DATABASE_URL", "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"),
		ListenAddr:          envOr("LISTEN_ADDR", "127.0.0.1:"+envOr("PORT", "8080")),
		AdminUsername:       os.Getenv("ADMIN_USERNAME"),
		AdminPassword:       os.Getenv("ADMIN_PASSWORD"),
		StaticDir:           envOr("STATIC_DIR", "frontend/dist"),
		MapAssetDir:         envOr("OFFLINE_MAP_ASSET_DIR", "/opt/arena/map-assets"),
		OfferTimeout:        envDuration("OFFER_TIMEOUT_SECONDS", 900),
		NoWorkerTimeout:     envDuration("NO_WORKER_TIMEOUT_SECONDS", 600),
		StaleAfter:          envDuration("LOCATION_STALE_SECONDS", 300),
		DeclinePenalty:      envDuration("DECLINE_PENALTY_SECONDS", 1800),
		DeclinePenaltyCount: 3,
	}
	return c
}

func envOr(k, d string) string {
	if v := os.Getenv(k); v != "" {
		return v
	}
	return d
}

func envDuration(k string, defSeconds int) time.Duration {
	if v := os.Getenv(k); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			return time.Duration(n) * time.Second
		}
	}
	return time.Duration(defSeconds) * time.Second
}

// App is the application root: database pool, realtime hub and configuration.
type App struct {
	cfg  Config
	pool *pgxpool.Pool
	hub  *Hub

	// mu serialises all mutating operations so capacity pools, offers and
	// custody transitions never race inside a single process.
	mu sync.Mutex

	svcMu       sync.RWMutex
	svcSnapshot *ServiceabilitySnapshot
	svcQueue    chan struct{}

	ready bool
}

func New(ctx context.Context, cfg Config) (*App, error) {
	pool, err := pgxpool.New(ctx, cfg.DatabaseURL)
	if err != nil {
		return nil, fmt.Errorf("connect database: %w", err)
	}
	a := &App{cfg: cfg, pool: pool, hub: NewHub(), svcQueue: make(chan struct{}, 1)}
	return a, nil
}

// Reset drops and recreates every application-owned table.
func Reset(ctx context.Context, cfg Config) error {
	pool, err := pgxpool.New(ctx, cfg.DatabaseURL)
	if err != nil {
		return err
	}
	defer pool.Close()
	if _, err := pool.Exec(ctx, "DROP SCHEMA public CASCADE; CREATE SCHEMA public;"); err != nil {
		return fmt.Errorf("drop schema: %w", err)
	}
	if _, err := pool.Exec(ctx, schemaSQL); err != nil {
		return fmt.Errorf("apply schema: %w", err)
	}
	if err := seedDefaults(ctx, pool); err != nil {
		return err
	}
	log.Println("reset complete: schema materialised")
	return nil
}

// Init applies the schema (idempotent), seeds defaults, ensures the first
// administrator exists and publishes the initial serviceability snapshot.
func (a *App) Init(ctx context.Context) error {
	if _, err := a.pool.Exec(ctx, schemaSQL); err != nil {
		return fmt.Errorf("apply schema: %w", err)
	}
	if err := seedDefaults(ctx, a.pool); err != nil {
		return err
	}
	if err := a.ensureInitialAdmin(ctx); err != nil {
		return err
	}
	if err := a.loadOrComputeSnapshot(ctx); err != nil {
		return err
	}
	a.ready = true
	go a.snapshotWorker()
	go a.schedulerLoop()
	return nil
}

func (a *App) Close() { a.pool.Close() }

func (a *App) Ready(ctx context.Context) bool {
	if !a.ready {
		return false
	}
	c, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	return a.pool.Ping(c) == nil
}

