package app

import (
	"encoding/json"
	"strings"
	"time"
)

type planVersionInput struct {
	JourneyID           string `json:"journeyId"`
	ExpectedPlanVersion *int   `json:"expectedPlanVersion"`
}

// lockActiveJourney loads a journey for update and enforces plan-version checks.
func (a *App) lockActiveJourney(r *Req, journeyID string, expected *int) (*Journey, error) {
	if expected == nil || *expected < 1 {
		return nil, errBadRequest("invalid_plan_version", "expectedPlanVersion must be >= 1")
	}
	j, err := loadJourney(r.ctx, r.tx, journeyID, true)
	if err != nil {
		return nil, err
	}
	if j == nil {
		return nil, errNotFound("journey not found")
	}
	if !j.active() {
		return nil, errConflict("inactive_plan", "journey is "+j.Status)
	}
	if j.PlanVersion != *expected {
		return nil, errConflict("stale_plan", "expectedPlanVersion does not match the current plan version")
	}
	return j, nil
}

func (a *App) bumpPlanVersion(r *Req, journeyID string) error {
	_, err := r.tx.Exec(r.ctx, `UPDATE journeys SET plan_version = plan_version + 1, updated_at=now() WHERE id=$1`, journeyID)
	return err
}

// cancelUnfinishedAssignments cancels unfinished assignments of a journey,
// optionally keeping one (the in-flight custody anchor).
func (a *App) cancelUnfinishedAssignments(r *Req, journeyID string, keep *string, reason string) error {
	list, err := loadJourneyAssignments(r.ctx, r.tx, journeyID)
	if err != nil {
		return err
	}
	for _, as := range list {
		if as.finished() || (keep != nil && as.ID == *keep) {
			continue
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE assignments SET status='cancelled', offer_expires_at=NULL, completed_at=$2, updated_at=now() WHERE id=$1`, as.ID, r.now); err != nil {
			return err
		}
		r.audit("assignment_cancelled", "assignment", as.ID, map[string]any{"reason": reason, "journeyId": journeyID, "kind": as.Kind, "sampleId": as.sampleID(), "sampleIds": as.SampleIDs, "workerId": as.WorkerID, "previousStatus": as.Status})
		if as.WorkerID != nil {
			r.emit("assignment.cancelled", "assignment", as.ID, map[string]any{"assignmentId": as.ID, "reason": reason}, opsRoles, []string{*as.WorkerID})
		}
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE handoffs SET status='cancelled' WHERE journey_id=$1 AND status='pending' AND (to_assignment_id IN (SELECT id FROM assignments WHERE journey_id=$1 AND status='cancelled'))`, journeyID); err != nil {
		return err
	}
	return nil
}

func (a *App) opCancelJourney(r *Req) (any, error) {
	var in struct {
		planVersionInput
		Reason string `json:"reason"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	j, err := a.lockActiveJourney(r, in.JourneyID, in.ExpectedPlanVersion)
	if err != nil {
		return nil, err
	}
	samples, err := loadSamplesWhere(r.ctx, r.tx, `s.id = ANY($1)`, j.SampleIDs)
	if err != nil {
		return nil, err
	}
	for _, s := range samples {
		if s.Status == "received" {
			return nil, errConflict("completed_work_immutable", "sample "+s.ID+" was already received")
		}
	}
	if err := a.cancelUnfinishedAssignments(r, j.ID, nil, "journey_cancelled"); err != nil {
		return nil, err
	}
	if err := releaseReservations(r, j.ID, "", "", "journey_cancelled"); err != nil {
		return nil, err
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE journeys SET status='cancelled', plan_version=plan_version+1, updated_at=now() WHERE id=$1`, j.ID); err != nil {
		return nil, err
	}
	for _, s := range samples {
		if s.terminal() {
			continue
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET status='cancelled', last_event_at=$2, updated_at=now() WHERE id=$1`, s.ID, r.now); err != nil {
			return nil, err
		}
		r.audit("sample_cancelled", "sample", s.ID, map[string]any{"journeyId": j.ID, "reason": in.Reason})
		r.emit("sample.cancelled", "sample", s.ID, map[string]any{"sampleId": s.ID, "journeyId": j.ID}, opsRoles, []string{s.Req.RequesterID})
	}
	r.audit("journey_cancelled", "journey", j.ID, map[string]any{"reason": in.Reason, "sampleIds": j.SampleIDs, "planVersion": j.PlanVersion + 1})
	r.emit("journey.cancelled", "journey", j.ID, map[string]any{"journeyId": j.ID, "sampleIds": j.SampleIDs}, opsRoles, nil)
	return map[string]any{"journeyId": j.ID, "status": "cancelled", "sampleIds": j.SampleIDs}, nil
}

type replanOpts struct {
	Reason             string
	ExcludeLocations   map[string]bool
	ExcludeConnections map[string]bool
	Waypoint           *string
	ExplicitPath       []string
	PreferredLabID     *string
	ForceReplace       bool
}

type replanOutcome struct {
	Status      string // replaced | expired | exception | not_required
	Replacement *Journey
}

// custodyAnchor finds the unfinished assignment whose worker currently holds
// (or is about to collect) the journey's samples.
func custodyAnchor(list []*Assignment) *Assignment {
	for _, as := range list {
		if as.finished() {
			continue
		}
		if as.holding() {
			return as
		}
	}
	for _, as := range list {
		if as.Kind == "collection" && as.Status == "accepted" {
			return as
		}
	}
	return nil
}

// replanJourney replaces the unfinished part of a journey with a new plan,
// preserving completed work and the current custody holder.
func (a *App) replanJourney(r *Req, j *Journey, opts replanOpts) (*replanOutcome, error) {
	samples, err := loadSamplesWhere(r.ctx, r.tx, `s.id = ANY($1) AND s.status NOT IN ('received','cancelled','expired')`, j.SampleIDs)
	if err != nil {
		return nil, err
	}
	if len(samples) == 0 {
		return &replanOutcome{Status: "not_required"}, nil
	}
	lead := samples[0]
	st, err := loadSampleType(r.ctx, r.tx, lead.Req.SampleTypeID)
	if err != nil {
		return nil, err
	}
	list, err := loadJourneyAssignments(r.ctx, r.tx, j.ID)
	if err != nil {
		return nil, err
	}
	anchor := custodyAnchor(list)
	net, err := loadNetwork(r.ctx, r.tx)
	if err != nil {
		return nil, err
	}
	if opts.ExcludeLocations == nil {
		opts.ExcludeLocations = map[string]bool{}
	}
	if opts.ExcludeConnections == nil {
		opts.ExcludeConnections = map[string]bool{}
	}
	startAt := lead.Req.EarliestCollectionAt
	if lead.LastEventAt != nil && lead.LastEventAt.After(startAt) {
		startAt = *lead.LastEventAt
	}
	deadline := lead.Req.DeliveryDeadline
	for _, s := range samples {
		if s.Req.DeliveryDeadline.Before(deadline) {
			deadline = s.Req.DeliveryDeadline
		}
	}
	pin := &planInput{Origin: lead.Req.Origin, OriginType: lead.Req.OriginType, OriginNodeID: lead.Req.OriginNodeID, SampleType: st, StartAt: startAt, Deadline: deadline, Units: len(samples),
		ExcludeLocations: opts.ExcludeLocations, ExcludeConnections: opts.ExcludeConnections, PreferredLabID: opts.PreferredLabID}

	spec := journeySpec{SampleIDs: j.SampleIDs, SampleType: st, ParentJourneyID: strPtr(j.ID), OriginCoord: lead.Req.Origin, OriginType: lead.Req.OriginType, StartAt: startAt, Deadline: deadline, Reason: opts.Reason}
	keep := ""
	var holderUser *User
	if lead.CurrentHolderID != nil {
		holderUser, _ = loadUser(r.ctx, r.tx, *lead.CurrentHolderID)
	}
	switch {
	case anchor == nil && !lead.Sealed:
		spec.NeedsCollection = true
		if lead.Req.OriginType == "node" && lead.Req.OriginNodeID != nil {
			pin.StartLocationID = lead.Req.OriginNodeID
		}
	case anchor == nil && lead.Sealed:
		role := RoleNodeHandler
		if holderUser != nil && holderUser.hasRole(RoleCollector) {
			role = RoleCollector
		}
		spec.Holder = &holderSpec{UserID: derefStr(lead.CurrentHolderID), Role: role}
		if lead.CurrentLocationID != nil {
			pin.StartLocationID = lead.CurrentLocationID
		} else if j.EntryLocationID != nil {
			pin.StartLocationID = j.EntryLocationID
		}
	case anchor.Kind == "collection":
		spec.Anchor = anchor
		keep = anchor.ID
		if lead.Req.OriginType == "node" && lead.Req.OriginNodeID != nil {
			pin.StartLocationID = lead.Req.OriginNodeID
		}
	case anchor.Kind == "node":
		spec.Anchor = anchor
		keep = anchor.ID
		pin.StartLocationID = anchor.NodeID
	case anchor.Kind == "laboratory":
		spec.Anchor = anchor
		keep = anchor.ID
		pin.StartLocationID = anchor.LaboratoryID
	case anchor.Kind == "transport":
		dest := net.locations[derefStr(anchor.ToLocationID)]
		destOK := dest != nil && dest.Active && !opts.ExcludeLocations[dest.ID]
		if anchor.Status == "arrived" || anchor.Status == "delivered" || destOK {
			spec.Anchor = anchor
			keep = anchor.ID
			pin.StartLocationID = anchor.ToLocationID
			pin.StartAt = startAt
			if anchor.EstimatedEndAt != nil && anchor.EstimatedEndAt.After(startAt) {
				pin.StartAt = *anchor.EstimatedEndAt
				spec.StartAt = pin.StartAt
			}
		} else {
			// The courier must divert: give the same courier a new first leg from where the current leg began.
			spec.Holder = &holderSpec{UserID: derefStr(anchor.WorkerID), Role: RoleCourier, Status: anchor.Status}
			pin.StartLocationID = anchor.FromLocationID
		}
	}

	// Release the old plan's reservations before planning so the journey's own
	// reservations do not count against it.
	if err := releaseReservations(r, j.ID, "", "", "replanning"); err != nil {
		return nil, err
	}

	var res *planResult
	if len(opts.ExplicitPath) > 0 {
		var e *APIError
		res, e = net.planFromPath(pin, opts.ExplicitPath)
		if e != nil {
			return nil, e
		}
	} else if opts.Waypoint != nil {
		first := *pin
		first.TargetLocationID = opts.Waypoint
		p1 := net.plan(&first)
		if p1.Reason != "serviceable" {
			if p1.Reason == "deadline_unreachable" {
				res = p1
			} else {
				return nil, errConflict("invalid_stop", "the requested stop cannot be reached: "+p1.Reason)
			}
		} else {
			second := *pin
			second.StartLocationID = opts.Waypoint
			second.StartAt = p1.ArrivalAt
			second.TargetLocationID = nil
			p2 := net.plan(&second)
			if p2.Reason != "serviceable" && p2.Reason != "deadline_unreachable" {
				return nil, errConflict("invalid_stop", "no route from the requested stop to a laboratory: "+p2.Reason)
			}
			ids := []string{}
			for _, l := range p1.Path {
				ids = append(ids, l.ID)
			}
			for _, l := range p2.Path[1:] {
				ids = append(ids, l.ID)
			}
			var e *APIError
			res, e = net.planFromPath(pin, ids)
			if e != nil {
				return nil, e
			}
		}
	} else {
		res = net.plan(pin)
	}

	if res.Reason == "serviceable" && !opts.ForceReplace && spec.Anchor != nil && samePlan(res, list, anchor) {
		// Nothing structural changed; restore reservations and keep the plan.
		for _, s := range samples {
			for i, loc := range res.Path {
				if i == 0 && anchor.Kind == "transport" {
					continue
				}
				if err := reserveCapacity(r, j.ID, s.ID, "location", loc.ID, st.RequiresCooledRoute); err != nil {
					return nil, err
				}
			}
			for _, c := range res.Connections {
				if err := reserveCapacity(r, j.ID, s.ID, "connection", c.ID, st.RequiresCooledRoute); err != nil {
					return nil, err
				}
			}
		}
		return &replanOutcome{Status: "not_required"}, nil
	}

	if res.Reason != "serviceable" {
		status := "exception"
		if res.Reason == "deadline_unreachable" {
			status = "expired"
		}
		if err := a.cancelUnfinishedAssignments(r, j.ID, nilIfEmpty(keep), "replan_"+status); err != nil {
			return nil, err
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE journeys SET replan_status=$2, status=CASE WHEN $2='expired' THEN 'expired' ELSE status END, plan_version=plan_version+1, updated_at=now() WHERE id=$1`, j.ID, status); err != nil {
			return nil, err
		}
		for _, s := range samples {
			if status == "expired" {
				exc := map[string]any{"kind": "deadline_unreachable", "reason": "no valid route can meet the delivery deadline", "observedAt": r.now, "journeyId": j.ID}
				if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET status='expired', exception=$2, updated_at=now() WHERE id=$1`, s.ID, mustJSON(exc)); err != nil {
					return nil, err
				}
				if _, err := r.tx.Exec(r.ctx, `INSERT INTO sample_exceptions (id, sample_id, kind, reason, observed_at, recorded_by) VALUES ($1,$2,'deadline_unreachable','no valid route can meet the delivery deadline',$3,$4)`, newID(), s.ID, r.now, r.sess.UserID); err != nil {
					return nil, err
				}
				r.audit("sample_expired", "sample", s.ID, map[string]any{"reason": "deadline_unreachable", "journeyId": j.ID, "trigger": opts.Reason})
				r.emit("sample.expired", "sample", s.ID, map[string]any{"sampleId": s.ID, "reason": "deadline_unreachable"}, opsRoles, []string{s.Req.RequesterID})
			} else if s.Status != "exception" {
				if err := a.raiseException(r, s, "no_valid_route", "no valid route is available after replanning: "+res.Reason, nil, map[string]any{"journeyId": j.ID, "trigger": opts.Reason, "planReason": res.Reason}); err != nil {
					return nil, err
				}
			}
		}
		r.audit("journey_replanned", "journey", j.ID, map[string]any{"replanStatus": status, "reason": opts.Reason, "planReason": res.Reason, "sampleIds": j.SampleIDs})
		r.emit("journey.replanned", "journey", j.ID, map[string]any{"journeyId": j.ID, "replanStatus": status}, opsRoles, nil)
		return &replanOutcome{Status: status}, nil
	}

	if spec.Anchor != nil && spec.Anchor.Kind == "collection" && spec.Anchor.ToLocationID != nil && *spec.Anchor.ToLocationID != res.Entry.ID {
		if _, err := r.tx.Exec(r.ctx, `UPDATE assignments SET to_location_id=$2, updated_at=now() WHERE id=$1`, spec.Anchor.ID, res.Entry.ID); err != nil {
			return nil, err
		}
	}
	if err := a.cancelUnfinishedAssignments(r, j.ID, nilIfEmpty(keep), "replanned"); err != nil {
		return nil, err
	}
	spec.Plan = res
	nj, err := a.materializeJourney(r, spec)
	if err != nil {
		return nil, err
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE journeys SET status='replaced', replan_status='replaced', replacement_journey_id=$2, plan_version=plan_version+1, updated_at=now() WHERE id=$1`, j.ID, nj.ID); err != nil {
		return nil, err
	}
	if keep != "" {
		if _, err := r.tx.Exec(r.ctx, `UPDATE handoffs SET journey_id=$2 WHERE journey_id=$1 AND status='pending' AND from_assignment_id=$3`, j.ID, nj.ID, keep); err != nil {
			return nil, err
		}
	}
	r.audit("journey_replanned", "journey", j.ID, map[string]any{"replanStatus": "replaced", "replacementJourneyId": nj.ID, "reason": opts.Reason, "sampleIds": j.SampleIDs, "keptAssignmentId": nilIfEmpty(keep)})
	r.emit("journey.replanned", "journey", j.ID, map[string]any{"journeyId": j.ID, "replacementJourneyId": nj.ID, "replanStatus": "replaced"}, opsRoles, nil)
	return &replanOutcome{Status: "replaced", Replacement: nj}, nil
}

func nilIfEmpty(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}

// samePlan reports whether the remaining unfinished legs already follow the new path.
func samePlan(res *planResult, list []*Assignment, anchor *Assignment) bool {
	var remaining []*Connection
	for _, as := range list {
		if as.Kind != "transport" || as.finished() || as.ID == anchor.ID {
			continue
		}
		remaining = append(remaining, &Connection{ID: derefStr(as.ConnectionID)})
	}
	if len(remaining) != len(res.Connections) {
		return false
	}
	for i := range remaining {
		if remaining[i].ID != res.Connections[i].ID {
			return false
		}
	}
	return true
}

// replanForResource replans every active journey whose unfinished work depends on a resource.
func (a *App) replanForResource(r *Req, resourceType, resourceID, reason string) ([]replanRecord, error) {
	var where string
	var args []any
	exclude := replanOpts{Reason: reason, ExcludeLocations: map[string]bool{}, ExcludeConnections: map[string]bool{}}
	switch resourceType {
	case "location", "node", "laboratory", "capacity_location":
		exclude.ExcludeLocations[resourceID] = true
		where = `status IN ('planned','active') AND id IN (SELECT journey_id FROM assignments WHERE status NOT IN ('completed','cancelled','replaced','expired') AND (from_location_id=$1 OR to_location_id=$1 OR node_id=$1 OR laboratory_id=$1))`
		args = []any{resourceID}
	case "connection", "route", "capacity_connection":
		exclude.ExcludeConnections[resourceID] = true
		where = `status IN ('planned','active') AND id IN (SELECT journey_id FROM assignments WHERE status NOT IN ('completed','cancelled','replaced','expired') AND connection_id=$1)`
		args = []any{resourceID}
	case "laboratory_acceptance":
		parts := strings.SplitN(resourceID, ":", 2)
		where = `status IN ('planned','active') AND target_laboratory_id=$1 AND id IN (SELECT active_journey_id FROM samples s JOIN requests q ON q.id=s.request_id WHERE q.sample_type_id=$2)`
		args = []any{parts[0], parts[1]}
	default:
		return nil, nil
	}
	journeys, err := loadJourneysWhere(r.ctx, r.tx, where, args...)
	if err != nil {
		return nil, err
	}
	var out []replanRecord
	for _, j := range journeys {
		list, err := loadJourneyAssignments(r.ctx, r.tx, j.ID)
		if err != nil {
			return nil, err
		}
		anchor := custodyAnchor(list)
		// Work the holder has already completed (e.g. arrived at the disrupted node) is left alone.
		if anchor != nil && anchor.Kind == "transport" && (anchor.Status == "arrived" || anchor.Status == "delivered") && derefStr(anchor.ToLocationID) == resourceID {
			exclude.ExcludeLocations[resourceID] = false
		}
		oc, err := a.replanJourney(r, j, exclude)
		if err != nil {
			if ae, ok := err.(*APIError); ok {
				r.audit("journey_replan_failed", "journey", j.ID, map[string]any{"code": ae.Code, "error": ae.Message, "sampleIds": j.SampleIDs})
				out = append(out, replanRecord{Journey: j, Outcome: &replanOutcome{Status: "exception"}})
				continue
			}
			return nil, err
		}
		out = append(out, replanRecord{Journey: j, Outcome: oc})
	}
	return out, nil
}

type replanRecord struct {
	Journey *Journey
	Outcome *replanOutcome
}

func (a *App) opReportDisruption(r *Req) (any, error) {
	var in struct {
		ResourceType string  `json:"resourceType"`
		ResourceID   string  `json:"resourceId"`
		Reason       string  `json:"reason"`
		OccurredAt   *string `json:"occurredAt"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	at, e := requiredTime(in.OccurredAt, "occurredAt")
	if e != nil {
		return nil, e
	}
	valid := map[string]bool{"location": true, "node": true, "laboratory": true, "connection": true, "route": true, "worker": true, "capacity": true}
	if !valid[in.ResourceType] {
		return nil, errBadRequest("invalid_resource_type", "unknown resourceType")
	}
	if in.ResourceID == "" {
		return nil, errInvalidJSON("resourceId is required")
	}
	var records []replanRecord
	var err error
	affected := map[string]bool{}
	resourceType := in.ResourceType
	switch in.ResourceType {
	case "location", "node", "laboratory":
		loc, err := loadLocation(r.ctx, r.tx, in.ResourceID)
		if err != nil {
			return nil, err
		}
		if loc == nil {
			return nil, errNotFound("location not found")
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE locations SET active=false, updated_at=now() WHERE id=$1`, loc.ID); err != nil {
			return nil, err
		}
		if err := a.bumpNetworkRevision(r); err != nil {
			return nil, err
		}
		records, err = a.replanForResource(r, "location", loc.ID, "disruption_"+in.ResourceType)
		if err != nil {
			return nil, err
		}
		a.requestSnapshot()
	case "connection", "route":
		c, err := loadConnection(r.ctx, r.tx, in.ResourceID)
		if err != nil {
			return nil, err
		}
		if c == nil {
			return nil, errNotFound("connection not found")
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE connections SET active=false, updated_at=now() WHERE id=$1`, c.ID); err != nil {
			return nil, err
		}
		if err := a.bumpNetworkRevision(r); err != nil {
			return nil, err
		}
		records, err = a.replanForResource(r, "connection", c.ID, "disruption_"+in.ResourceType)
		if err != nil {
			return nil, err
		}
		a.requestSnapshot()
	case "worker":
		u, err := loadUser(r.ctx, r.tx, in.ResourceID)
		if err != nil {
			return nil, err
		}
		if u == nil {
			return nil, errNotFound("worker not found")
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE users SET available=false, updated_at=now() WHERE id=$1`, u.ID); err != nil {
			return nil, err
		}
		held, err := loadAssignmentsWhere(r.ctx, r.tx, `worker_id=$1 AND status IN ('offered','accepted')`, u.ID)
		if err != nil {
			return nil, err
		}
		for _, as := range held {
			for _, sid := range as.SampleIDs {
				affected[sid] = true
			}
		}
		if err := a.releaseWorkerOffers(r, u.ID, "worker_disrupted"); err != nil {
			return nil, err
		}
	case "capacity":
		if loc, _ := loadLocation(r.ctx, r.tx, in.ResourceID); loc != nil {
			records, err = a.replanForResource(r, "capacity_location", loc.ID, "disruption_capacity")
		} else if c, _ := loadConnection(r.ctx, r.tx, in.ResourceID); c != nil {
			records, err = a.replanForResource(r, "capacity_connection", c.ID, "disruption_capacity")
		} else {
			return nil, errNotFound("capacity pool not found")
		}
		if err != nil {
			return nil, err
		}
	}
	replacement := []string{}
	status := "not_required"
	rank := map[string]int{"not_required": 0, "replaced": 1, "exception": 2, "expired": 3}
	for _, rec := range records {
		for _, sid := range rec.Journey.SampleIDs {
			affected[sid] = true
		}
		if rec.Outcome.Replacement != nil {
			replacement = append(replacement, rec.Outcome.Replacement.ID)
		}
		if rank[rec.Outcome.Status] > rank[status] {
			status = rec.Outcome.Status
		}
	}
	if resourceType == "worker" && len(affected) > 0 && status == "not_required" {
		status = "replaced"
	}
	affectedIDs := []string{}
	for id := range affected {
		affectedIDs = append(affectedIDs, id)
	}
	id := newID()
	if _, err := r.tx.Exec(r.ctx, `INSERT INTO disruptions (id, resource_type, resource_id, reason, occurred_at, reported_by, affected_sample_ids, replacement_plan_ids, replan_status) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		id, in.ResourceType, in.ResourceID, in.Reason, at, r.sess.UserID, affectedIDs, replacement, status); err != nil {
		return nil, err
	}
	r.audit("disruption_reported", "disruption", id, map[string]any{"resourceType": in.ResourceType, "resourceId": in.ResourceID, "reason": in.Reason, "affectedSampleIds": affectedIDs, "replacementPlanIds": replacement, "replanStatus": status})
	r.emit("disruption.reported", "disruption", id, map[string]any{"disruptionId": id, "resourceType": in.ResourceType, "resourceId": in.ResourceID, "replanStatus": status}, opsRoles, nil)
	a.requestOfferSweep()
	return map[string]any{"disruptionId": id, "affectedSampleIds": affectedIDs, "replacementPlanIds": replacement, "replanStatus": status}, nil
}

func (a *App) opRerouteJourney(r *Req) (any, error) {
	var in struct {
		planVersionInput
		Reason string `json:"reason"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	j, err := a.lockActiveJourney(r, in.JourneyID, in.ExpectedPlanVersion)
	if err != nil {
		return nil, err
	}
	oc, err := a.replanJourney(r, j, replanOpts{Reason: "reroute:" + in.Reason, ForceReplace: true})
	if err != nil {
		return nil, err
	}
	out := map[string]any{"journeyId": j.ID, "replanStatus": oc.Status}
	if oc.Replacement != nil {
		out["replacementPlanId"] = oc.Replacement.ID
		plan, err := a.journeyPlanJSON(r, oc.Replacement, true)
		if err != nil {
			return nil, err
		}
		out["replacementJourney"] = plan
	}
	return out, nil
}

// splitJourney moves a subset of samples out of a batched journey into a new
// journey following the same route, re-offering the unfinished work.
func (a *App) splitJourney(r *Req, j *Journey, sampleIDs []string) (*Journey, error) {
	if len(sampleIDs) == 0 || len(sampleIDs) >= len(j.SampleIDs) {
		return nil, errConflict("invalid_split", "sampleIds must be a non-empty proper subset of the journey's samples")
	}
	moving := map[string]bool{}
	for _, id := range sampleIDs {
		if !containsStr(j.SampleIDs, id) {
			return nil, errConflict("invalid_split", "sample "+id+" is not part of this journey")
		}
		moving[id] = true
	}
	list, err := loadJourneyAssignments(r.ctx, r.tx, j.ID)
	if err != nil {
		return nil, err
	}
	anchor := custodyAnchor(list)
	samples, err := loadSamplesWhere(r.ctx, r.tx, `s.id = ANY($1)`, sampleIDs)
	if err != nil {
		return nil, err
	}
	for _, s := range samples {
		if s.terminal() {
			return nil, errConflict("completed_work_immutable", "sample "+s.ID+" is already "+s.Status)
		}
	}
	lead := samples[0]
	st, err := loadSampleType(r.ctx, r.tx, lead.Req.SampleTypeID)
	if err != nil {
		return nil, err
	}
	net, err := loadNetwork(r.ctx, r.tx)
	if err != nil {
		return nil, err
	}
	// Remaining route = unfinished transport legs of the current plan.
	var pathIDs []string
	for _, as := range list {
		if as.Kind != "transport" || as.finished() {
			continue
		}
		if len(pathIDs) == 0 {
			pathIDs = append(pathIDs, *as.FromLocationID)
		}
		pathIDs = append(pathIDs, *as.ToLocationID)
	}
	if len(pathIDs) == 0 && j.TargetLaboratoryID != nil {
		pathIDs = []string{*j.TargetLaboratoryID}
	}
	startAt := lead.Req.EarliestCollectionAt
	if lead.LastEventAt != nil && lead.LastEventAt.After(startAt) {
		startAt = *lead.LastEventAt
	}
	pin := &planInput{Origin: lead.Req.Origin, OriginType: lead.Req.OriginType, SampleType: st, StartAt: startAt, Deadline: lead.Req.DeliveryDeadline, Units: len(sampleIDs)}
	spec := journeySpec{SampleIDs: sampleIDs, SampleType: st, ParentJourneyID: strPtr(j.ID), OriginCoord: lead.Req.Origin, OriginType: lead.Req.OriginType, StartAt: startAt, Deadline: lead.Req.DeliveryDeadline, Reason: "split"}
	switch {
	case anchor == nil && !lead.Sealed:
		spec.NeedsCollection = true
	case anchor == nil:
		return nil, errConflict("split_in_progress", "samples are in custody without an active leg; split is not possible")
	case anchor.Kind == "transport" && anchor.Status != "arrived" && anchor.Status != "delivered":
		spec.Holder = &holderSpec{UserID: derefStr(anchor.WorkerID), Role: RoleCourier, Status: anchor.Status}
	case anchor.Kind == "transport":
		return nil, errConflict("split_in_progress", "hand the batch over at the current node before splitting it")
	case anchor.Kind == "collection":
		if anchor.Status != "sealed" {
			return nil, errConflict("split_in_progress", "the batch is being collected; split once sealed")
		}
		spec.Holder = &holderSpec{UserID: derefStr(anchor.WorkerID), Role: RoleCollector}
	case anchor.Kind == "node":
		spec.Holder = &holderSpec{UserID: derefStr(anchor.WorkerID), Role: RoleNodeHandler}
	case anchor.Kind == "laboratory":
		return nil, errConflict("split_in_progress", "the batch has already reached the laboratory")
	}
	// Release the moving samples' reservations on the old journey, then plan along the same path.
	for _, sid := range sampleIDs {
		if err := releaseReservations(r, j.ID, "", sid, "split"); err != nil {
			return nil, err
		}
	}
	res, e := net.planFromPath(pin, pathIDs)
	if e != nil {
		return nil, e
	}
	if res.Reason != "serviceable" {
		return nil, errConflict("deadline_exceeded", "the split journey cannot meet its deadline")
	}
	spec.Plan = res
	// Remove the moving samples from the old journey's unfinished assignments and sample list.
	remaining := []string{}
	for _, id := range j.SampleIDs {
		if !moving[id] {
			remaining = append(remaining, id)
		}
	}
	for _, as := range list {
		if as.finished() {
			continue
		}
		keep := []string{}
		for _, id := range as.SampleIDs {
			if !moving[id] {
				keep = append(keep, id)
			}
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE assignments SET sample_ids=$2, updated_at=now() WHERE id=$1`, as.ID, keep); err != nil {
			return nil, err
		}
	}
	mode := "direct"
	if len(remaining) > 1 {
		mode = "batched"
	} else if len(res.Connections) > 1 {
		mode = "multi_stop"
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE journeys SET sample_ids=$2, route_mode=$3, plan_version=plan_version+1, updated_at=now() WHERE id=$1`, j.ID, remaining, mode); err != nil {
		return nil, err
	}
	nj, err := a.materializeJourney(r, spec)
	if err != nil {
		return nil, err
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE journeys SET split_journey_id=$2 WHERE id=$1`, j.ID, nj.ID); err != nil {
		return nil, err
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE handoffs SET journey_id=$2 WHERE journey_id=$1 AND status='pending' AND sample_id = ANY($3)`, j.ID, nj.ID, sampleIDs); err != nil {
		return nil, err
	}
	r.audit("journey_split", "journey", j.ID, map[string]any{"splitJourneyId": nj.ID, "movedSampleIds": sampleIDs, "remainingSampleIds": remaining, "sampleIds": j.SampleIDs})
	r.emit("journey.split", "journey", j.ID, map[string]any{"journeyId": j.ID, "splitJourneyId": nj.ID}, opsRoles, nil)
	return nj, nil
}

func (a *App) opSplitJourney(r *Req) (any, error) {
	var in struct {
		planVersionInput
		SampleIDs []string `json:"sampleIds"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	j, err := a.lockActiveJourney(r, in.JourneyID, in.ExpectedPlanVersion)
	if err != nil {
		return nil, err
	}
	nj, err := a.splitJourney(r, j, in.SampleIDs)
	if err != nil {
		return nil, err
	}
	updated, _ := loadJourney(r.ctx, r.tx, j.ID, false)
	plan, err := a.journeyPlanJSON(r, updated, true)
	if err != nil {
		return nil, err
	}
	split, err := a.journeyPlanJSON(r, nj, true)
	if err != nil {
		return nil, err
	}
	plan["splitJourney"] = split
	return map[string]any{"journey": plan, "splitJourney": split}, nil
}

// batchCompatible validates that a set of samples may share a container/vehicle.
func batchCompatible(samples []*Sample, types map[string]*SampleType) *APIError {
	for i, s := range samples {
		ti := types[s.Req.SampleTypeID]
		if ti == nil {
			return errConflict("invalid_batch", "unknown sample type")
		}
		if !ti.BatchingAllowed && len(samples) > 1 {
			return errConflict("pulse_no_batch", ti.Name+" samples must not be combined into a batch")
		}
		for k, o := range samples {
			if k == i {
				continue
			}
			to := types[o.Req.SampleTypeID]
			if containsStr(ti.IncompatibleSampleTypes, o.Req.SampleTypeID) || containsStr(s.Req.IncompatibleSampleTypes, o.Req.SampleTypeID) {
				return errConflict("incompatible_batch", ti.Name+" must not share a container with "+to.Name)
			}
			if ti.ContainerType != to.ContainerType && s.Req.ContainerType != o.Req.ContainerType {
				return errConflict("incompatible_batch", "container types differ between samples")
			}
			if s.Req.TemperatureMinC > o.Req.TemperatureMaxC || o.Req.TemperatureMinC > s.Req.TemperatureMaxC {
				return errConflict("incompatible_batch", "temperature ranges do not overlap")
			}
			if ti.RequiresCooledRoute != to.RequiresCooledRoute {
				return errConflict("incompatible_batch", "cooled and non-cooled samples cannot share a batch")
			}
		}
	}
	return nil
}

func (a *App) mergeJourneys(r *Req, target *Journey, sourceIDs []string) error {
	if len(sourceIDs) == 0 {
		return errConflict("invalid_merge", "sourceJourneyIds is required")
	}
	tList, err := loadJourneyAssignments(r.ctx, r.tx, target.ID)
	if err != nil {
		return err
	}
	tAnchor := custodyAnchor(tList)
	if tAnchor != nil && tAnchor.Kind == "laboratory" {
		return errConflict("invalid_merge", "the target journey has already reached its laboratory")
	}
	allSamples, err := loadSamplesWhere(r.ctx, r.tx, `s.id = ANY($1)`, target.SampleIDs)
	if err != nil {
		return err
	}
	types, _, err := loadSampleTypes(r.ctx, r.tx)
	if err != nil {
		return err
	}
	net, err := loadNetwork(r.ctx, r.tx)
	if err != nil {
		return err
	}
	var sources []*Journey
	for _, sid := range sourceIDs {
		if sid == target.ID {
			return errConflict("invalid_merge", "a journey cannot be merged into itself")
		}
		sj, err := loadJourney(r.ctx, r.tx, sid, true)
		if err != nil {
			return err
		}
		if sj == nil {
			return errNotFound("source journey " + sid + " not found")
		}
		if !sj.active() {
			return errConflict("inactive_plan", "source journey "+sid+" is "+sj.Status)
		}
		sList, err := loadJourneyAssignments(r.ctx, r.tx, sj.ID)
		if err != nil {
			return err
		}
		sAnchor := custodyAnchor(sList)
		if !sameAnchorPosition(tAnchor, sAnchor, target, sj) {
			if sAnchor != nil || tAnchor != nil {
				return errConflict("partial_journey_merge", "journeys can only be merged while their samples are at the same position with the same holder")
			}
			return errConflict("invalid_merge", "journeys do not start from the same entry node")
		}
		ss, err := loadSamplesWhere(r.ctx, r.tx, `s.id = ANY($1)`, sj.SampleIDs)
		if err != nil {
			return err
		}
		for _, s := range ss {
			if s.terminal() {
				return errConflict("completed_work_immutable", "sample "+s.ID+" is already "+s.Status)
			}
			if !net.labAccepts(derefStr(target.TargetLaboratoryID), s.Req.SampleTypeID) {
				return errConflict("invalid_destination", "the target laboratory does not accept sample "+s.ID)
			}
		}
		allSamples = append(allSamples, ss...)
		sources = append(sources, sj)
	}
	if e := batchCompatible(allSamples, types); e != nil {
		return e
	}
	// Validate the target's remaining legs for every merged sample (cooled route, deadlines).
	for _, as := range tList {
		if as.Kind != "transport" || as.finished() {
			continue
		}
		c, _ := loadConnection(r.ctx, r.tx, derefStr(as.ConnectionID))
		for _, s := range allSamples {
			if types[s.Req.SampleTypeID].RequiresCooledRoute && (c == nil || !c.Cooled) {
				return errConflict("incompatible_batch", "the target route is not cooled")
			}
			if as.EstimatedEndAt != nil && as.EstimatedEndAt.After(s.Req.DeliveryDeadline) {
				return errConflict("deadline_exceeded", "sample "+s.ID+" cannot meet its deadline on the target route")
			}
		}
	}
	for _, s := range allSamples {
		if target.EstimatedDeliveryAt != nil && target.EstimatedDeliveryAt.After(s.Req.DeliveryDeadline) {
			return errConflict("deadline_exceeded", "sample "+s.ID+" cannot meet its deadline on the target route")
		}
	}
	merged := append([]string{}, target.SampleIDs...)
	for _, sj := range sources {
		if err := a.cancelUnfinishedAssignments(r, sj.ID, nil, "merged_into_"+target.ID); err != nil {
			return err
		}
		if err := releaseReservations(r, sj.ID, "", "", "merged"); err != nil {
			return err
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE journeys SET status='merged', replan_status='replaced', replacement_journey_id=$2, plan_version=plan_version+1, updated_at=now() WHERE id=$1`, sj.ID, target.ID); err != nil {
			return err
		}
		for _, sid := range sj.SampleIDs {
			merged = append(merged, sid)
			if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3, updated_at=now() WHERE id=$1`, sid, target.ID, target.TargetLaboratoryID); err != nil {
				return err
			}
			// Reserve capacity on the target's remaining resources for the incoming sample.
			cooled := types[sampleTypeOf(allSamples, sid)].RequiresCooledRoute
			for _, as := range tList {
				if as.finished() {
					continue
				}
				switch as.Kind {
				case "transport":
					if err := reserveCapacity(r, target.ID, sid, "connection", derefStr(as.ConnectionID), cooled); err != nil {
						return err
					}
					if err := reserveCapacity(r, target.ID, sid, "location", derefStr(as.ToLocationID), cooled); err != nil {
						return err
					}
				case "collection":
					if err := reserveCapacity(r, target.ID, sid, "location", derefStr(as.ToLocationID), cooled); err != nil {
						return err
					}
				}
			}
		}
		r.audit("journey_merged", "journey", sj.ID, map[string]any{"targetJourneyId": target.ID, "sampleIds": sj.SampleIDs})
	}
	for _, as := range tList {
		if as.finished() {
			continue
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE assignments SET sample_ids=$2, updated_at=now() WHERE id=$1`, as.ID, merged); err != nil {
			return err
		}
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE journeys SET sample_ids=$2, route_mode='batched', plan_version=plan_version+1, updated_at=now() WHERE id=$1`, target.ID, merged); err != nil {
		return err
	}
	r.audit("journeys_merged", "journey", target.ID, map[string]any{"sourceJourneyIds": sourceIDs, "sampleIds": merged})
	r.emit("journey.merged", "journey", target.ID, map[string]any{"journeyId": target.ID, "sourceJourneyIds": sourceIDs}, opsRoles, nil)
	return nil
}

func sampleTypeOf(samples []*Sample, id string) string {
	for _, s := range samples {
		if s.ID == id {
			return s.Req.SampleTypeID
		}
	}
	return ""
}

func sameAnchorPosition(t, s *Assignment, tj, sj *Journey) bool {
	if t == nil && s == nil {
		return derefStr(tj.EntryLocationID) == derefStr(sj.EntryLocationID)
	}
	if t == nil || s == nil {
		return false
	}
	if t.Kind != s.Kind || derefStr(t.WorkerID) != derefStr(s.WorkerID) {
		return false
	}
	switch t.Kind {
	case "node":
		return derefStr(t.NodeID) == derefStr(s.NodeID)
	case "transport":
		return derefStr(t.ConnectionID) == derefStr(s.ConnectionID)
	case "collection":
		return t.Status == "sealed" && s.Status == "sealed" && derefStr(t.ToLocationID) == derefStr(s.ToLocationID)
	}
	return false
}

func (a *App) opMergeJourneys(r *Req) (any, error) {
	var in struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	j, err := a.lockActiveJourney(r, in.TargetJourneyID, in.ExpectedPlanVersion)
	if err != nil {
		return nil, err
	}
	if err := a.mergeJourneys(r, j, in.SourceJourneyIDs); err != nil {
		return nil, err
	}
	updated, _ := loadJourney(r.ctx, r.tx, j.ID, false)
	return a.journeyPlanJSON(r, updated, true)
}

func (a *App) opEditActivePlan(r *Req) (any, error) {
	var in struct {
		planVersionInput
		ChangeType string                     `json:"changeType"`
		Changes    map[string]json.RawMessage `json:"changes"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	valid := map[string]bool{"add_stop": true, "remove_stop": true, "reorder_stops": true, "replace_worker": true, "reassign_worker": true, "merge_samples": true, "split_samples": true, "split_batch": true, "cancel_work": true, "reroute": true, "replace_route": true}
	if !valid[in.ChangeType] {
		return nil, errBadRequest("invalid_change_type", "unknown changeType")
	}
	if in.Changes == nil {
		in.Changes = map[string]json.RawMessage{}
	}
	getStr := func(keys ...string) string {
		for _, k := range keys {
			if raw, ok := in.Changes[k]; ok {
				var s string
				if json.Unmarshal(raw, &s) == nil {
					return s
				}
			}
		}
		return ""
	}
	getList := func(keys ...string) []string {
		for _, k := range keys {
			if raw, ok := in.Changes[k]; ok {
				var l []string
				if json.Unmarshal(raw, &l) == nil {
					return l
				}
			}
		}
		return nil
	}
	j, err := a.lockActiveJourney(r, in.JourneyID, in.ExpectedPlanVersion)
	if err != nil {
		return nil, err
	}
	var replacement, split *Journey
	switch in.ChangeType {
	case "replace_worker", "reassign_worker":
		asID := getStr("assignmentId", "assignment_id")
		workerID := getStr("workerId", "worker_id", "newWorkerId")
		if asID == "" || workerID == "" {
			return nil, errBadRequest("invalid_worker", "changes.assignmentId and changes.workerId are required")
		}
		as, err := loadAssignment(r.ctx, r.tx, asID, true)
		if err != nil {
			return nil, err
		}
		if as == nil || as.JourneyID != j.ID {
			return nil, errConflict("invalid_assignment", "assignment is not part of this journey")
		}
		if as.finished() {
			return nil, errConflict("completed_work_immutable", "assignment is already finished")
		}
		if as.holding() {
			return nil, errConflict("work_in_progress", "the worker currently holds the sample; custody must be handed off first")
		}
		u, err := loadUser(r.ctx, r.tx, workerID)
		if err != nil {
			return nil, err
		}
		if u == nil {
			return nil, errBadRequest("invalid_worker", "worker not found")
		}
		eligible, err := a.eligibleWorkers(r, &Assignment{Kind: as.Kind, NodeID: as.NodeID, LaboratoryID: as.LaboratoryID, RequiredQualification: as.RequiredQualification}, false)
		if err != nil {
			return nil, err
		}
		found := false
		for _, e := range eligible {
			if e.ID == u.ID {
				found = true
			}
		}
		if !found {
			return nil, errConflict("ineligible_worker", "worker is not eligible for this assignment")
		}
		if !u.Available {
			return nil, errConflict("worker_unavailable", "worker is unavailable")
		}
		previous := as.WorkerID
		if _, err := r.tx.Exec(r.ctx, `UPDATE assignments SET status='offered', worker_id=$2, offered_at=$3, offer_expires_at=$4, accepted_at=NULL, updated_at=now() WHERE id=$1`, as.ID, u.ID, r.now, r.now.Add(a.cfg.OfferTimeout)); err != nil {
			return nil, err
		}
		r.audit("assignment_reassigned", "assignment", as.ID, map[string]any{"journeyId": j.ID, "previousWorkerId": previous, "workerId": u.ID, "sampleId": as.sampleID(), "sampleIds": as.SampleIDs})
		r.emit("assignment.offered", "assignment", as.ID, map[string]any{"assignmentId": as.ID, "kind": as.Kind, "workerId": u.ID, "sampleId": as.sampleID(), "journeyId": j.ID}, opsRoles, []string{u.ID})
		if previous != nil {
			r.emit("assignment.cancelled", "assignment", as.ID, map[string]any{"assignmentId": as.ID, "reason": "reassigned"}, nil, []string{*previous})
		}
		if err := a.bumpPlanVersion(r, j.ID); err != nil {
			return nil, err
		}
	case "add_stop":
		loc := getStr("locationId", "location_id", "stopLocationId")
		if loc == "" {
			return nil, errConflict("invalid_stop", "changes.locationId is required")
		}
		l, err := loadLocation(r.ctx, r.tx, loc)
		if err != nil {
			return nil, err
		}
		if l == nil || !l.Active {
			return nil, errConflict("invalid_stop", "stop location is unknown or inactive")
		}
		oc, err := a.replanJourney(r, j, replanOpts{Reason: "edit:add_stop", Waypoint: strPtr(l.ID), ForceReplace: true})
		if err != nil {
			return nil, err
		}
		replacement = oc.Replacement
		if replacement == nil {
			return nil, errConflict("invalid_plan", "the plan could not be rebuilt with the extra stop ("+oc.Status+")")
		}
	case "remove_stop":
		stopID := getStr("stopId", "stop_id")
		loc := getStr("locationId", "location_id")
		stops, err := loadStops(r.ctx, r.tx, j.ID)
		if err != nil {
			return nil, err
		}
		var target *Stop
		for _, s := range stops {
			if (stopID != "" && s.ID == stopID) || (loc != "" && s.LocationID == loc) {
				target = s
			}
		}
		if target == nil {
			return nil, errConflict("invalid_stop", "stop not found on this journey")
		}
		if target.CompletedAt != nil {
			return nil, errConflict("completed_work_immutable", "the stop has already been completed")
		}
		if target.StopType != "handoff" {
			return nil, errConflict("invalid_stop", "only intermediate handoff stops can be removed")
		}
		oc, err := a.replanJourney(r, j, replanOpts{Reason: "edit:remove_stop", ExcludeLocations: map[string]bool{target.LocationID: true}, ForceReplace: true})
		if err != nil {
			return nil, err
		}
		replacement = oc.Replacement
		if replacement == nil {
			return nil, errConflict("no_valid_route", "no route avoids the removed stop ("+oc.Status+")")
		}
	case "reorder_stops":
		order := getList("stopIds", "stop_ids", "order", "locationIds")
		if len(order) == 0 {
			return nil, errConflict("invalid_stop_order", "changes.stopIds is required")
		}
		stops, err := loadStops(r.ctx, r.tx, j.ID)
		if err != nil {
			return nil, err
		}
		byID := map[string]*Stop{}
		byLoc := map[string]*Stop{}
		for _, s := range stops {
			byID[s.ID] = s
			byLoc[s.LocationID] = s
		}
		var path []string
		for _, id := range order {
			s := byID[id]
			if s == nil {
				s = byLoc[id]
			}
			if s == nil {
				return nil, errConflict("invalid_stop", "unknown stop "+id)
			}
			if s.CompletedAt != nil {
				return nil, errConflict("completed_work_immutable", "completed stops cannot be reordered")
			}
			path = append(path, s.LocationID)
		}
		list, err := loadJourneyAssignments(r.ctx, r.tx, j.ID)
		if err != nil {
			return nil, err
		}
		anchor := custodyAnchor(list)
		if anchor != nil && anchor.Kind == "transport" {
			path = append([]string{derefStr(anchor.ToLocationID)}, path...)
			if len(path) > 1 && path[0] == path[1] {
				path = path[1:]
			}
		}
		oc, err := a.replanJourney(r, j, replanOpts{Reason: "edit:reorder_stops", ExplicitPath: path, ForceReplace: true})
		if err != nil {
			return nil, err
		}
		replacement = oc.Replacement
		if replacement == nil {
			return nil, errConflict("invalid_stop_order", "the requested order is not a valid plan ("+oc.Status+")")
		}
	case "merge_samples":
		if err := a.mergeJourneys(r, j, getList("sourceJourneyIds", "source_journey_ids", "journeyIds")); err != nil {
			return nil, err
		}
	case "split_samples", "split_batch":
		nj, err := a.splitJourney(r, j, getList("sampleIds", "sample_ids"))
		if err != nil {
			return nil, err
		}
		split = nj
	case "cancel_work":
		samples, err := loadSamplesWhere(r.ctx, r.tx, `s.id = ANY($1)`, j.SampleIDs)
		if err != nil {
			return nil, err
		}
		for _, s := range samples {
			if s.Status == "received" {
				return nil, errConflict("completed_work_immutable", "sample "+s.ID+" was already received")
			}
		}
		if err := a.cancelUnfinishedAssignments(r, j.ID, nil, "edit:cancel_work"); err != nil {
			return nil, err
		}
		if err := releaseReservations(r, j.ID, "", "", "edit:cancel_work"); err != nil {
			return nil, err
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE journeys SET status='cancelled', plan_version=plan_version+1, updated_at=now() WHERE id=$1`, j.ID); err != nil {
			return nil, err
		}
		for _, s := range samples {
			if !s.terminal() {
				if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET status='cancelled', updated_at=now() WHERE id=$1`, s.ID); err != nil {
					return nil, err
				}
				r.audit("sample_cancelled", "sample", s.ID, map[string]any{"journeyId": j.ID, "reason": "edit:cancel_work"})
			}
		}
		r.audit("journey_cancelled", "journey", j.ID, map[string]any{"reason": getStr("reason"), "sampleIds": j.SampleIDs})
	case "reroute", "replace_route":
		opts := replanOpts{Reason: "edit:" + in.ChangeType, ForceReplace: true, ExcludeLocations: map[string]bool{}, ExcludeConnections: map[string]bool{}}
		for _, id := range getList("excludeLocationIds", "avoidLocationIds") {
			opts.ExcludeLocations[id] = true
		}
		for _, id := range getList("excludeConnectionIds", "avoidConnectionIds") {
			opts.ExcludeConnections[id] = true
		}
		if lab := getStr("targetLaboratoryId", "laboratoryId"); lab != "" {
			opts.PreferredLabID = strPtr(lab)
		}
		oc, err := a.replanJourney(r, j, opts)
		if err != nil {
			return nil, err
		}
		replacement = oc.Replacement
		if replacement == nil && oc.Status != "not_required" {
			return nil, errConflict("no_valid_route", "no valid replacement route ("+oc.Status+")")
		}
	}
	updated, err := loadJourney(r.ctx, r.tx, j.ID, false)
	if err != nil {
		return nil, err
	}
	r.audit("plan_edited", "journey", j.ID, map[string]any{"changeType": in.ChangeType, "changes": rawChanges(in.Changes), "sampleIds": j.SampleIDs, "planVersion": updated.PlanVersion})
	plan, err := a.journeyPlanJSON(r, updated, true)
	if err != nil {
		return nil, err
	}
	if replacement != nil {
		rp, err := a.journeyPlanJSON(r, replacement, true)
		if err != nil {
			return nil, err
		}
		plan["replacementJourney"] = rp
	}
	if split != nil {
		sp, err := a.journeyPlanJSON(r, split, true)
		if err != nil {
			return nil, err
		}
		plan["splitJourney"] = sp
	}
	return plan, nil
}

func rawChanges(m map[string]json.RawMessage) map[string]any {
	out := map[string]any{}
	for k, v := range m {
		var x any
		_ = json.Unmarshal(v, &x)
		out[k] = x
	}
	return out
}

