package app

import (
	"encoding/json"
	"strings"
	"time"
)

func (a *App) isStale(recordedAt *time.Time) bool {
	return recordedAt == nil || time.Since(*recordedAt) > a.cfg.StaleAfter
}

// journeyPlanJSON renders the full dispatcher view of a journey.
func (a *App) journeyPlanJSON(r *Req, j *Journey, includeNested bool) (map[string]any, error) {
	stops, err := loadStops(r.ctx, r.tx, j.ID)
	if err != nil {
		return nil, err
	}
	list, err := loadJourneyAssignments(r.ctx, r.tx, j.ID)
	if err != nil {
		return nil, err
	}
	legs := []map[string]any{}
	workers := []string{}
	seen := map[string]bool{}
	var collectionIDs, nodeIDs, labIDs, transportIDs []string
	for _, as := range list {
		if as.WorkerID != nil && !seen[*as.WorkerID] {
			seen[*as.WorkerID] = true
			workers = append(workers, *as.WorkerID)
		}
		switch as.Kind {
		case "collection":
			collectionIDs = append(collectionIDs, as.ID)
		case "node":
			nodeIDs = append(nodeIDs, as.ID)
		case "laboratory":
			labIDs = append(labIDs, as.ID)
		case "transport":
			transportIDs = append(transportIDs, as.ID)
			legs = append(legs, as.toLeg())
		}
	}
	stopJSON := []map[string]any{}
	for _, s := range stops {
		stopJSON = append(stopJSON, s.toJSON())
	}
	capUsed := len(j.SampleIDs)
	capAvail := a.routeAvailableCapacity(r, j)
	out := map[string]any{
		"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode, "status": j.Status,
		"totalCostUnits": j.TotalCostUnits, "capacityUsed": capUsed, "capacityAvailable": capAvail,
		"sampleIds": j.SampleIDs, "orderedStops": stopJSON, "legs": legs, "assignedWorkerIds": workers,
		"collectionAssignmentIds": orEmpty(collectionIDs), "nodeAssignmentIds": orEmpty(nodeIDs), "laboratoryAssignmentIds": orEmpty(labIDs),
		"valid": j.active() || j.Status == "completed",
	}
	if j.EstimatedDeliveryAt != nil {
		out["estimatedDeliveryAt"] = *j.EstimatedDeliveryAt
	}
	if j.ParentJourneyID != nil {
		out["parentJourneyId"] = *j.ParentJourneyID
	}
	if len(collectionIDs) > 0 {
		out["collectionAssignmentId"] = collectionIDs[0]
	}
	if len(transportIDs) > 0 {
		out["firstTransportAssignmentId"] = transportIDs[0]
		out["finalTransportAssignmentId"] = transportIDs[len(transportIDs)-1]
		if len(transportIDs) > 2 {
			out["middleTransportAssignmentId"] = transportIDs[1]
		}
	}
	if j.ReplanStatus != "" {
		out["replanStatus"] = j.ReplanStatus
	}
	if includeNested {
		if j.ReplacementJourneyID != nil {
			if rj, _ := loadJourney(r.ctx, r.tx, *j.ReplacementJourneyID, false); rj != nil {
				if plan, err := a.journeyPlanJSON(r, rj, false); err == nil {
					out["replacementJourney"] = plan
				}
			}
		}
		if j.SplitJourneyID != nil {
			if sj, _ := loadJourney(r.ctx, r.tx, *j.SplitJourneyID, false); sj != nil {
				if plan, err := a.journeyPlanJSON(r, sj, false); err == nil {
					out["splitJourney"] = plan
				}
			}
		}
	}
	return out, nil
}

func orEmpty(l []string) []string {
	if l == nil {
		return []string{}
	}
	return l
}

// routeAvailableCapacity is the tightest remaining capacity across the journey's reserved resources.
func (a *App) routeAvailableCapacity(r *Req, j *Journey) int {
	rows, err := r.tx.Query(r.ctx, `SELECT DISTINCT resource_type, resource_id, cooled FROM capacity_reservations WHERE journey_id=$1 AND active`, j.ID)
	if err != nil {
		return 0
	}
	defer rows.Close()
	min := -1
	for rows.Next() {
		var rtype, rid string
		var cooled bool
		if err := rows.Scan(&rtype, &rid, &cooled); err != nil {
			return 0
		}
		var avail int
		table := "locations"
		if rtype == "connection" {
			table = "connections"
		}
		col := "capacity_units - reserved_units"
		if cooled {
			col = "cooled_capacity_units - cooled_reserved_units"
		}
		if err := r.tx.QueryRow(r.ctx, `SELECT `+col+` FROM `+table+` WHERE id=$1`, rid).Scan(&avail); err != nil {
			continue
		}
		if min < 0 || avail < min {
			min = avail
		}
	}
	if min < 0 {
		return 0
	}
	return min
}

func (a *App) opReadJourneyPlan(r *Req) (any, error) {
	var in struct {
		JourneyID string `json:"journeyId"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	j, err := loadJourney(r.ctx, r.tx, in.JourneyID, false)
	if err != nil {
		return nil, err
	}
	if j == nil {
		return nil, errNotFound("journey not found")
	}
	role := r.activeRole()
	switch role {
	case RoleAdministrator, RoleDispatcher:
		return a.journeyPlanJSON(r, j, true)
	case RoleRequester:
		samples, err := loadSamplesWhere(r.ctx, r.tx, `s.id = ANY($1) AND r.requester_id=$2`, j.SampleIDs, r.sess.UserID)
		if err != nil {
			return nil, err
		}
		if len(samples) == 0 {
			return nil, errForbidden("this journey does not carry any of your samples")
		}
		stops, err := loadStops(r.ctx, r.tx, j.ID)
		if err != nil {
			return nil, err
		}
		list, err := loadJourneyAssignments(r.ctx, r.tx, j.ID)
		if err != nil {
			return nil, err
		}
		ids := []string{}
		for _, s := range samples {
			ids = append(ids, s.ID)
		}
		stopJSON := []map[string]any{}
		for _, s := range stops {
			stopJSON = append(stopJSON, s.toJSON())
		}
		legs := []map[string]any{}
		for _, as := range list {
			if as.Kind != "transport" {
				continue
			}
			leg := map[string]any{"sequence": as.Sequence, "status": as.Status}
			if as.FromLocationID != nil {
				leg["fromLocationId"] = *as.FromLocationID
			}
			if as.ToLocationID != nil {
				leg["toLocationId"] = *as.ToLocationID
			}
			legs = append(legs, leg)
		}
		out := map[string]any{"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode, "status": j.Status, "totalCostUnits": j.TotalCostUnits, "sampleIds": ids, "orderedStops": stopJSON, "legs": legs}
		if j.EstimatedDeliveryAt != nil {
			out["estimatedDeliveryAt"] = *j.EstimatedDeliveryAt
		}
		if j.ParentJourneyID != nil {
			out["parentJourneyId"] = *j.ParentJourneyID
		}
		return out, nil
	default:
		list, err := loadJourneyAssignments(r.ctx, r.tx, j.ID)
		if err != nil {
			return nil, err
		}
		var mine []*Assignment
		for _, as := range list {
			if as.WorkerID != nil && *as.WorkerID == r.sess.UserID {
				mine = append(mine, as)
			}
		}
		if len(mine) == 0 {
			return nil, errForbidden("you have no assignment on this journey")
		}
		stops, err := loadStops(r.ctx, r.tx, j.ID)
		if err != nil {
			return nil, err
		}
		relevant := map[string]bool{}
		ids := []string{}
		legs := []map[string]any{}
		var collectionIDs, nodeIDs, labIDs []string
		sampleSet := map[string]bool{}
		for _, as := range mine {
			ids = append(ids, as.ID)
			for _, sid := range as.SampleIDs {
				sampleSet[sid] = true
			}
			if as.FromLocationID != nil {
				relevant[*as.FromLocationID] = true
			}
			if as.ToLocationID != nil {
				relevant[*as.ToLocationID] = true
			}
			if as.NodeID != nil {
				relevant[*as.NodeID] = true
			}
			if as.LaboratoryID != nil {
				relevant[*as.LaboratoryID] = true
			}
			switch as.Kind {
			case "collection":
				collectionIDs = append(collectionIDs, as.ID)
			case "node":
				nodeIDs = append(nodeIDs, as.ID)
			case "laboratory":
				labIDs = append(labIDs, as.ID)
			}
			legs = append(legs, as.toLeg())
		}
		stopJSON := []map[string]any{}
		for _, s := range stops {
			if relevant[s.LocationID] {
				stopJSON = append(stopJSON, s.toJSON())
			}
		}
		sampleIDs := []string{}
		for id := range sampleSet {
			sampleIDs = append(sampleIDs, id)
		}
		out := map[string]any{"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode, "status": j.Status, "scope": "assigned_legs",
			"assignmentIds": ids, "sampleIds": sampleIDs, "legs": legs, "orderedStops": stopJSON,
			"collectionAssignmentIds": orEmpty(collectionIDs), "nodeAssignmentIds": orEmpty(nodeIDs), "laboratoryAssignmentIds": orEmpty(labIDs), "assignedWorkerIds": []string{r.sess.UserID}}
		if j.EstimatedDeliveryAt != nil {
			out["estimatedDeliveryAt"] = *j.EstimatedDeliveryAt
		}
		if j.ParentJourneyID != nil {
			out["parentJourneyId"] = *j.ParentJourneyID
		}
		return out, nil
	}
}

// canSeeSample enforces data-level access: owners, custodians/assigned workers and operations roles.
func (a *App) canSeeSample(r *Req, s *Sample) (bool, error) {
	if r.isOps() {
		return true, nil
	}
	role := r.activeRole()
	if role == RoleRequester {
		return s.Req.RequesterID == r.sess.UserID, nil
	}
	if s.CurrentHolderID != nil && *s.CurrentHolderID == r.sess.UserID {
		return true, nil
	}
	if s.Req.CreatedBy == r.sess.UserID {
		return true, nil
	}
	var n int
	if err := r.tx.QueryRow(r.ctx, `SELECT count(*) FROM assignments WHERE $1 = ANY(sample_ids) AND worker_id=$2`, s.ID, r.sess.UserID).Scan(&n); err != nil {
		return false, err
	}
	if n > 0 {
		return true, nil
	}
	// Node handlers and laboratory operators may see samples routed through their location.
	if r.sess.AssignedLocationID != nil && (role == RoleNodeHandler || role == RoleLaboratory) {
		if s.TargetLaboratoryID != nil && *s.TargetLaboratoryID == *r.sess.AssignedLocationID {
			return true, nil
		}
		if err := r.tx.QueryRow(r.ctx, `SELECT count(*) FROM assignments WHERE $1 = ANY(sample_ids) AND (node_id=$2 OR laboratory_id=$2 OR to_location_id=$2)`, s.ID, *r.sess.AssignedLocationID).Scan(&n); err != nil {
			return false, err
		}
		return n > 0, nil
	}
	return false, nil
}

func (a *App) sampleLocationFields(s *Sample, m map[string]any) {
	if s.LatestLat != nil && s.LatestLng != nil {
		m["latestLocation"] = Coordinate{*s.LatestLat, *s.LatestLng}
	}
	if s.LocationRecordedAt != nil {
		m["locationRecordedAt"] = *s.LocationRecordedAt
	}
	m["locationStale"] = a.isStale(s.LocationRecordedAt)
}

func (a *App) opReadSampleState(r *Req, sampleID string) (any, error) {
	s, err := loadSample(r.ctx, r.tx, sampleID, false)
	if err != nil {
		return nil, err
	}
	if s == nil {
		return nil, errNotFound("sample not found")
	}
	ok, err := a.canSeeSample(r, s)
	if err != nil {
		return nil, err
	}
	if !ok {
		return nil, errForbidden("you may not view this sample")
	}
	timeline, err := timelineFor(r.ctx, r.tx, s.ID)
	if err != nil {
		return nil, err
	}
	ids, err := activeAssignmentIDs(r, s.ID)
	if err != nil {
		return nil, err
	}
	out := map[string]any{
		"sampleId": s.ID, "requestId": s.RequestID, "requesterId": s.Req.RequesterID, "origin": s.Req.Origin, "originType": s.Req.OriginType,
		"requestedAt": s.Req.RequestedAt, "deliveryDeadline": s.Req.DeliveryDeadline, "sampleTypeId": s.Req.SampleTypeID, "containerType": s.Req.ContainerType,
		"temperatureMinC": s.Req.TemperatureMinC, "temperatureMaxC": s.Req.TemperatureMaxC, "incompatibleSampleTypes": s.Req.IncompatibleSampleTypes,
		"serviceability": s.Serviceability, "activeAssignmentIds": ids, "state": map[string]any{"status": s.Status}, "timeline": timeline,
	}
	if s.ActiveJourneyID != nil {
		out["activeJourneyId"] = *s.ActiveJourneyID
	}
	if s.TargetLaboratoryID != nil {
		out["targetLaboratoryId"] = *s.TargetLaboratoryID
	}
	a.sampleLocationFields(s, out)
	return out, nil
}

func (a *App) opReadSampleLifecycle(r *Req) (any, error) {
	var in struct {
		SampleID string `json:"sampleId"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	s, err := loadSample(r.ctx, r.tx, in.SampleID, false)
	if err != nil {
		return nil, err
	}
	if s == nil {
		return nil, errNotFound("sample not found")
	}
	ok, err := a.canSeeSample(r, s)
	if err != nil {
		return nil, err
	}
	if !ok {
		return nil, errForbidden("you may not view this sample")
	}
	timeline, err := timelineFor(r.ctx, r.tx, s.ID)
	if err != nil {
		return nil, err
	}
	completed, err := loadAssignmentsWhere(r.ctx, r.tx, `$1 = ANY(sample_ids) AND status='completed'`, s.ID)
	if err != nil {
		return nil, err
	}
	completedIDs := []string{}
	for _, as := range completed {
		completedIDs = append(completedIDs, as.ID)
	}
	replacements := []string{}
	if s.ActiveJourneyID != nil {
		js, err := loadJourneysWhere(r.ctx, r.tx, `parent_journey_id IS NOT NULL AND status IN ('planned','active') AND $1 = ANY(sample_ids)`, s.ID)
		if err != nil {
			return nil, err
		}
		for _, j := range js {
			replacements = append(replacements, j.ID)
		}
	}
	out := map[string]any{"sampleId": s.ID, "status": s.Status, "sealed": s.Sealed, "completedLegIds": completedIDs, "activeReplacementPlanIds": replacements, "timeline": timeline}
	if s.ActiveJourneyID != nil {
		out["activeJourneyId"] = *s.ActiveJourneyID
	}
	if s.CurrentHolderID != nil {
		out["currentHolderId"] = *s.CurrentHolderID
	}
	if s.ReceivedLaboratoryID != nil {
		out["receivedLaboratoryId"] = *s.ReceivedLaboratoryID
	}
	if s.Exception != nil {
		out["exception"] = s.Exception
	}
	pending, err := loadHandoffsWhere(r.ctx, r.tx, `sample_id=$1 AND status='pending'`, s.ID)
	if err != nil {
		return nil, err
	}
	if len(pending) > 0 {
		out["pendingHandoffId"] = pending[0].ID
		out["pendingHandoff"] = pending[0].toJSON()
	}
	a.sampleLocationFields(s, out)
	return out, nil
}

