func (a *App) eventsSince(ctx context.Context, sess *Session, since int64, limit int) ([]RealtimeEvent, error) {
        rows, err := a.pool.Query(ctx, `SELECT id, type, entity_type, entity_id, payload, audience_roles, audience_user_ids, created_at FROM realtime_events WHERE id > $1 ORDER BY id ASC LIMIT $2`, since, limit)
        if err != nil {
                return nil, err
        }
        defer rows.Close()
        out := []RealtimeEvent{}
        for rows.Next() {
                var e RealtimeEvent
                var payload []byte
                if err := rows.Scan(&e.ID, &e.Type, &e.EntityType, &e.EntityID, &payload, &e.roles, &e.userIDs, &e.CreatedAt); err != nil {
                        return nil, err
                }
                e.Payload = map[string]any{}
                _ = json.Unmarshal(payload, &e.Payload)
                if e.visibleTo(sess) {
                        out = append(out, e)
                }
        }
        return out, rows.Err()
}

