export class ApiError extends Error {
  status: number
  code: string
  constructor(status: number, code: string, message: string) {
    super(message)
    this.status = status
    this.code = code
  }
}

const TOKEN_KEY = 'labsample.sessionToken'

export function getToken(): string | null {
  return localStorage.getItem(TOKEN_KEY)
}
export function setToken(token: string | null) {
  if (token) localStorage.setItem(TOKEN_KEY, token)
  else localStorage.removeItem(TOKEN_KEY)
}

export function newIdempotencyKey(): string {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) return crypto.randomUUID()
  return `${Date.now()}-${Math.random().toString(36).slice(2)}`
}

async function request<T>(method: string, path: string, body?: unknown): Promise<T> {
  const headers: Record<string, string> = { Accept: 'application/json' }
  const token = getToken()
  if (token) headers.Authorization = `Bearer ${token}`
  if (body !== undefined) headers['Content-Type'] = 'application/json'
  const res = await fetch(path, { method, headers, body: body === undefined ? undefined : JSON.stringify(body) })
  const text = await res.text()
  let parsed: any = null
  try {
    parsed = text ? JSON.parse(text) : null
  } catch {
    parsed = null
  }
  if (!res.ok) {
    const code = parsed?.code ?? 'http_error'
    const message = parsed?.error ?? `Request failed with status ${res.status}`
    if (res.status === 401 && token && path !== '/api/authenticate-user') {
      setToken(null)
      window.dispatchEvent(new Event('labsample:unauthorized'))
    }
    throw new ApiError(res.status, code, message)
  }
  return (parsed && 'data' in parsed ? parsed.data : parsed) as T
}

export const api = {
  post: <T>(op: string, body: unknown = {}) => request<T>('POST', `/api/${op}`, body),
  get: <T>(path: string) => request<T>('GET', `/api/${path}`),
}

export function describeError(err: unknown): string {
  if (err instanceof ApiError) return `${err.message} (${err.code})`
  if (err instanceof Error) return err.message
  return String(err)
}

