      )
      setToken(data.sessionToken)
      setLoading(true)
      await refresh()
    },
    [refresh],
  )

  const logout = useCallback(() => {
    setToken(null)
    setUser(null)
    setAssignedLocationId(null)
    socketRef.current?.close()
  }, [])

  const selectRole = useCallback(async (role: Role) => {
    const data = await api.post<{ activeRole: string; roles: string[] }>('select-active-role', { role })
    setUser((u) => (u ? { ...u, activeRole: data.activeRole, roles: data.roles } : u))
    setTick((t) => t + 1)
  }, [])

  const value = useMemo<SessionState>(
    () => ({ loading, user, catalogue, assignedLocationId, tick, lastEvent, login, logout, selectRole, refresh }),
    [loading, user, catalogue, assignedLocationId, tick, lastEvent, login, logout, selectRole, refresh],
  )
  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>
}

export function useSession(): SessionState {
  const ctx = useContext(SessionContext)
  if (!ctx) throw new Error('useSession must be used inside SessionProvider')
  return ctx
}

export function useLocationName() {
  const { catalogue } = useSession()
  return useCallback(
    (id?: string | null) => {
      if (!id) return '—'
      return catalogue.locations.find((l) => l.locationId === id)?.name ?? id.slice(0, 8)
    },
    [catalogue.locations],
  )
}

export function useSampleTypeName() {
  const { catalogue } = useSession()
  return useCallback(
    (id?: string | null) => {
      if (!id) return '—'
      return catalogue.sampleTypes.find((t) => t.sampleTypeId === id)?.name ?? id.slice(0, 8)
    },
    [catalogue.sampleTypes],
  )
}

