import type { ReactNode } from 'react'
import { fmtTime, humanize } from '../lib/format'
import type { TimelineEntry } from '../lib/types'

export function Alert({ kind, children }: { kind: 'error' | 'success' | 'info'; children: ReactNode }) {
  return (
    <div role={kind === 'error' ? 'alert' : 'status'} className={`alert alert-${kind}`}>
      {children}
    </div>
  )
}

export function Badge({ children, tone }: { children: ReactNode; tone?: 'ok' | 'warn' | 'bad' | 'muted' }) {
  return <span className={`badge badge-${tone ?? 'muted'}`}>{children}</span>
}

export function Panel({ title, children, actions }: { title: string; children: ReactNode; actions?: ReactNode }) {
  return (
    <section className="panel" aria-label={title}>
      <header className="panel-header">
        <h2>{title}</h2>
        {actions}
      </header>
      <div className="panel-body">{children}</div>
    </section>
  )
}

export function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) {
  return (
    <label className="field">
      <span className="field-label">{label}</span>
      {children}
      {hint && <span className="field-hint">{hint}</span>}
    </label>
  )
}

export function KeyValue({ items }: { items: [string, ReactNode][] }) {
  return (
    <dl className="kv">
      {items.map(([k, v]) => (
        <div key={k} className="kv-row">
          <dt>{k}</dt>
          <dd>{v}</dd>
        </div>
      ))}
    </dl>
  )
}

export function Timeline({ entries, title = 'Status timeline' }: { entries: TimelineEntry[]; title?: string }) {
  const sorted = [...entries].sort((a, b) => a.eventId - b.eventId)
  return (
    <div>
      <h3>{title}</h3>
      {sorted.length === 0 ? (
        <p className="muted">No status changes recorded yet.</p>
      ) : (
        <ol className="timeline" aria-label={title}>
          {sorted.map((e, i) => (
            <li key={e.eventId}>
              <span className="timeline-step">{i + 1}</span>
              <span className="timeline-action">{humanize(e.action)}</span>
              <span className="timeline-meta">
                {fmtTime(e.occurredAt)} · {humanize(e.role)} {e.success ? '' : '· failed'}
              </span>
              {renderDetails(e.details)}
            </li>
          ))}
        </ol>
      )}
    </div>
  )
}

function renderDetails(d: Record<string, unknown>) {
  const keys = Object.keys(d ?? {}).filter((k) => !['before', 'after'].includes(k))
  if (keys.length === 0) return null
  const parts = keys.slice(0, 6).map((k) => `${k}: ${summarize(d[k])}`)
  return <span className="timeline-details">{parts.join(' · ')}</span>
}

function summarize(v: unknown): string {
  if (v == null) return '—'
  if (typeof v === 'string') return v.length > 40 ? v.slice(0, 37) + '…' : v
  if (typeof v === 'number' || typeof v === 'boolean') return String(v)
  if (Array.isArray(v)) return `[${v.length}]`
  return '{…}'
}

export function StaleBadge({ stale, recordedAt }: { stale: boolean; recordedAt?: string }) {
  return (
    <span className="freshness">
      <Badge tone={stale ? 'warn' : 'ok'}>{stale ? 'Location stale' : 'Location fresh'}</Badge>
      <span className="muted"> Last update: {fmtTime(recordedAt)}</span>
    </span>
  )
}

export function StatusBadge({ status }: { status: string }) {
  const bad = ['exception', 'expired', 'cancelled', 'unserviceable', 'declined'].includes(status)
  const ok = ['received', 'completed', 'delivered', 'accepted', 'sealed'].includes(status)
  return <Badge tone={bad ? 'bad' : ok ? 'ok' : 'muted'}>{humanize(status)}</Badge>
}

