import { describeError } from './lib/api'
import LoginPage from './pages/LoginPage'
import WorkPage from './pages/WorkPage'
import SamplePage from './pages/SamplePage'
import NewRequestPage from './pages/NewRequestPage'
import MonitorPage from './pages/MonitorPage'
import AuditPage from './pages/AuditPage'
import AdminPage from './pages/AdminPage'
import CapacityPage from './pages/CapacityPage'
import MapPage from './pages/MapPage'
import JourneyPage from './pages/JourneyPage'
import PresealedPage from './pages/PresealedPage'
import { Alert } from './components/ui'

const OPS_ROLES = ['administrator', 'dispatcher']
const CUSTODIAN_ROLES = ['collection_professional', 'delivery_partner', 'node_handler', 'laboratory_team']

export default function App() {
  const { loading, user } = useSession()
  if (loading) {
    return (
      <main className="centered">
        <p role="status">Loading…</p>
      </main>
    )
  }
  return (
    <Routes>
      <Route path="/login" element={user ? <Navigate to="/" replace /> : <LoginPage />} />
      <Route element={user ? <Shell /> : <Navigate to="/login" replace />}>
        <Route index element={<WorkPage />} />
        <Route path="work" element={<WorkPage />} />
        <Route path="samples/:sampleId" element={<SamplePage />} />
        <Route path="journeys/:journeyId" element={<JourneyPage />} />
        <Route path="requests/new" element={<NewRequestPage />} />
        <Route path="presealed" element={<PresealedPage />} />
        <Route path="monitor" element={<MonitorPage />} />
        <Route path="audit" element={<AuditPage />} />
        <Route path="admin" element={<AdminPage />} />
        <Route path="capacity" element={<CapacityPage />} />
        <Route path="map" element={<MapPage />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Route>
    </Routes>
  )
}

function Shell() {
  const { user, logout, selectRole } = useSession()
  const navigate = useNavigate()
  const [roleError, setRoleError] = useState<string | null>(null)
  if (!user) return null
  const role = user.activeRole
  const isOps = OPS_ROLES.includes(role)
  const isCustodian = CUSTODIAN_ROLES.includes(role)

  const onRoleChange = async (e: React.ChangeEvent<HTMLSelectElement>) => {
    const r = e.target.value as Role
    if (!r) return
    setRoleError(null)
    try {
      await selectRole(r)
      navigate('/work')
    } catch (err) {
      setRoleError(describeError(err))
    }
  }

  return (
    <div className="shell">
      <header className="topbar">
        <div className="brand">
          <NavLink to="/">Lab Sample Logistics</NavLink>
        </div>
        <nav className="nav" aria-label="Main navigation">
          <NavLink to="/work">My work</NavLink>
          {role === 'requester' && <NavLink to="/requests/new">New request</NavLink>}
          {isCustodian && <NavLink to="/presealed">Register pre-sealed sample</NavLink>}
          {(role === 'node_handler' || role === 'laboratory_team') && <NavLink to="/capacity">Capacity</NavLink>}
          {isOps && <NavLink to="/monitor">Monitor</NavLink>}
          {isOps && <NavLink to="/audit">Audit</NavLink>}
          {role === 'administrator' && <NavLink to="/admin">Administration</NavLink>}
          <NavLink to="/map">Map</NavLink>
        </nav>
        <div className="session">
          <span className="username" aria-label="Signed in user">
            {user.fullName || user.username}
          </span>
          <label className="role-select">
            <span>Active role</span>
            <select value={role} onChange={onRoleChange} aria-label="Active role">
              {!role && <option value="">Select a role…</option>}
              {user.roles.map((r) => (
                <option key={r} value={r}>
                  {ROLE_LABELS[r as Role] ?? r}
                </option>
              ))}
            </select>
          </label>
          <button type="button" className="btn btn-secondary" onClick={() => { logout(); navigate('/login') }}>
            Sign out
          </button>
        </div>
      </header>
      {roleError && <Alert kind="error">{roleError}</Alert>}
      <main className="content">
        {!role ? (
          <Alert kind="info">Select the role you are working under to see your work.</Alert>
        ) : (
          <p className="role-banner">
            Working as <strong>{ROLE_LABELS[role as Role] ?? role}</strong>
          </p>
        )}
        <Outlet />
      </main>
    </div>
  )
}

