func (a *App) opReadSampleLifecycle(r *Req) (any, error) {
	var in struct {
		SampleID string `json:"sampleId"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	s, err := loadSample(r.ctx, r.tx, in.SampleID, false)
	if err != nil {
		return nil, err
	}
