                Confirm handoff as {canConfirmSender ? 'sender' : 'receiver'}
              </button>
            </div>
          )}
          {iHold && !pending && nextLeg && nextLeg.workerId && lifecycle?.sealed && (
            <HandoffForm item={item} nextLeg={nextLeg} busy={busy} run={run} />
          )}
        </div>
      )}

      <button type="button" className="link-btn" onClick={() => setShowHistory((s) => !s)} aria-expanded={showHistory}>
        {showHistory ? 'Hide status timeline' : 'Show status timeline'}
      </button>
      {showHistory && <Timeline entries={item.history} />}
    </article>
  )
}

type Runner = (label: string, fn: () => Promise<unknown>) => Promise<void>

function CollectSealForm({ item, busy, run }: { item: AssignmentWorkItem; busy: boolean; run: Runner }) {
  const [containerType, setContainerType] = useState('')
  const [temp, setTemp] = useState('')
  const submit = (e: FormEvent) => {
    e.preventDefault()
    void run('Collection and sealing', () =>
      api.post('collect-and-seal-sample', {
        sampleId: item.sampleId,
        assignmentId: item.assignmentId,
        collectedAt: nowIso(),
        containerType,
        observedTemperatureC: Number(temp),
        idempotencyKey: newIdempotencyKey(),
      }),
    )
  }
  return (
    <form className="subpanel" onSubmit={submit} aria-label="Collect and seal sample">
      <h4>Collect and seal</h4>
      <Field label="Container type">
        <input value={containerType} onChange={(e) => setContainerType(e.target.value)} required />
      </Field>
      <Field label="Observed temperature (°C)">
        <input type="number" step="0.1" value={temp} onChange={(e) => setTemp(e.target.value)} required />
      </Field>
      <button type="submit" className="btn" disabled={busy}>
        Record collected and sealed
      </button>
    </form>
  )
}

function ProgressForm({ item, steps, busy, run }: { item: AssignmentWorkItem; steps: readonly string[]; busy: boolean; run: Runner }) {
  const currentIdx = steps.indexOf(item.status)
  const [status, setStatus] = useState(steps[Math.min(currentIdx + 1, steps.length - 1)])
  return (
    <form
      className="subpanel"
      aria-label="Update progress"
      onSubmit={(e) => {
        e.preventDefault()
        void run('Progress update', () =>
          api.post('update-assignment-progress', { assignmentId: item.assignmentId, status, occurredAt: nowIso(), idempotencyKey: newIdempotencyKey() }),
        )
      }}
    >
      <h4>Update progress</h4>
      <Field label="New status">
        <select value={status} onChange={(e) => setStatus(e.target.value)}>
          {steps.map((s) => (
            <option key={s} value={s}>
              {humanize(s)}
            </option>
          ))}
        </select>
      </Field>
      <button type="submit" className="btn" disabled={busy}>
        Record progress
      </button>
    </form>
  )
}

function LocationForm({ item, busy, run }: { item: AssignmentWorkItem; busy: boolean; run: Runner }) {
  const [lat, setLat] = useState('12.9716')
  const [lng, setLng] = useState('77.5946')
  const [seq, setSeq] = useState(() => Number(localStorage.getItem(`loc-seq-${item.assignmentId}`) ?? 0) + 1)
  const useDevice = () => {
    navigator.geolocation?.getCurrentPosition((p) => {
      setLat(p.coords.latitude.toFixed(6))
      setLng(p.coords.longitude.toFixed(6))
    })
  }
  return (
    <form
      className="subpanel"
      aria-label="Record location"
      onSubmit={(e) => {
        e.preventDefault()
        void run('Location', async () => {
          await api.post('record-worker-location', {
            assignmentId: item.assignmentId,
            coordinate: { latitude: Number(lat), longitude: Number(lng) },
            sequence: seq,
            recordedAt: nowIso(),
