}

function HandoffForm({ item, nextLeg, busy, run }: { item: AssignmentWorkItem; nextLeg: JourneyLeg; busy: boolean; run: Runner }) {
  const locName = useLocationName()
  return (
    <div className="subpanel">
      <h4>Hand off to next leg</h4>
      <p className="muted">
        Next: {humanize(nextLeg.status)} leg {nextLeg.sequence} → {locName(nextLeg.toLocationId)}
      </p>
      <button
        type="button"
        className="btn"
        disabled={busy || !['accepted', 'at_pickup', 'picked_up', 'in_transit', 'arrived', 'in_progress'].includes(nextLeg.status)}
        onClick={() =>
          run('Handoff initiation', () =>
            api.post('initiate-handoff', {
              sampleId: item.sampleId,
              fromAssignmentId: item.assignmentId,
              toAssignmentId: nextLeg.assignmentId,
              receiverId: nextLeg.workerId,
              initiatedAt: nowIso(),
              idempotencyKey: newIdempotencyKey(),
            }),
          )
        }
      >
        Initiate handoff
      </button>
      {!['accepted', 'at_pickup', 'picked_up', 'in_transit', 'arrived', 'in_progress'].includes(nextLeg.status) && (
        <p className="muted">The next worker must accept their assignment before a handoff can start.</p>
      )}
    </div>
  )
}

