import { useCallback, useEffect, useMemo, useState, type FormEvent } from 'react'
import { Link } from 'react-router-dom'
import { api, describeError, newIdempotencyKey } from '../lib/api'
import { useLocationName, useSession } from '../lib/session'
import type { OperationsState } from '../lib/types'
import { fmtCoord, fmtTime, humanize, nowIso } from '../lib/format'
import { Alert, Badge, Field, Panel, StaleBadge, StatusBadge } from '../components/ui'
import LiveMap, { type MapMarker } from '../components/LiveMap'

const CATEGORIES = ['samples', 'workers', 'locations', 'laboratories', 'connections', 'routes', 'handoffs', 'delays', 'exceptions'] as const
type Category = (typeof CATEGORIES)[number]

export default function MonitorPage() {
  const { tick } = useSession()
  const locName = useLocationName()
  const [ops, setOps] = useState<OperationsState | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [category, setCategory] = useState<Category>('samples')
  const [notice, setNotice] = useState<{ kind: 'error' | 'success'; text: string } | null>(null)

  const load = useCallback(async () => {
    try {
      setOps(await api.post<OperationsState>('read-operations-state', {}))
      setError(null)
    } catch (err) {
      setError(describeError(err))
    }
  }, [])

  useEffect(() => {
    void load()
  }, [load, tick])

  const markers = useMemo<MapMarker[]>(() => {
    if (!ops) return []
    const m: MapMarker[] = []
    for (const s of ops.samples) {
      if (s.latestLocation) m.push({ id: `s-${s.sampleId}`, coordinate: s.latestLocation, label: `Sample ${s.sampleId.slice(0, 8)} (${humanize(s.status)})`, kind: 'sample', stale: s.locationStale })
      else if (s.origin && !['received', 'cancelled'].includes(s.status)) m.push({ id: `o-${s.sampleId}`, coordinate: s.origin, label: `Origin of sample ${s.sampleId.slice(0, 8)}`, kind: 'origin' })
    }
    for (const w of ops.workers) {
      if (w.latestLocation) m.push({ id: `w-${w.workerId}`, coordinate: w.latestLocation, label: `${w.fullName ?? 'Worker'} (${w.roles?.map(humanize).join(', ')})`, kind: 'worker', stale: w.locationStale })
    }
    return m
  }, [ops])

  const act = async (label: string, fn: () => Promise<unknown>) => {
    setNotice(null)
    try {
      await fn()
      setNotice({ kind: 'success', text: `${label} applied.` })
      await load()
    } catch (err) {
      setNotice({ kind: 'error', text: describeError(err) })
    }
  }

  if (error) return <Alert kind="error">{error}</Alert>
  if (!ops) return <p role="status">Loading operations state…</p>

  const laboratories = ops.locations.filter((l) => l.functions.laboratory)
  const counts: Record<Category, number> = {
    samples: ops.samples.length,
    workers: ops.workers.length,
    locations: ops.locations.length,
    laboratories: laboratories.length,
    connections: ops.connections.length,
    routes: ops.routes.length,
    handoffs: ops.handoffs.length,
    delays: ops.delays.length,
    exceptions: ops.exceptions.length,
  }

  return (
    <div className="page">
      <h1>Operations monitor</h1>
      <div className="stats" aria-label="Summary">
        <Badge>Assignment spread: {ops.assignmentCountSpread}</Badge>
        <Badge tone={ops.ineligibleAssignmentCount ? 'bad' : 'ok'}>Ineligible assignments: {ops.ineligibleAssignmentCount}</Badge>
        <Badge tone={counts.exceptions ? 'bad' : 'ok'}>Exceptions: {counts.exceptions}</Badge>
        <Badge tone={counts.delays ? 'warn' : 'ok'}>Delays: {counts.delays}</Badge>
      </div>
      {notice && <Alert kind={notice.kind}>{notice.text}</Alert>}
      <LiveMap locations={ops.locations} connections={ops.connections} markers={markers} height={380} />
      <div className="tabs" role="tablist" aria-label="Monitor categories">
        {CATEGORIES.map((c) => (
          <button key={c} role="tab" type="button" aria-selected={category === c} className={`tab${category === c ? ' tab-active' : ''}`} onClick={() => setCategory(c)}>
            {humanize(c)} ({counts[c]})
          </button>
        ))}
      </div>
      <Panel title={humanize(category)}>
        {category === 'samples' && (
          <table className="table">
            <thead>
              <tr>
                <th>Sample</th>
                <th>Status</th>
                <th>Current holder</th>
                <th>Deadline</th>
                <th>Last location</th>
                <th>Freshness</th>
                <th>Journey</th>
              </tr>
            </thead>
            <tbody>
              {ops.samples.map((s) => (
                <tr key={s.sampleId}>
                  <td>
                    <Link to={`/samples/${s.sampleId}`}>{s.sampleId.slice(0, 8)}</Link>
                  </td>
                  <td>
                    <StatusBadge status={s.status} />
                  </td>
                  <td>{s.currentHolderId ? workerName(ops, s.currentHolderId) : '—'}</td>
                  <td>{fmtTime(s.deliveryDeadline)}</td>
                  <td>{fmtCoord(s.latestLocation)}</td>
                  <td>
                    <StaleBadge stale={s.locationStale} recordedAt={s.locationRecordedAt} />
                  </td>
                  <td>{s.activeJourneyId ? <Link to={`/journeys/${s.activeJourneyId}`}>{s.activeJourneyId.slice(0, 8)}</Link> : '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
        {category === 'workers' && (
          <table className="table">
            <thead>
              <tr>
                <th>Worker</th>
                <th>Roles</th>
                <th>Availability</th>
                <th>Capacity</th>
                <th>Assignments</th>
                <th>Location</th>
                <th>Freshness</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {ops.workers.map((w) => (
                <tr key={w.workerId}>
                  <td>{w.fullName ?? w.workerId.slice(0, 8)}</td>
                  <td>{w.roles?.map(humanize).join(', ')}</td>
                  <td>
                    <Badge tone={w.available ? 'ok' : 'warn'}>{humanize(w.status)}</Badge>
                  </td>
                  <td>{w.capacityUnits}</td>
                  <td>{w.assignmentCount}</td>
                  <td>{fmtCoord(w.latestLocation)}</td>
                  <td>
                    <StaleBadge stale={w.locationStale} recordedAt={w.locationRecordedAt} />
                  </td>
                  <td>
                    <button
                      type="button"
                      className="btn btn-small"
                      onClick={() => act('Availability change', () => api.post('set-worker-availability', { workerId: w.workerId, available: !w.available, capacityUnits: w.capacityUnits }))}
                    >
                      Mark {w.available ? 'unavailable' : 'available'}
                    </button>
                    <button
                      type="button"
                      className="btn btn-small btn-danger"
                      onClick={() => act('Disruption', () => api.post('report-disruption', { resourceType: 'worker', resourceId: w.workerId, occurredAt: nowIso(), idempotencyKey: newIdempotencyKey() }))}
                    >
                      Report disruption
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
        {(category === 'locations' || category === 'laboratories') && (
          <table className="table">
            <thead>
              <tr>
                <th>Name</th>
                <th>Functions</th>
                <th>Active</th>
                <th>Capacity (regular / cooled available)</th>
                <th>Accepts</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {(category === 'laboratories' ? laboratories : ops.locations).map((l) => (
                <tr key={l.locationId}>
                  <td>{l.name}</td>
                  <td>
                    {Object.entries(l.functions)
                      .filter(([, v]) => v)
                      .map(([k]) => humanize(k))
                      .join(', ')}
                  </td>
                  <td>
                    <Badge tone={l.active ? 'ok' : 'bad'}>{l.active ? 'active' : 'inactive'}</Badge>
                  </td>
                  <td>{l.capacity ? `${l.capacity.availableUnits}/${l.capacity.capacityUnits} · ${l.capacity.cooledAvailableUnits}/${l.capacity.cooledCapacityUnits}` : '—'}</td>
                  <td>{l.acceptedSampleTypeIds?.length ?? 0} types</td>
                  <td>
                    <button
                      type="button"
                      className="btn btn-small btn-danger"
                      onClick={() => act('Disruption', () => api.post('report-disruption', { resourceType: l.functions.laboratory ? 'laboratory' : 'node', resourceId: l.locationId, occurredAt: nowIso(), idempotencyKey: newIdempotencyKey() }))}
                    >
                      Report disruption
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
        {category === 'connections' && (
          <table className="table">
            <thead>
              <tr>
                <th>From</th>
                <th>To</th>
                <th>Travel</th>
                <th>Cooled</th>
                <th>Active</th>
                <th>Capacity</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {ops.connections.map((c) => (
                <tr key={c.connectionId}>
                  <td>{locName(c.fromLocationId)}</td>
                  <td>{locName(c.toLocationId)}</td>
                  <td>{c.travelMinutes} min</td>
                  <td>{c.cooled ? 'yes' : 'no'}</td>
                  <td>
                    <Badge tone={c.active ? 'ok' : 'bad'}>{c.active ? 'active' : 'inactive'}</Badge>
                  </td>
                  <td>{c.capacity ? `${c.capacity.availableUnits}/${c.capacity.capacityUnits} · ${c.capacity.cooledAvailableUnits}/${c.capacity.cooledCapacityUnits}` : '—'}</td>
                  <td>
                    <button
                      type="button"
                      className="btn btn-small btn-danger"
                      onClick={() => act('Disruption', () => api.post('report-disruption', { resourceType: 'connection', resourceId: c.connectionId, occurredAt: nowIso(), idempotencyKey: newIdempotencyKey() }))}
                    >
                      Report disruption
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
        {category === 'routes' && <GenericList rows={ops.routes} idKeys={['journeyId']} linkPrefix="/journeys/" />}
        {category === 'handoffs' && <GenericList rows={ops.handoffs} idKeys={['handoffId']} />}
        {category === 'delays' && <GenericList rows={ops.delays} idKeys={['sampleId', 'assignmentId']} linkPrefix="/samples/" />}
        {category === 'exceptions' && <GenericList rows={ops.exceptions} idKeys={['exceptionId', 'sampleId']} linkPrefix="/samples/" />}
      </Panel>
      <DisruptionForm onDone={load} />
    </div>
  )
}

function workerName(ops: OperationsState, id: string) {
  return ops.workers.find((w) => w.workerId === id)?.fullName ?? id.slice(0, 8)
}

function GenericList({ rows, idKeys, linkPrefix }: { rows: Record<string, unknown>[]; idKeys: string[]; linkPrefix?: string }) {
  if (rows.length === 0) return <p className="muted">None.</p>
  const columns = Array.from(new Set(rows.flatMap((r) => Object.keys(r)))).slice(0, 10)
  return (
    <table className="table">
      <thead>
        <tr>
          {columns.map((c) => (
            <th key={c}>{humanize(c)}</th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((r, i) => (
          <tr key={String(r[idKeys[0]] ?? i)}>
            {columns.map((c) => (
              <td key={c}>{renderCell(c, r[c], linkPrefix)}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  )
}

function renderCell(key: string, v: unknown, linkPrefix?: string) {
  if (v == null) return '—'
  if (typeof v === 'string') {
    if (key === 'sampleId' && linkPrefix === '/samples/') return <Link to={`/samples/${v}`}>{v.slice(0, 8)}</Link>
    if (key === 'journeyId') return <Link to={`/journeys/${v}`}>{v.slice(0, 8)}</Link>
    if (/\d{4}-\d{2}-\d{2}T/.test(v)) return fmtTime(v)
    return v.length > 36 ? v.slice(0, 8) : humanize(v)
  }
  if (typeof v === 'boolean') return v ? 'yes' : 'no'
  if (typeof v === 'number') return String(v)
  if (Array.isArray(v)) return v.length ? v.map((x) => (typeof x === 'string' ? x.slice(0, 8) : JSON.stringify(x))).join(', ') : '—'
  return JSON.stringify(v)
}

function DisruptionForm({ onDone }: { onDone: () => void }) {
  const [resourceType, setResourceType] = useState('worker')
  const [resourceId, setResourceId] = useState('')
  const [reason, setReason] = useState('')
  const [result, setResult] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const submit = async (e: FormEvent) => {
    e.preventDefault()
    setError(null)
    setResult(null)
    try {
