                  <td>{l.capacity ? `${l.capacity.availableUnits}/${l.capacity.capacityUnits} · ${l.capacity.cooledAvailableUnits}/${l.capacity.cooledCapacityUnits}` : '—'}</td>
                  <td>{l.acceptedSampleTypeIds?.length ?? 0} types</td>
                  <td>
                    <button
                      type="button"
                      className="btn btn-small btn-danger"
                      onClick={() => act('Disruption', () => api.post('report-disruption', { resourceType: l.functions.laboratory ? 'laboratory' : 'node', resourceId: l.locationId, occurredAt: nowIso(), idempotencyKey: newIdempotencyKey() }))}
                    >
                      Report disruption
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
        {category === 'connections' && (
          <table className="table">
            <thead>
              <tr>
                <th>From</th>
                <th>To</th>
                <th>Travel</th>
                <th>Cooled</th>
                <th>Active</th>
                <th>Capacity</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {ops.connections.map((c) => (
                <tr key={c.connectionId}>
                  <td>{locName(c.fromLocationId)}</td>
                  <td>{locName(c.toLocationId)}</td>
                  <td>{c.travelMinutes} min</td>
                  <td>{c.cooled ? 'yes' : 'no'}</td>
                  <td>
                    <Badge tone={c.active ? 'ok' : 'bad'}>{c.active ? 'active' : 'inactive'}</Badge>
                  </td>
                  <td>{c.capacity ? `${c.capacity.availableUnits}/${c.capacity.capacityUnits} · ${c.capacity.cooledAvailableUnits}/${c.capacity.cooledCapacityUnits}` : '—'}</td>
                  <td>
                    <button
                      type="button"
                      className="btn btn-small btn-danger"
                      onClick={() => act('Disruption', () => api.post('report-disruption', { resourceType: 'connection', resourceId: c.connectionId, occurredAt: nowIso(), idempotencyKey: newIdempotencyKey() }))}
                    >
                      Report disruption
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
        {category === 'routes' && <GenericList rows={ops.routes} idKeys={['journeyId']} linkPrefix="/journeys/" />}
        {category === 'handoffs' && <GenericList rows={ops.handoffs} idKeys={['handoffId']} />}
        {category === 'delays' && <GenericList rows={ops.delays} idKeys={['sampleId', 'assignmentId']} linkPrefix="/samples/" />}
        {category === 'exceptions' && <GenericList rows={ops.exceptions} idKeys={['exceptionId', 'sampleId']} linkPrefix="/samples/" />}
      </Panel>
      <DisruptionForm onDone={load} />
    </div>
  )
}

function workerName(ops: OperationsState, id: string) {
  return ops.workers.find((w) => w.workerId === id)?.fullName ?? id.slice(0, 8)
}

function GenericList({ rows, idKeys, linkPrefix }: { rows: Record<string, unknown>[]; idKeys: string[]; linkPrefix?: string }) {
  if (rows.length === 0) return <p className="muted">None.</p>
  const columns = Array.from(new Set(rows.flatMap((r) => Object.keys(r)))).slice(0, 10)
  return (
    <table className="table">
      <thead>
        <tr>
          {columns.map((c) => (
            <th key={c}>{humanize(c)}</th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((r, i) => (
          <tr key={String(r[idKeys[0]] ?? i)}>
            {columns.map((c) => (
              <td key={c}>{renderCell(c, r[c], linkPrefix)}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  )
}

function renderCell(key: string, v: unknown, linkPrefix?: string) {
  if (v == null) return '—'
  if (typeof v === 'string') {
    if (key === 'sampleId' && linkPrefix === '/samples/') return <Link to={`/samples/${v}`}>{v.slice(0, 8)}</Link>
    if (key === 'journeyId') return <Link to={`/journeys/${v}`}>{v.slice(0, 8)}</Link>
    if (/\d{4}-\d{2}-\d{2}T/.test(v)) return fmtTime(v)
    return v.length > 36 ? v.slice(0, 8) : humanize(v)
  }
  if (typeof v === 'boolean') return v ? 'yes' : 'no'
  if (typeof v === 'number') return String(v)
  if (Array.isArray(v)) return v.length ? v.map((x) => (typeof x === 'string' ? x.slice(0, 8) : JSON.stringify(x))).join(', ') : '—'
  return JSON.stringify(v)
}

function DisruptionForm({ onDone }: { onDone: () => void }) {
  const [resourceType, setResourceType] = useState('worker')
  const [resourceId, setResourceId] = useState('')
  const [reason, setReason] = useState('')
  const [result, setResult] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const submit = async (e: FormEvent) => {
    e.preventDefault()
    setError(null)
    setResult(null)
    try {
      const r = await api.post<{ affectedSampleIds: string[]; replacementPlanIds: string[]; replanStatus: string }>('report-disruption', {
        resourceType,
        resourceId,
        reason: reason || undefined,
        occurredAt: nowIso(),
        idempotencyKey: newIdempotencyKey(),
      })
      setResult(`Replan status: ${humanize(r.replanStatus)} · ${r.affectedSampleIds.length} samples affected · ${r.replacementPlanIds.length} replacement plans`)
      onDone()
    } catch (err) {
      setError(describeError(err))
    }
  }
  return (
    <Panel title="Report disruption">
      <form onSubmit={submit} className="form" aria-label="Report disruption">
        {error && <Alert kind="error">{error}</Alert>}
        {result && <Alert kind="success">{result}</Alert>}
        <div className="row">
          <Field label="Resource type">
            <select value={resourceType} onChange={(e) => setResourceType(e.target.value)}>
              {['location', 'node', 'laboratory', 'connection', 'route', 'worker', 'capacity'].map((t) => (
                <option key={t} value={t}>
                  {humanize(t)}
                </option>
              ))}
            </select>
          </Field>
          <Field label="Resource ID">
            <input value={resourceId} onChange={(e) => setResourceId(e.target.value)} required />
          </Field>
          <Field label="Reason">
            <input value={reason} onChange={(e) => setReason(e.target.value)} />
          </Field>
        </div>
        <button type="submit" className="btn btn-danger">
          Report and replan
        </button>
      </form>
    </Panel>
  )
}

