import { useCallback, useEffect, useState, type FormEvent } from 'react'
import { Link, useNavigate, useParams } from 'react-router-dom'
import { api, describeError, newIdempotencyKey } from '../lib/api'
import { useLocationName, useSession } from '../lib/session'
import type { JourneyPlan } from '../lib/types'
import { fmtTime, humanize } from '../lib/format'
import { Alert, Badge, Field, KeyValue, Panel, StatusBadge } from '../components/ui'

const CHANGE_TYPES = ['add_stop', 'remove_stop', 'reorder_stops', 'replace_worker', 'reassign_worker', 'merge_samples', 'split_samples', 'split_batch', 'cancel_work', 'reroute', 'replace_route']

export default function JourneyPage() {
  const { journeyId = '' } = useParams()
  const { user, tick } = useSession()
  const locName = useLocationName()
  const navigate = useNavigate()
  const [plan, setPlan] = useState<JourneyPlan | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [notice, setNotice] = useState<{ kind: 'error' | 'success'; text: string } | null>(null)
  const isOps = user?.activeRole === 'dispatcher' || user?.activeRole === 'administrator'

  const load = useCallback(async () => {
    try {
      setPlan(await api.post<JourneyPlan>('read-journey-plan', { journeyId }))
      setError(null)
    } catch (err) {
      setError(describeError(err))
    }
  }, [journeyId])

  useEffect(() => {
    void load()
  }, [load, tick])

  const act = async (label: string, fn: () => Promise<unknown>) => {
    setNotice(null)
    try {
      const r = await fn()
      setNotice({ kind: 'success', text: `${label} applied.` })
      await load()
      return r
    } catch (err) {
      setNotice({ kind: 'error', text: describeError(err) })
      return null
    }
  }

  if (error) return <Alert kind="error">{error}</Alert>
  if (!plan) return <p role="status">Loading journey…</p>
  const scope = (plan as unknown as { scope?: string }).scope

  return (
    <div className="page">
      <h1>
        Journey {journeyId.slice(0, 8)} <StatusBadge status={plan.status} />
      </h1>
      {notice && <Alert kind={notice.kind}>{notice.text}</Alert>}
      <div className="two-col">
        <Panel title="Plan">
          <KeyValue
            items={[
              ['Plan version', String(plan.planVersion)],
              ['Route mode', humanize(plan.routeMode)],
              ['Estimated delivery', fmtTime(plan.estimatedDeliveryAt)],
              ['Total cost', plan.totalCostUnits != null ? String(plan.totalCostUnits) : '—'],
              ['Valid', plan.valid == null ? '—' : plan.valid ? 'yes' : 'no'],
              ['Replan status', humanize(plan.replanStatus ?? 'not_required')],
              ...(plan.parentJourneyId ? ([['Parent journey', <Link to={`/journeys/${plan.parentJourneyId}`}>{plan.parentJourneyId.slice(0, 8)}</Link>]] as [string, React.ReactNode][]) : []),
              ...(plan.replacementJourney ? ([['Replacement journey', <Link to={`/journeys/${plan.replacementJourney.journeyId}`}>{plan.replacementJourney.journeyId.slice(0, 8)}</Link>]] as [string, React.ReactNode][]) : []),
              ...(scope ? ([['Scope', humanize(scope)]] as [string, React.ReactNode][]) : []),
            ]}
          />
          <h3>Samples</h3>
          <p>
            {(plan.sampleIds ?? []).map((s) => (
              <Link key={s} to={`/samples/${s}`} className="chip">
                {s.slice(0, 8)}
              </Link>
            ))}
          </p>
        </Panel>
        <Panel title="Stops">
          <ol className="stops">
            {plan.orderedStops.map((s) => (
              <li key={s.stopId}>
                <Badge tone={s.completedAt ? 'ok' : 'muted'}>{humanize(s.stopType)}</Badge> {locName(s.locationId)} · ETA {fmtTime(s.estimatedAt)}
                {s.dwellMinutes ? ` · dwell ${s.dwellMinutes} min` : ''}
                {s.completedAt && <span className="muted"> · completed {fmtTime(s.completedAt)}</span>}
              </li>
            ))}
          </ol>
        </Panel>
      </div>
      <Panel title="Legs and assignments">
        <table className="table">
          <thead>
            <tr>
              <th>#</th>
              <th>Assignment</th>
              <th>From</th>
              <th>To</th>
              <th>Worker</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {plan.legs.map((l) => (
              <tr key={l.assignmentId}>
                <td>{l.sequence}</td>
                <td>{l.assignmentId.slice(0, 8)}</td>
                <td>{l.fromLocationId ? locName(l.fromLocationId) : 'Origin'}</td>
                <td>{locName(l.toLocationId)}</td>
                <td>{l.workerId ? (l.workerId === user?.userId ? 'You' : l.workerId.slice(0, 8)) : <Badge tone="warn">unassigned</Badge>}</td>
                <td>
                  <StatusBadge status={l.status} />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </Panel>
      {isOps && !['completed', 'cancelled', 'replaced', 'expired'].includes(plan.status) && (
        <Panel title="Change plan">
          <p className="muted">All changes are checked against plan version {plan.planVersion}; outdated updates are rejected.</p>
          <div className="actions">
            <button
              type="button"
              className="btn"
              onClick={() =>
                act('Reroute', () => api.post('reroute-journey', { journeyId, expectedPlanVersion: plan.planVersion, idempotencyKey: newIdempotencyKey() }))
              }
            >
              Reroute unfinished work
            </button>
            <button
              type="button"
              className="btn btn-danger"
              onClick={async () => {
                const r = await act('Cancellation', () => api.post('cancel-journey', { journeyId, expectedPlanVersion: plan.planVersion, idempotencyKey: newIdempotencyKey() }))
                if (r) navigate('/monitor')
              }}
            >
              Cancel journey
            </button>
          </div>
          <SplitForm plan={plan} act={act} />
          <MergeForm plan={plan} act={act} />
          <EditForm plan={plan} act={act} />
        </Panel>
      )}
    </div>
  )
}

type Act = (label: string, fn: () => Promise<unknown>) => Promise<unknown>

function SplitForm({ plan, act }: { plan: JourneyPlan; act: Act }) {
  const [selected, setSelected] = useState<string[]>([])
  if ((plan.sampleIds ?? []).length < 2) return null
  return (
    <form
      className="subpanel"
      aria-label="Split journey"
      onSubmit={(e: FormEvent) => {
        e.preventDefault()
        void act('Split', () => api.post('split-journey', { journeyId: plan.journeyId, expectedPlanVersion: plan.planVersion, sampleIds: selected, idempotencyKey: newIdempotencyKey() }))
      }}
    >
      <h4>Split samples into a new journey</h4>
      {plan.sampleIds.map((s) => (
        <label key={s} className="check">
          <input type="checkbox" checked={selected.includes(s)} onChange={(e) => setSelected(e.target.checked ? [...selected, s] : selected.filter((x) => x !== s))} /> {s.slice(0, 8)}
        </label>
      ))}
      <button type="submit" className="btn" disabled={selected.length === 0}>
        Split
      </button>
    </form>
  )
}

function MergeForm({ plan, act }: { plan: JourneyPlan; act: Act }) {
  const [source, setSource] = useState('')
  return (
    <form
      className="subpanel"
      aria-label="Merge journeys"
      onSubmit={(e: FormEvent) => {
        e.preventDefault()
        void act('Merge', () =>
          api.post('merge-journeys', { targetJourneyId: plan.journeyId, expectedPlanVersion: plan.planVersion, sourceJourneyIds: source.split(/[\s,]+/).filter(Boolean), idempotencyKey: newIdempotencyKey() }),
        )
      }}
    >
      <h4>Merge another journey into this one</h4>
      <Field label="Source journey IDs (comma separated)">
        <input value={source} onChange={(e) => setSource(e.target.value)} required />
      </Field>
      <button type="submit" className="btn">
        Merge
      </button>
    </form>
  )
}

function EditForm({ plan, act }: { plan: JourneyPlan; act: Act }) {
  const [changeType, setChangeType] = useState('replace_worker')
  const [changes, setChanges] = useState('{\n  "assignmentId": "",\n  "workerId": ""\n}')
  const [parseError, setParseError] = useState<string | null>(null)
  return (
    <form
      className="subpanel"
      aria-label="Edit active plan"
      onSubmit={(e: FormEvent) => {
        e.preventDefault()
        setParseError(null)
        let parsed: unknown
        try {
          parsed = JSON.parse(changes)
        } catch {
          setParseError('Changes must be valid JSON.')
          return
        }
        void act('Plan edit', () => api.post('edit-active-plan', { journeyId: plan.journeyId, expectedPlanVersion: plan.planVersion, changeType, changes: parsed, idempotencyKey: newIdempotencyKey() }))
      }}
    >
      <h4>Edit active plan</h4>
      {parseError && <Alert kind="error">{parseError}</Alert>}
      <Field label="Change type">
        <select value={changeType} onChange={(e) => setChangeType(e.target.value)}>
          {CHANGE_TYPES.map((c) => (
            <option key={c} value={c}>
              {humanize(c)}
            </option>
          ))}
        </select>
      </Field>
      <Field label="Changes (JSON)" hint="e.g. replace_worker: {assignmentId, workerId}; add_stop: {locationId, stopType, sequence, dwellMinutes}; remove_stop: {stopId}; reorder_stops: {stopIds: [...]}">
        <textarea rows={5} value={changes} onChange={(e) => setChanges(e.target.value)} />
      </Field>
      <button type="submit" className="btn">
        Apply change
      </button>
    </form>
  )
}

