import { useCallback, useEffect, useState, type FormEvent } from 'react'
import { api, describeError } from '../lib/api'
import type { AuditSearchResult } from '../lib/types'
import { fmtTime, humanize } from '../lib/format'
import { Alert, Badge, Field, Panel } from '../components/ui'

export default function AuditPage() {
  const [query, setQuery] = useState('')
  const [entityId, setEntityId] = useState('')
  const [action, setAction] = useState('')
  const [role, setRole] = useState('')
  const [order, setOrder] = useState<'newest_first' | 'oldest_first'>('newest_first')
  const [offset, setOffset] = useState(0)
  const [result, setResult] = useState<AuditSearchResult | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [expanded, setExpanded] = useState<string | null>(null)
  const limit = 50

  const search = useCallback(
    async (off: number) => {
      setError(null)
      try {
        const body: Record<string, unknown> = { limit, offset: off, order }
        if (query) body.query = query
        if (entityId) body.entityId = entityId
        if (action) body.action = action
        if (role) body.role = role
        setResult(await api.post<AuditSearchResult>('search-audit-trail', body))
        setOffset(off)
      } catch (err) {
        setError(describeError(err))
      }
    },
    [query, entityId, action, role, order],
  )

  useEffect(() => {
    void search(0)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const submit = (e: FormEvent) => {
    e.preventDefault()
    void search(0)
  }

  return (
    <div className="page">
      <h1>Audit history</h1>
      <Panel title="Search">
        <form className="form" onSubmit={submit} aria-label="Audit search">
          <div className="row">
            <Field label="Search text">
              <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="request, sample, action, user…" />
            </Field>
            <Field label="Entity ID">
              <input value={entityId} onChange={(e) => setEntityId(e.target.value)} />
            </Field>
            <Field label="Action">
              <input value={action} onChange={(e) => setAction(e.target.value)} />
            </Field>
            <Field label="Role">
              <input value={role} onChange={(e) => setRole(e.target.value)} />
            </Field>
            <Field label="Order">
              <select value={order} onChange={(e) => setOrder(e.target.value as 'newest_first' | 'oldest_first')}>
                <option value="newest_first">Newest first</option>
                <option value="oldest_first">Oldest first</option>
              </select>
            </Field>
          </div>
          <button type="submit" className="btn">
            Search
          </button>
        </form>
      </Panel>
      {error && <Alert kind="error">{error}</Alert>}
      {result && (
        <Panel
          title={`Results (${result.total})`}
          actions={
            <div className="actions">
              <button type="button" className="btn btn-small" disabled={offset === 0} onClick={() => search(Math.max(0, offset - limit))}>
                Previous
              </button>
              <button type="button" className="btn btn-small" disabled={!result.hasMore} onClick={() => search(result.nextOffset ?? offset + limit)}>
                Next
              </button>
            </div>
          }
        >
          {result.entries.length === 0 ? (
            <p className="muted">No audit records match.</p>
          ) : (
            <table className="table audit">
              <thead>
                <tr>
                  <th>Time</th>
                  <th>Action</th>
                  <th>User</th>
                  <th>Role</th>
                  <th>Entity</th>
                  <th>Outcome</th>
                  <th>Changes</th>
                </tr>
              </thead>
              <tbody>
                {result.entries.map((e) => (
                  <tr key={e.auditId}>
                    <td>{fmtTime(e.occurredAt)}</td>
                    <td>{humanize(e.action)}</td>
                    <td>{e.actorId ? e.actorId.slice(0, 8) : 'anonymous'}</td>
                    <td>{humanize(e.role)}</td>
                    <td>
                      {humanize(e.entityType)} {e.entityId ? e.entityId.slice(0, 8) : ''}
                    </td>
                    <td>
                      <Badge tone={e.success ? 'ok' : 'bad'}>{e.success ? 'success' : 'failure'}</Badge>
                    </td>
                    <td>
                      <button type="button" className="link-btn" onClick={() => setExpanded(expanded === e.auditId ? null : e.auditId)}>
                        {expanded === e.auditId ? 'Hide' : 'Show'} details
                      </button>
                      {expanded === e.auditId && <pre className="details">{JSON.stringify(e.details, null, 2)}</pre>}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </Panel>
      )}
    </div>
  )
}

