import { useCallback, useEffect, useMemo, useState } from 'react'
import { api } from '../lib/api'
import { useSession } from '../lib/session'
import type { OperationsState, ServiceabilitySnapshot } from '../lib/types'
import { fmtTime, humanize } from '../lib/format'
import { Badge, Panel } from '../components/ui'
import LiveMap, { type MapMarker } from '../components/LiveMap'

export default function MapPage() {
  const { catalogue, user, tick } = useSession()
  const [ops, setOps] = useState<OperationsState | null>(null)
  const [snapshot, setSnapshot] = useState<ServiceabilitySnapshot | null>(null)
  const isOps = user?.activeRole === 'dispatcher' || user?.activeRole === 'administrator'

  const load = useCallback(async () => {
    try {
      setSnapshot(await api.post<ServiceabilitySnapshot>('read-serviceability-snapshot', {}))
    } catch {
      setSnapshot(null)
    }
    if (isOps) {
      try {
        setOps(await api.post<OperationsState>('read-operations-state', {}))
      } catch {
        setOps(null)
      }
    }
  }, [isOps])

  useEffect(() => {
    void load()
  }, [load, tick])

  const markers = useMemo<MapMarker[]>(() => {
    if (!ops) return []
    const m: MapMarker[] = []
    for (const s of ops.samples) if (s.latestLocation) m.push({ id: `s-${s.sampleId}`, coordinate: s.latestLocation, label: `Sample ${s.sampleId.slice(0, 8)}`, kind: 'sample', stale: s.locationStale })
    for (const w of ops.workers) if (w.latestLocation) m.push({ id: `w-${w.workerId}`, coordinate: w.latestLocation, label: w.fullName ?? 'Worker', kind: 'worker', stale: w.locationStale })
    return m
  }, [ops])

  return (
    <div className="page">
      <h1>Network map</h1>
      <LiveMap locations={ops?.locations ?? catalogue.locations} connections={ops?.connections ?? []} markers={markers} height={520} />
      {snapshot && (
        <Panel title="Serviceability coverage">
          <p>
            <Badge tone="ok">Version {snapshot.version} · {humanize(snapshot.status)}</Badge> computed {fmtTime(snapshot.computedAt)} · network revision {snapshot.networkRevision} ·{' '}
            {snapshot.activeCollectionPointCount} active collection points
          </p>
          <ul className="plain">
            {snapshot.regions.map((r) => (
              <li key={r.locationId}>
                {r.name} — {r.coverageKm} km radius
              </li>
            ))}
          </ul>
        </Panel>
      )}
    </div>
  )
}

