function SampleTypesTab() {
  const { catalogue } = useSession()
  const [notice, run] = useRunner()
  const [editing, setEditing] = useState<SampleType | null>(null)
  const [name, setName] = useState('')
  const [container, setContainer] = useState('')
  const [tMin, setTMin] = useState('')
  const [tMax, setTMax] = useState('')
  const [qualification, setQualification] = useState('')
  const [cooledRoute, setCooledRoute] = useState(false)
  const [batching, setBatching] = useState(true)
  const [incompatible, setIncompatible] = useState<string[]>([])

  const reset = () => {
    setEditing(null)
    setName('')
    setContainer('')
    setTMin('')
    setTMax('')
    setQualification('')
    setCooledRoute(false)
    setBatching(true)
    setIncompatible([])
  }
  const edit = (t: SampleType) => {
    setEditing(t)
    setName(t.name)
    setContainer(t.containerType)
    setTMin(String(t.temperatureMinC))
    setTMax(String(t.temperatureMaxC))
    setQualification(t.requiredQualification)
    setCooledRoute(t.requiresCooledRoute)
    setBatching(t.batchingAllowed)
    setIncompatible(t.incompatibleSampleTypes)
  }
  const submit = async (e: FormEvent) => {
    e.preventDefault()
    const body = {
      qualifiedCollectorRequired: !!qualification,
      requiredQualification: qualification || undefined,
      containerType: container,
      temperatureMinC: Number(tMin),
      temperatureMaxC: Number(tMax),
      incompatibleSampleTypes: incompatible,
      requiresCooledRoute: cooledRoute,
      batchingAllowed: batching,
    }
    const ok = await run('Sample type', () => (editing ? api.post('update-sample-type', { sampleTypeId: editing.sampleTypeId, ...body }) : api.post('create-sample-type', { name, ...body })))
    if (ok) reset()
  }

  return (
    <div className="two-col">
      <Panel title={editing ? `Edit ${editing.name}` : 'Create sample type'}>
        {notice && <Alert kind={notice.kind}>{notice.text}</Alert>}
        <form className="form" onSubmit={submit} aria-label="Sample type form">
          {!editing && (
            <Field label="Name">
              <input value={name} onChange={(e) => setName(e.target.value)} required />
            </Field>
          )}
          <Field label="Container type">
            <input value={container} onChange={(e) => setContainer(e.target.value)} required />
          </Field>
          <div className="row">
            <Field label="Min temperature (°C)">
              <input type="number" step="0.1" value={tMin} onChange={(e) => setTMin(e.target.value)} required />
            </Field>
            <Field label="Max temperature (°C)">
              <input type="number" step="0.1" value={tMax} onChange={(e) => setTMax(e.target.value)} required />
            </Field>
          </div>
          <Field label="Required collector qualification" hint="Leave blank if no qualification is required">
            <input value={qualification} onChange={(e) => setQualification(e.target.value)} />
          </Field>
          <label className="check">
            <input type="checkbox" checked={cooledRoute} onChange={(e) => setCooledRoute(e.target.checked)} /> Requires cooled route
          </label>
          <label className="check">
            <input type="checkbox" checked={batching} onChange={(e) => setBatching(e.target.checked)} /> Batching allowed
          </label>
          <fieldset className="checks">
            <legend>Incompatible with</legend>
            {catalogue.sampleTypes
              .filter((t) => t.sampleTypeId !== editing?.sampleTypeId)
              .map((t) => (
                <label key={t.sampleTypeId} className="check">
                  <input
                    type="checkbox"
                    checked={incompatible.includes(t.sampleTypeId)}
                    onChange={(e) => setIncompatible(e.target.checked ? [...incompatible, t.sampleTypeId] : incompatible.filter((x) => x !== t.sampleTypeId))}
                  />{' '}
                  {t.name}
                </label>
              ))}
          </fieldset>
          <div className="actions">
            <button type="submit" className="btn">
              {editing ? 'Save changes' : 'Create sample type'}
            </button>
            {editing && (
              <button type="button" className="btn btn-secondary" onClick={reset}>
                Cancel
              </button>
            )}
          </div>
        </form>
      </Panel>
      <Panel title="Sample types">
        <table className="table">
          <thead>
            <tr>
              <th>Name</th>
              <th>Container</th>
              <th>Temperature</th>
              <th>Rules</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {catalogue.sampleTypes.map((t) => (
              <tr key={t.sampleTypeId}>
                <td>{t.name}</td>
                <td>{t.containerType}</td>
                <td>
                  {t.temperatureMinC} – {t.temperatureMaxC} °C
                </td>
                <td>
                  {[
                    t.qualifiedCollectorRequired && `qualified collector (${t.requiredQualification})`,
                    t.requiresCooledRoute && 'cooled route',
                    !t.batchingAllowed && 'no batching',
                    t.incompatibleSampleTypes.length && `${t.incompatibleSampleTypes.length} incompatibilities`,
                  ]
                    .filter(Boolean)
                    .join(', ') || 'standard'}
                </td>
                <td>
                  <button type="button" className="btn btn-small" onClick={() => edit(t)}>
                    Edit
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </Panel>
    </div>
  )
}
