import { useCallback, useEffect, useState, type FormEvent } from 'react'
import { api, describeError } from '../lib/api'
import { useLocationName, useSession } from '../lib/session'
import { ROLE_LABELS, type Location, type OperationsState, type Role, type SampleType } from '../lib/types'
import { humanize } from '../lib/format'
import { Alert, Badge, Field, Panel } from '../components/ui'

const ALL_ROLES: Role[] = ['administrator', 'dispatcher', 'requester', 'collection_professional', 'delivery_partner', 'node_handler', 'laboratory_team']
const FUNCTIONS = ['collection_point', 'transfer_point', 'hub', 'laboratory'] as const
type Tab = 'users' | 'locations' | 'connections' | 'sampleTypes'

type Notice = { kind: 'error' | 'success'; text: string } | null

export default function AdminPage() {
  const [tab, setTab] = useState<Tab>('users')
  const { tick } = useSession()
  const [ops, setOps] = useState<OperationsState | null>(null)
  const load = useCallback(async () => {
    try {
      setOps(await api.post<OperationsState>('read-operations-state', {}))
    } catch {
      setOps(null)
    }
  }, [])
  useEffect(() => {
    void load()
  }, [load, tick])

  return (
    <div className="page">
      <h1>Administration</h1>
      <div className="tabs" role="tablist" aria-label="Administration sections">
        {(['users', 'locations', 'connections', 'sampleTypes'] as Tab[]).map((t) => (
          <button key={t} type="button" role="tab" aria-selected={tab === t} className={`tab${tab === t ? ' tab-active' : ''}`} onClick={() => setTab(t)}>
            {humanize(t === 'sampleTypes' ? 'sample_types' : t)}
          </button>
        ))}
      </div>
      {tab === 'users' && <UsersTab ops={ops} onChanged={load} />}
      {tab === 'locations' && <LocationsTab ops={ops} onChanged={load} />}
      {tab === 'connections' && <ConnectionsTab ops={ops} onChanged={load} />}
      {tab === 'sampleTypes' && <SampleTypesTab />}
    </div>
  )
}

function useRunner(): [Notice, (label: string, fn: () => Promise<unknown>) => Promise<boolean>] {
  const [notice, setNotice] = useState<Notice>(null)
  const run = async (label: string, fn: () => Promise<unknown>) => {
    setNotice(null)
    try {
      await fn()
      setNotice({ kind: 'success', text: `${label} saved.` })
      return true
    } catch (err) {
      setNotice({ kind: 'error', text: describeError(err) })
      return false
    }
  }
  return [notice, run]
}

function UsersTab({ ops, onChanged }: { ops: OperationsState | null; onChanged: () => void }) {
  const { catalogue } = useSession()
  const [notice, run] = useRunner()
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [fullName, setFullName] = useState('')
  const [roles, setRoles] = useState<Role[]>(['requester'])
  const [qualifications, setQualifications] = useState('')
  const [assignedLocationId, setAssignedLocationId] = useState('')
  const [editing, setEditing] = useState<string | null>(null)
  const [editRoles, setEditRoles] = useState<Role[]>([])
  const [editQuals, setEditQuals] = useState('')
  const [editLocation, setEditLocation] = useState('')
  const [editActive, setEditActive] = useState(true)

  const toggle = (list: Role[], r: Role) => (list.includes(r) ? list.filter((x) => x !== r) : [...list, r])
  const quals = (s: string) => s.split(/[\s,]+/).filter(Boolean)
  const certs = (q: string[]) => q.map((code) => ({ code, active: true }))

  const create = async (e: FormEvent) => {
    e.preventDefault()
    const q = quals(qualifications)
    const ok = await run('User', () =>
      api.post('create-user', {
        username,
        initialPassword: password,
        fullName: fullName || undefined,
        roles,
        qualifications: q,
        certifications: certs(q),
        active: true,
        assignedLocationId: assignedLocationId || undefined,
      }),
    )
    if (ok) {
      setUsername('')
      setPassword('')
      setFullName('')
      onChanged()
    }
  }

  const startEdit = async (userId: string) => {
    try {
      const u = await api.get<{ roles: string[]; qualifications: string[]; active: boolean }>(`read-user/${userId}`)
      setEditing(userId)
      setEditRoles(u.roles as Role[])
      setEditQuals(u.qualifications.join(', '))
      setEditActive(u.active)
      setEditLocation('')
    } catch {
      /* surfaced on save */
    }
  }

  const saveEdit = async (e: FormEvent) => {
    e.preventDefault()
    if (!editing) return
    const q = quals(editQuals)
    const ok = await run('User access', () =>
      api.post('update-user-access', { userId: editing, roles: editRoles, qualifications: q, certifications: certs(q), active: editActive, assignedLocationId: editLocation || undefined }),
    )
    if (ok) {
      setEditing(null)
      onChanged()
    }
  }

  return (
    <div className="two-col">
      <Panel title="Create user">
        {notice && <Alert kind={notice.kind}>{notice.text}</Alert>}
        <form className="form" onSubmit={create} aria-label="Create user">
          <Field label="Username">
            <input value={username} onChange={(e) => setUsername(e.target.value)} required />
          </Field>
          <Field label="Initial password">
            <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required />
          </Field>
          <Field label="Full name">
            <input value={fullName} onChange={(e) => setFullName(e.target.value)} />
          </Field>
          <fieldset className="checks">
            <legend>Roles</legend>
            {ALL_ROLES.map((r) => (
              <label key={r} className="check">
                <input type="checkbox" checked={roles.includes(r)} onChange={() => setRoles(toggle(roles, r))} /> {ROLE_LABELS[r]}
              </label>
            ))}
          </fieldset>
          <Field label="Qualifications / certifications" hint="Comma separated, e.g. Amber, Frost">
            <input value={qualifications} onChange={(e) => setQualifications(e.target.value)} />
          </Field>
          <Field label="Assigned node or laboratory">
            <select value={assignedLocationId} onChange={(e) => setAssignedLocationId(e.target.value)}>
              <option value="">None</option>
              {catalogue.locations.map((l) => (
                <option key={l.locationId} value={l.locationId}>
                  {l.name}
                </option>
              ))}
            </select>
          </Field>
          <button type="submit" className="btn">
            Create user
          </button>
        </form>
      </Panel>
      <Panel title="Workers">
        {!ops ? (
          <p className="muted">Loading…</p>
        ) : (
          <table className="table">
            <thead>
              <tr>
                <th>Name</th>
                <th>Roles</th>
                <th>Status</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {ops.workers.map((w) => (
                <tr key={w.workerId}>
                  <td>{w.fullName ?? w.workerId.slice(0, 8)}</td>
                  <td>{w.roles?.map((r) => ROLE_LABELS[r as Role] ?? r).join(', ')}</td>
                  <td>
                    <Badge tone={w.available ? 'ok' : 'warn'}>{humanize(w.status)}</Badge>
                  </td>
                  <td>
                    <button type="button" className="btn btn-small" onClick={() => startEdit(w.workerId)}>
                      Edit access
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
        {editing && (
          <form className="subpanel form" onSubmit={saveEdit} aria-label="Edit user access">
            <h4>Edit access for {editing.slice(0, 8)}</h4>
            <fieldset className="checks">
              <legend>Roles</legend>
              {ALL_ROLES.map((r) => (
                <label key={r} className="check">
                  <input type="checkbox" checked={editRoles.includes(r)} onChange={() => setEditRoles(toggle(editRoles, r))} /> {ROLE_LABELS[r]}
                </label>
              ))}
            </fieldset>
            <Field label="Qualifications / certifications">
              <input value={editQuals} onChange={(e) => setEditQuals(e.target.value)} />
            </Field>
            <Field label="Assigned node or laboratory">
              <select value={editLocation} onChange={(e) => setEditLocation(e.target.value)}>
                <option value="">Keep / none</option>
                {catalogue.locations.map((l) => (
                  <option key={l.locationId} value={l.locationId}>
                    {l.name}
                  </option>
                ))}
              </select>
            </Field>
            <label className="check">
              <input type="checkbox" checked={editActive} onChange={(e) => setEditActive(e.target.checked)} /> Active
            </label>
            <div className="actions">
              <button type="submit" className="btn">
                Save access
              </button>
              <button type="button" className="btn btn-secondary" onClick={() => setEditing(null)}>
                Cancel
              </button>
            </div>
          </form>
        )}
      </Panel>
    </div>
  )
}

function LocationsTab({ ops, onChanged }: { ops: OperationsState | null; onChanged: () => void }) {
  const { catalogue } = useSession()
  const [notice, run] = useRunner()
  const [name, setName] = useState('')
  const [lat, setLat] = useState('12.97')
  const [lng, setLng] = useState('77.59')
  const [coverage, setCoverage] = useState('5')
  const [handling, setHandling] = useState('10')
  const [fns, setFns] = useState<string[]>(['collection_point'])
  const [capTarget, setCapTarget] = useState<Location | null>(null)
  const [capRegular, setCapRegular] = useState('0')
  const [capCooled, setCapCooled] = useState('0')
  const [accLab, setAccLab] = useState('')
  const [accType, setAccType] = useState('')

  const create = async (e: FormEvent) => {
    e.preventDefault()
    const ok = await run('Location', () =>
      api.post('create-location', {
        name,
        coordinate: { latitude: Number(lat), longitude: Number(lng) },
        coverageKm: Number(coverage),
        handlingMinutes: Number(handling),
        active: true,
        functions: fns,
      }),
    )
    if (ok) {
      setName('')
      onChanged()
    }
  }

  const locations = ops?.locations ?? catalogue.locations
  return (
    <>
      {notice && <Alert kind={notice.kind}>{notice.text}</Alert>}
      <div className="two-col">
        <Panel title="Create location">
          <form className="form" onSubmit={create} aria-label="Create location">
            <Field label="Name">
              <input value={name} onChange={(e) => setName(e.target.value)} required />
            </Field>
            <div className="row">
              <Field label="Latitude">
                <input type="number" step="any" value={lat} onChange={(e) => setLat(e.target.value)} required />
              </Field>
              <Field label="Longitude">
                <input type="number" step="any" value={lng} onChange={(e) => setLng(e.target.value)} required />
              </Field>
            </div>
            <div className="row">
              <Field label="Coverage (km, max 5)">
                <input type="number" step="0.1" min={0.1} max={5} value={coverage} onChange={(e) => setCoverage(e.target.value)} />
              </Field>
              <Field label="Handling minutes">
                <input type="number" min={0} max={1440} value={handling} onChange={(e) => setHandling(e.target.value)} />
              </Field>
            </div>
            <fieldset className="checks">
              <legend>Functions</legend>
              {FUNCTIONS.map((f) => (
                <label key={f} className="check">
                  <input type="checkbox" checked={fns.includes(f)} onChange={() => setFns(fns.includes(f) ? fns.filter((x) => x !== f) : [...fns, f])} /> {humanize(f)}
                </label>
              ))}
            </fieldset>
            <button type="submit" className="btn">
              Create location
            </button>
          </form>
        </Panel>
        <Panel title="Laboratory acceptance">
          <form
            className="form"
            aria-label="Configure laboratory acceptance"
            onSubmit={async (e) => {
              e.preventDefault()
              await run('Laboratory acceptance', () => api.post('configure-laboratory-acceptance', { laboratoryId: accLab, sampleTypeId: accType, accepts: true }))
              onChanged()
            }}
          >
            <Field label="Laboratory">
              <select value={accLab} onChange={(e) => setAccLab(e.target.value)} required>
                <option value="">Select…</option>
                {locations
                  .filter((l) => l.functions.laboratory)
                  .map((l) => (
                    <option key={l.locationId} value={l.locationId}>
                      {l.name}
                    </option>
                  ))}
              </select>
            </Field>
            <Field label="Sample type">
              <select value={accType} onChange={(e) => setAccType(e.target.value)} required>
                <option value="">Select…</option>
                {catalogue.sampleTypes.map((t) => (
                  <option key={t.sampleTypeId} value={t.sampleTypeId}>
                    {t.name}
                  </option>
                ))}
              </select>
            </Field>
            <div className="actions">
              <button type="submit" className="btn">
                Accept type
              </button>
              <button
                type="button"
                className="btn btn-secondary"
                onClick={async () => {
                  await run('Laboratory acceptance', () => api.post('configure-laboratory-acceptance', { laboratoryId: accLab, sampleTypeId: accType, accepts: false }))
                  onChanged()
                }}
              >
                Stop accepting
              </button>
            </div>
          </form>
        </Panel>
      </div>
      <Panel title="Locations">
        <table className="table">
          <thead>
            <tr>
              <th>Name</th>
              <th>Functions</th>
              <th>Active</th>
              <th>Capacity</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {locations.map((l) => (
              <tr key={l.locationId}>
                <td>{l.name}</td>
                <td>
                  {FUNCTIONS.map((f) => (
                    <button
                      key={f}
                      type="button"
                      className={`chip-btn${l.functions[f] ? ' chip-on' : ''}`}
                      title={`Toggle ${humanize(f)}`}
                      onClick={async () => {
                        await run('Function status', () => api.post('set-location-function-status', { locationId: l.locationId, function: f, active: !l.functions[f] }))
                        onChanged()
                      }}
                    >
                      {humanize(f)}
                    </button>
                  ))}
                </td>
                <td>
                  <Badge tone={l.active ? 'ok' : 'bad'}>{l.active ? 'active' : 'inactive'}</Badge>
                </td>
                <td>{l.capacity ? `${l.capacity.capacityUnits} regular · ${l.capacity.cooledCapacityUnits} cooled` : '—'}</td>
                <td>
                  <button
                    type="button"
                    className="btn btn-small"
                    onClick={async () => {
                      await run('Location status', () => api.post('set-location-status', { locationId: l.locationId, active: !l.active }))
                      onChanged()
                    }}
                  >
                    {l.active ? 'Deactivate' : 'Activate'}
                  </button>
                  <button
                    type="button"
                    className="btn btn-small"
                    onClick={() => {
                      setCapTarget(l)
                      setCapRegular(String(l.capacity?.capacityUnits ?? 0))
                      setCapCooled(String(l.capacity?.cooledCapacityUnits ?? 0))
                    }}
                  >
                    Capacity
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {capTarget && (
          <form
            className="subpanel form"
            aria-label="Configure capacity"
            onSubmit={async (e) => {
              e.preventDefault()
              const ok = await run('Capacity', () => api.post('configure-capacity', { resourceId: capTarget.locationId, capacityUnits: Number(capRegular), cooledCapacityUnits: Number(capCooled) }))
              if (ok) {
                setCapTarget(null)
                onChanged()
              }
            }}
          >
            <h4>Capacity for {capTarget.name}</h4>
            <div className="row">
              <Field label="Regular units">
                <input type="number" min={0} value={capRegular} onChange={(e) => setCapRegular(e.target.value)} />
              </Field>
              <Field label="Cooled units">
                <input type="number" min={0} value={capCooled} onChange={(e) => setCapCooled(e.target.value)} />
              </Field>
            </div>
            <div className="actions">
              <button type="submit" className="btn">
                Save
              </button>
              <button type="button" className="btn btn-secondary" onClick={() => setCapTarget(null)}>
                Cancel
              </button>
            </div>
          </form>
        )}
      </Panel>
    </>
  )
}

function ConnectionsTab({ ops, onChanged }: { ops: OperationsState | null; onChanged: () => void }) {
  const { catalogue } = useSession()
  const locName = useLocationName()
  const [notice, run] = useRunner()
  const [from, setFrom] = useState('')
  const [to, setTo] = useState('')
  const [minutes, setMinutes] = useState('30')
  const [cost, setCost] = useState('30')
  const [cooled, setCooled] = useState(false)
  const [capRegular, setCapRegular] = useState('10')
  const [capCooled, setCapCooled] = useState('0')

  const create = async (e: FormEvent) => {
    e.preventDefault()
    const ok = await run('Connection', async () => {
      const c = await api.post<{ connectionId: string }>('create-connection', { fromLocationId: from, toLocationId: to, travelMinutes: Number(minutes), costUnits: Number(cost), cooled, active: true })
      await api.post('configure-capacity', { resourceId: c.connectionId, capacityUnits: Number(capRegular), cooledCapacityUnits: Number(capCooled) })
    })
    if (ok) onChanged()
  }

  return (
    <>
      {notice && <Alert kind={notice.kind}>{notice.text}</Alert>}
      <div className="two-col">
        <Panel title="Create connection">
          <form className="form" onSubmit={create} aria-label="Create connection">
            <div className="row">
              <Field label="From">
                <select value={from} onChange={(e) => setFrom(e.target.value)} required>
                  <option value="">Select…</option>
                  {catalogue.locations.map((l) => (
                    <option key={l.locationId} value={l.locationId}>
                      {l.name}
                    </option>
                  ))}
                </select>
              </Field>
              <Field label="To">
                <select value={to} onChange={(e) => setTo(e.target.value)} required>
                  <option value="">Select…</option>
                  {catalogue.locations.map((l) => (
                    <option key={l.locationId} value={l.locationId}>
                      {l.name}
                    </option>
                  ))}
                </select>
              </Field>
            </div>
            <div className="row">
              <Field label="Travel minutes">
                <input type="number" min={1} value={minutes} onChange={(e) => setMinutes(e.target.value)} required />
              </Field>
              <Field label="Cost units">
                <input type="number" min={0} step="any" value={cost} onChange={(e) => setCost(e.target.value)} required />
              </Field>
            </div>
            <label className="check">
              <input type="checkbox" checked={cooled} onChange={(e) => setCooled(e.target.checked)} /> Cooled transport available
            </label>
            <div className="row">
              <Field label="Regular capacity">
                <input type="number" min={0} value={capRegular} onChange={(e) => setCapRegular(e.target.value)} />
              </Field>
              <Field label="Cooled capacity">
                <input type="number" min={0} value={capCooled} onChange={(e) => setCapCooled(e.target.value)} />
              </Field>
            </div>
            <button type="submit" className="btn">
              Create connection
            </button>
          </form>
        </Panel>
        <Panel title="Connections">
          {!ops ? (
            <p className="muted">Loading…</p>
          ) : (
            <table className="table">
              <thead>
                <tr>
                  <th>From</th>
                  <th>To</th>
                  <th>Travel</th>
                  <th>Cooled</th>
                  <th>Capacity</th>
                  <th>Active</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {ops.connections.map((c) => (
                  <tr key={c.connectionId}>
                    <td>{locName(c.fromLocationId)}</td>
                    <td>{locName(c.toLocationId)}</td>
                    <td>{c.travelMinutes} min</td>
                    <td>{c.cooled ? 'yes' : 'no'}</td>
                    <td>{c.capacity ? `${c.capacity.capacityUnits} · ${c.capacity.cooledCapacityUnits} cooled` : '—'}</td>
                    <td>
                      <Badge tone={c.active ? 'ok' : 'bad'}>{c.active ? 'active' : 'inactive'}</Badge>
                    </td>
                    <td>
                      <button
                        type="button"
                        className="btn btn-small"
                        onClick={async () => {
                          await run('Connection status', () => api.post('set-connection-status', { connectionId: c.connectionId, active: !c.active }))
                          onChanged()
                        }}
                      >
                        {c.active ? 'Deactivate' : 'Activate'}
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </Panel>
      </div>
    </>
  )
}

function SampleTypesTab() {
  const { catalogue } = useSession()
  const [notice, run] = useRunner()
  const [editing, setEditing] = useState<SampleType | null>(null)
  const [name, setName] = useState('')
  const [container, setContainer] = useState('')
  const [tMin, setTMin] = useState('')
  const [tMax, setTMax] = useState('')
  const [qualification, setQualification] = useState('')
  const [cooledRoute, setCooledRoute] = useState(false)
  const [batching, setBatching] = useState(true)
  const [incompatible, setIncompatible] = useState<string[]>([])

  const reset = () => {
    setEditing(null)
    setName('')
    setContainer('')
    setTMin('')
    setTMax('')
    setQualification('')
    setCooledRoute(false)
    setBatching(true)
    setIncompatible([])
  }
  const edit = (t: SampleType) => {
    setEditing(t)
    setName(t.name)
    setContainer(t.containerType)
    setTMin(String(t.temperatureMinC))
    setTMax(String(t.temperatureMaxC))
    setQualification(t.requiredQualification)
    setCooledRoute(t.requiresCooledRoute)
    setBatching(t.batchingAllowed)
    setIncompatible(t.incompatibleSampleTypes)
  }
  const submit = async (e: FormEvent) => {
    e.preventDefault()
    const body = {
      qualifiedCollectorRequired: !!qualification,
      requiredQualification: qualification || undefined,
      containerType: container,
      temperatureMinC: Number(tMin),
      temperatureMaxC: Number(tMax),
      incompatibleSampleTypes: incompatible,
      requiresCooledRoute: cooledRoute,
      batchingAllowed: batching,
    }
    const ok = await run('Sample type', () => (editing ? api.post('update-sample-type', { sampleTypeId: editing.sampleTypeId, ...body }) : api.post('create-sample-type', { name, ...body })))
    if (ok) reset()
  }

  return (
    <div className="two-col">
      <Panel title={editing ? `Edit ${editing.name}` : 'Create sample type'}>
        {notice && <Alert kind={notice.kind}>{notice.text}</Alert>}
        <form className="form" onSubmit={submit} aria-label="Sample type form">
          {!editing && (
            <Field label="Name">
              <input value={name} onChange={(e) => setName(e.target.value)} required />
            </Field>
          )}
          <Field label="Container type">
            <input value={container} onChange={(e) => setContainer(e.target.value)} required />
          </Field>
          <div className="row">
            <Field label="Min temperature (°C)">
              <input type="number" step="0.1" value={tMin} onChange={(e) => setTMin(e.target.value)} required />
            </Field>
            <Field label="Max temperature (°C)">
              <input type="number" step="0.1" value={tMax} onChange={(e) => setTMax(e.target.value)} required />
            </Field>
          </div>
          <Field label="Required collector qualification" hint="Leave blank if no qualification is required">
            <input value={qualification} onChange={(e) => setQualification(e.target.value)} />
          </Field>
          <label className="check">
            <input type="checkbox" checked={cooledRoute} onChange={(e) => setCooledRoute(e.target.checked)} /> Requires cooled route
          </label>
          <label className="check">
            <input type="checkbox" checked={batching} onChange={(e) => setBatching(e.target.checked)} /> Batching allowed
          </label>
          <fieldset className="checks">
            <legend>Incompatible with</legend>
            {catalogue.sampleTypes
              .filter((t) => t.sampleTypeId !== editing?.sampleTypeId)
              .map((t) => (
                <label key={t.sampleTypeId} className="check">
                  <input
                    type="checkbox"
                    checked={incompatible.includes(t.sampleTypeId)}
                    onChange={(e) => setIncompatible(e.target.checked ? [...incompatible, t.sampleTypeId] : incompatible.filter((x) => x !== t.sampleTypeId))}
                  />{' '}
                  {t.name}
                </label>
              ))}
          </fieldset>
          <div className="actions">
            <button type="submit" className="btn">
              {editing ? 'Save changes' : 'Create sample type'}
            </button>
            {editing && (
              <button type="button" className="btn btn-secondary" onClick={reset}>
                Cancel
              </button>
            )}
          </div>
        </form>
      </Panel>
      <Panel title="Sample types">
        <table className="table">
          <thead>
            <tr>
              <th>Name</th>
              <th>Container</th>
              <th>Temperature</th>
              <th>Rules</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {catalogue.sampleTypes.map((t) => (
              <tr key={t.sampleTypeId}>
                <td>{t.name}</td>
                <td>{t.containerType}</td>
                <td>
                  {t.temperatureMinC} – {t.temperatureMaxC} °C
                </td>
                <td>
                  {[
                    t.qualifiedCollectorRequired && `qualified collector (${t.requiredQualification})`,
                    t.requiresCooledRoute && 'cooled route',
                    !t.batchingAllowed && 'no batching',
                    t.incompatibleSampleTypes.length && `${t.incompatibleSampleTypes.length} incompatibilities`,
                  ]
                    .filter(Boolean)
                    .join(', ') || 'standard'}
                </td>
                <td>
                  <button type="button" className="btn btn-small" onClick={() => edit(t)}>
                    Edit
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </Panel>
    </div>
  )
}

