:root {
  --bg: #f4f6f8;
  --panel: #ffffff;
  --border: #d9dee3;
  --text: #1f2933;
  --muted: #5f6b7a;
  --primary: #1d4ed8;
  --primary-dark: #1e40af;
  --danger: #b91c1c;
  --ok: #047857;
  --warn: #b45309;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 15px;
  color: var(--text);
}

* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); }
a { color: var(--primary); }
h1 { font-size: 1.5rem; margin: 0 0 0.75rem; display: flex; gap: 0.5rem; align-items: center; flex-wrap: wrap; }
h2 { font-size: 1.1rem; margin: 0; }
h3 { font-size: 1rem; margin: 0.75rem 0 0.25rem; }
h4 { margin: 0 0 0.5rem; font-size: 0.95rem; }
.muted { color: var(--muted); font-size: 0.9rem; }

.centered { min-height: 100vh; display: grid; place-items: center; padding: 1rem; }
.card { background: var(--panel); border: 1px solid var(--border); border-radius: 8px; padding: 1.25rem; }
.login { width: min(380px, 100%); display: flex; flex-direction: column; gap: 0.75rem; }

.shell { min-height: 100vh; display: flex; flex-direction: column; }
.topbar { display: flex; align-items: center; gap: 1.5rem; padding: 0.6rem 1.25rem; background: #0f172a; color: #fff; flex-wrap: wrap; }
.brand a { color: #fff; font-weight: 700; text-decoration: none; }
.nav { display: flex; gap: 0.25rem; flex-wrap: wrap; flex: 1; }
.nav a { color: #cbd5e1; text-decoration: none; padding: 0.35rem 0.6rem; border-radius: 6px; }
.nav a.active, .nav a:hover { background: #1e293b; color: #fff; }
.session { display: flex; align-items: center; gap: 0.75rem; }
.role-select { display: flex; align-items: center; gap: 0.4rem; font-size: 0.85rem; }
.role-select select { padding: 0.3rem; border-radius: 6px; }
.role-banner { margin: 0 0 0.75rem; color: var(--muted); }
.content { padding: 1.25rem; max-width: 1400px; width: 100%; margin: 0 auto; }
.page { display: flex; flex-direction: column; gap: 1rem; }
.two-col { display: grid; grid-template-columns: repeat(auto-fit, minmax(380px, 1fr)); gap: 1rem; }

.panel { background: var(--panel); border: 1px solid var(--border); border-radius: 8px; }
.panel-header { display: flex; justify-content: space-between; align-items: center; padding: 0.7rem 1rem; border-bottom: 1px solid var(--border); }
.panel-body { padding: 1rem; overflow-x: auto; }
.subpanel { border: 1px dashed var(--border); border-radius: 6px; padding: 0.75rem; margin-top: 0.75rem; background: #fafbfc; }
.action-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 0.75rem; }

.form { display: flex; flex-direction: column; gap: 0.75rem; }
.row { display: flex; gap: 0.75rem; flex-wrap: wrap; }
.row > .field { flex: 1 1 160px; }
.field { display: flex; flex-direction: column; gap: 0.25rem; margin-bottom: 0.5rem; }
.field-label { font-size: 0.85rem; font-weight: 600; }
.field-hint { font-size: 0.78rem; color: var(--muted); }
input, select, textarea { padding: 0.45rem 0.55rem; border: 1px solid var(--border); border-radius: 6px; font: inherit; background: #fff; }
textarea { font-family: ui-monospace, monospace; font-size: 0.85rem; }
.checks { border: 1px solid var(--border); border-radius: 6px; padding: 0.5rem 0.75rem; display: flex; flex-wrap: wrap; gap: 0.5rem 1rem; }
.checks legend { font-size: 0.85rem; font-weight: 600; }
.check { display: inline-flex; align-items: center; gap: 0.35rem; font-size: 0.9rem; }

.btn { background: var(--primary); color: #fff; border: 0; border-radius: 6px; padding: 0.5rem 0.9rem; font: inherit; cursor: pointer; text-decoration: none; display: inline-block; }
.btn:hover { background: var(--primary-dark); }
.btn:disabled { opacity: 0.5; cursor: not-allowed; }
.btn-secondary { background: #e2e8f0; color: var(--text); }
.btn-secondary:hover { background: #cbd5e1; }
.btn-danger { background: var(--danger); }
.btn-danger:hover { background: #991b1b; }
.btn-small { padding: 0.25rem 0.55rem; font-size: 0.82rem; margin-right: 0.3rem; }
.link-btn { background: none; border: 0; color: var(--primary); cursor: pointer; padding: 0.25rem 0; font: inherit; text-decoration: underline; }
.actions { display: flex; gap: 0.5rem; flex-wrap: wrap; margin-top: 0.5rem; }

.alert { padding: 0.65rem 0.9rem; border-radius: 6px; border: 1px solid; margin: 0.5rem 0; }
.alert-error { background: #fef2f2; border-color: #fca5a5; color: #7f1d1d; }
.alert-success { background: #ecfdf5; border-color: #6ee7b7; color: #064e3b; }
.alert-info { background: #eff6ff; border-color: #93c5fd; color: #1e3a8a; }

.badge { display: inline-block; padding: 0.12rem 0.5rem; border-radius: 999px; font-size: 0.78rem; font-weight: 600; white-space: nowrap; }
.badge-ok { background: #d1fae5; color: var(--ok); }
.badge-warn { background: #fef3c7; color: var(--warn); }
.badge-bad { background: #fee2e2; color: var(--danger); }
.badge-muted { background: #e2e8f0; color: #334155; }
.chip { display: inline-block; background: #e2e8f0; border-radius: 4px; padding: 0.1rem 0.4rem; margin-right: 0.3rem; font-size: 0.85rem; text-decoration: none; }
.chip-btn { border: 1px solid var(--border); background: #fff; border-radius: 999px; padding: 0.1rem 0.5rem; font-size: 0.78rem; margin: 0.1rem; cursor: pointer; color: var(--muted); }
.chip-on { background: #dbeafe; border-color: #93c5fd; color: #1e3a8a; }
.stats { display: flex; gap: 0.5rem; flex-wrap: wrap; }

.kv { margin: 0; display: grid; grid-template-columns: max-content 1fr; gap: 0.3rem 1rem; }
.kv-row { display: contents; }
.kv dt { font-weight: 600; color: var(--muted); font-size: 0.85rem; }
.kv dd { margin: 0; }

.table { width: 100%; border-collapse: collapse; font-size: 0.9rem; }
.table th, .table td { text-align: left; padding: 0.45rem 0.6rem; border-bottom: 1px solid var(--border); vertical-align: top; }
.table th { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.03em; color: var(--muted); }
.details { background: #0f172a; color: #e2e8f0; padding: 0.5rem; border-radius: 6px; font-size: 0.75rem; max-width: 420px; overflow: auto; }

.work-list, .plain { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0.75rem; }
.work-item { border: 1px solid var(--border); border-radius: 8px; padding: 0.9rem; background: #fff; }
.work-item-header { display: flex; align-items: center; gap: 0.6rem; flex-wrap: wrap; }
.work-item-header h3 { margin: 0; }

.timeline { list-style: none; margin: 0.25rem 0 0; padding: 0; border-left: 2px solid var(--border); }
.timeline li { position: relative; padding: 0.25rem 0 0.5rem 1.25rem; display: flex; flex-direction: column; }
.timeline-step { position: absolute; left: -0.7rem; top: 0.3rem; width: 1.2rem; height: 1.2rem; border-radius: 50%; background: var(--primary); color: #fff; font-size: 0.7rem; display: grid; place-items: center; }
.timeline-action { font-weight: 600; }
.timeline-meta, .timeline-details { font-size: 0.8rem; color: var(--muted); }
.stops { padding-left: 1.25rem; }
.stops li { margin: 0.3rem 0; }
.freshness { display: inline-flex; gap: 0.4rem; align-items: center; flex-wrap: wrap; }

.tabs { display: flex; gap: 0.25rem; flex-wrap: wrap; border-bottom: 1px solid var(--border); }
.tab { background: none; border: 0; border-bottom: 2px solid transparent; padding: 0.5rem 0.8rem; font: inherit; cursor: pointer; color: var(--muted); }
.tab-active { color: var(--primary); border-bottom-color: var(--primary); font-weight: 600; }

.map-wrap { position: relative; border: 1px solid var(--border); border-radius: 8px; overflow: hidden; background: #e5e7eb; }
.map { width: 100%; }
.map-legend { display: flex; gap: 1rem; padding: 0.4rem 0.75rem; font-size: 0.8rem; background: #fff; border-top: 1px solid var(--border); flex-wrap: wrap; }
.map-legend i { display: inline-block; width: 10px; height: 10px; border-radius: 50%; margin-right: 0.3rem; }
.map-marker { width: 14px; height: 14px; border-radius: 50%; border: 2px solid #fff; box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.3); cursor: pointer; }
.map-marker-stale { opacity: 0.5; border-style: dashed; }

