      loadedRef.current = false
      setReady(false)
    }
  }, [])

  useEffect(() => {
    const map = mapRef.current
    if (!map) return
    const apply = () => {
      const byId = new Map(locations.map((l) => [l.locationId, l]))
      const connFC: GeoJSON.FeatureCollection = {
        type: 'FeatureCollection',
        features: connections.flatMap((c) => {
          const a = byId.get(c.fromLocationId)
          const b = byId.get(c.toLocationId)
          if (!a || !b) return []
          return [
            {
              type: 'Feature',
              properties: { active: c.active, id: c.connectionId },
              geometry: {
                type: 'LineString',
                coordinates: [
                  [a.coordinate.longitude, a.coordinate.latitude],
                  [b.coordinate.longitude, b.coordinate.latitude],
                ],
              },
            } as GeoJSON.Feature,
          ]
        }),
      }
      ;(map.getSource('connections') as maplibregl.GeoJSONSource | undefined)?.setData(connFC)
      const coverageFC: GeoJSON.FeatureCollection = {
        type: 'FeatureCollection',
        features: locations
          .filter((l) => l.active && l.functions.collection_point)
          .map((l) => circleFeature(l.coordinate, l.coverageKm)),
      }
      ;(map.getSource('coverage') as maplibregl.GeoJSONSource | undefined)?.setData(coverageFC)
      const routeFC: GeoJSON.FeatureCollection = {
        type: 'FeatureCollection',
        features:
          routePath && routePath.length > 1
            ? [
                {
                  type: 'Feature',
                  properties: {},
                  geometry: { type: 'LineString', coordinates: routePath.map((c) => [c.longitude, c.latitude]) },
                },
              ]
            : [],
      }
      ;(map.getSource('route') as maplibregl.GeoJSONSource | undefined)?.setData(routeFC)

      markerRefs.current.forEach((m) => m.remove())
      markerRefs.current = []
      const all: MapMarker[] = [
        ...locations.map<MapMarker>((l) => ({
          id: l.locationId,
          coordinate: l.coordinate,
          label: `${l.name}${l.active ? '' : ' (inactive)'}`,
          kind: l.functions.laboratory ? 'laboratory' : 'node',
        })),
        ...markers,
      ]
      for (const m of all) {
        const el = document.createElement('div')
        el.className = `map-marker map-marker-${m.kind}${m.stale ? ' map-marker-stale' : ''}`
        el.style.background = COLORS[m.kind]
        el.setAttribute('role', 'img')
        el.setAttribute('aria-label', m.label)
        el.title = m.label
        const marker = new maplibregl.Marker({ element: el })
          .setLngLat([m.coordinate.longitude, m.coordinate.latitude])
          .setPopup(new maplibregl.Popup({ offset: 12 }).setText(m.label))
          .addTo(map)
        markerRefs.current.push(marker)
      }
      if (focus) map.easeTo({ center: [focus.longitude, focus.latitude], zoom: Math.max(map.getZoom(), 12) })
    }
    if (loadedRef.current) apply()
  }, [ready, locations, connections, markers, routePath, focus])

  return (
    <div className="map-wrap">
      <div ref={containerRef} className="map" style={{ height }} role="region" aria-label="Live map" />
      <div className="map-legend" aria-label="Map legend">
        <span><i style={{ background: COLORS.laboratory }} /> Laboratory</span>
        <span><i style={{ background: COLORS.node }} /> Node</span>
        <span><i style={{ background: COLORS.sample }} /> Sample</span>
        <span><i style={{ background: COLORS.worker }} /> Worker</span>
        <span><i style={{ background: COLORS.origin }} /> Origin</span>
        <span className="map-attribution">
          Map data ©{' '}
          <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">
            OpenStreetMap contributors
          </a>{' '}
          · offline Protomaps tiles
        </span>
      </div>
    </div>
  )
}

function emptyFC(): GeoJSON.FeatureCollection {
  return { type: 'FeatureCollection', features: [] }
}

function circleFeature(center: Coordinate, radiusKm: number, steps = 48): GeoJSON.Feature {
  const coords: [number, number][] = []
  const latR = radiusKm / 110.574
  const lngR = radiusKm / (111.32 * Math.cos((center.latitude * Math.PI) / 180))
  for (let i = 0; i <= steps; i++) {
    const t = (i / steps) * 2 * Math.PI
    coords.push([center.longitude + lngR * Math.cos(t), center.latitude + latR * Math.sin(t)])
  }
  return { type: 'Feature', properties: {}, geometry: { type: 'Polygon', coordinates: [coords] } }
}

